/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231107-6","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"区民委員会","time":"午後 １時００分～午後 １時２６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"しながわシティランの検討状況","agenda":"しながわシティランの検討状況","exchanges":[{"speaker":"えのした委員","kind":"確認","question":"５、今後の主な予定の（１）大会公式ロゴマークの公募は、その辺はどうなっているのかなと。もう１点、（４）プレ大会・記念イベント、そちらだけ確認を。","respondent":"三井スポーツ推進課長","answer":"大会公式ロゴマークの公募ですが、現在検討しているのは、区内在住・在勤・在学の小学生以上ということで予定しております。（４）プレ大会・記念イベントですが、できればプレ大会とは別にできないかということで、今検討を進めているところになります。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"区民のシビックプライドの醸成を図るという目的が書いてあるのですけれども、これはやはり区民のみの対象ということなのかというところ。その辺りを説明するよう求めました。","respondent":"三井スポーツ推進課長","answer":"募集時期についてはまだ検討中で、来年９月頃から大体１１月までということで、まだ検討し切れていないところになります。対象ですが、基本的には区民優先ということは考えているのですが、区民に限らずということは考えております。","id":"exchange-002"},{"speaker":"横山委員","kind":"確認","question":"幾つか伺っていくのですけれども、まず別紙１なのですが、役割分担の違いを教えていただけたらと思いました。１１の参加料なのですけれども、この参加料を算出した根拠というか、この辺りを確認したいと求めました。","respondent":"三井スポーツ推進課長","answer":"次に、ジュニアラン、ファミリーランのイメージですが、こちらもまだ検討中です。今後、他自治体なども参考にしながら、これから検討していくことになっております。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"２０２０年９月の定例会の一般質問で、東京２０２０大会の前の段階だったのですが、群集マネジメントについてお伺いしたことがありまして。群集マネージャーみたいな方からご意見をお伺いしたりですとか、現在の群集マネジメントに関する部分の検討状況を説明するよう求めました。","respondent":"三井スポーツ推進課長","answer":"具体的に群集マネジメントという言葉で特に検討しているところはないのですが、実際にコンサル等が入りまして、２,５００人がしながわ区民公園スタートで旧東海道を走っていくというルートは、狭いルートにもなるので、そこの誘導等はしっかり考えていきたいと考えております。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"例えば花火大会ですとか、大きなイベントの際に、群集マネジメントの動線を事前に考えているか、いないかというところで、大きな事故につながる可能性をすごく軽減できるかと思いますので、ぜひ引き続き検討を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問","question":"では、私からも１点質問させてください。いろいろあると思うのですが、どのような企業にどのような募集、声掛けをされていく予定か尋ねました。","respondent":"三井スポーツ推進課長","answer":"これから協賛を募るためのメニュー案等を今検討しているところでして、それについて、基本的には区内の企業等を考えております。実行委員会の中に東京商工会議所品川支部の方たちにも入っていただいていますので、そことも連携しながら進めたいと考えております。","id":"exchange-006"},{"speaker":"山本委員","kind":"意見","question":"そういうサポートなり協賛があったりすると、またより華やかになったり、そういった視点からも検討を進めてほしいと求めました。現物でのサポート等、いろいろな協賛の仕方があると思いますので、そういったところにも工夫など、ご検討いただければと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"別紙１の１１、ファミリーランのところに「ペア」と記載されているのですけれども、これは何人までとか、ペアというのは、親と子だけれども、お子さんが２人いる場合とか、そういうときはペアというこの表現はどうなのかなと思い、伺いたいと思います。","respondent":"三井スポーツ推進課長","answer":"こちらもこれから詳細を詰めていく中で変更はあるかもしれませんが、同伴は可能にしようかというような検討も含めてしているところで、そういう検討を今進めているところになります。","id":"exchange-008"},{"speaker":"せらく委員","kind":"質問","question":"ロゴマークの公募について伺いたいのですけれども、今月下旬から公募を始めるということで、このロゴマークは今回限りのマークになる予定でしょうか。今後ずっと使うのかということを聞きたいのと、あと、公募の周知方法もお聞かせほしいと求めました。","respondent":"三井スポーツ推進課長","answer":"１回だけで終了というよりは、しながわシティランで今後も使う公式ロゴマークということで公募する予定で進めております。今考えているのが、区内の学校など、そういうところにもチラシをまきたいと考えております。","id":"exchange-009"},{"speaker":"せらく委員","kind":"質問・要望","question":"まだコース案なのでこれからだと思うのですけれども、そういったところもスムーズな動線を確保してほしいと求めました。これは意見というか、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2972#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":8545,"voices":36}},{"id":"r05-20231107-7","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"厚生委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それから、4)のところでも課題整理というのが書いてありますので、ここも併せて伺いたいと思います。どう違うのがあるのか、どういう形で進められようとしているのか、まずその辺りから教えてほしいと求めました。","respondent":"東野福祉計画課長","answer":"これが一例ですが、そういったケースが幾つかございまして、それに対応するのが、品川区として重層事業の中で対応しているような一つの例です。いろいろなところが連携した形で、解決の糸口を探していく、そのような連携を取っていきたいという考えです。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"困難な事例についてはケース会議をやっていくという感じも、品川でもそういう形でやっているということでいいのでしょうか。どういうところが関わっているのかということを伺いたいのと、それから、どれぐらいのケースがされているのかも伺いたいと思います。","respondent":"東野福祉計画課長","answer":"そこから上がってきたものについて、それについての支援に対して、どう考えていくかというのをケース会議の中で話し合うということにしております。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"そういうところに行くかなという思いはしているのですけれども、第一の相談窓口みたいなものは、品川区としてはどう考えられているのか。それぞれのところで動いてもらって、重層的支援というのが機能していくことになるのか、その辺のイメージも併せて伺えたらと思います。","respondent":"東野福祉計画課長","answer":"これまでも区としては、そういった方への対応をどうするかというのは、実はやってきたところです。具体的な仕組みとして、この重層事業の取組を進めていく中で、それを吸い上げるような仕組みをつくっていこうというのが重層事業の目標です。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"職員向けの研修というのも書かれているのですけれども、これはどこの部署の職員に、どのような研修がされるのかということも伺いたいと思います。国からの補助金というのが出ている部分があるのか、出ているのであれば、どこにどういう形でどれぐらい出ているのかということも伺いたいと思います。","respondent":"東野福祉計画課長","answer":"そういったところと連携した形で、今後それを広めていくということが必要だと考えております。推奨しているという部分がありますので、そういった補助金なども利用しまして、今後も進めてまいりたいと思います。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"福祉計画課が担うのであれば、そのための職員体制というのもつくられているのか、その点についても伺いたいと思います。その中で、２０代・３０代のひきこもりの実態とか、区としてはどのような取組をされようとしているのかについても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"こちらに取り組んでいるわけですが、今後、きちんと職員体制につきましては要望していきたいと考えているところです。そのアンケートだけで把握できるかは分からないのですけれども、そういった取組から、まず始めていきたいと考えているところです。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"最後、１点だけいいですか。では、皆さんの後にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問","question":"ケース検討の会議で８件、令和５年度にされたということで、少しずつ会議等も進んでいてよかったなと思っています。このケースに関係するところがやっているのか、もともとケース会議はこのメンバーというふうに固定されているのかという点を説明するよう求めました。","respondent":"東野福祉計画課長","answer":"福祉施策に取り組んでいる福祉部の各課でありますとか、それから、こちらの健康推進部のメンバーなども入っているところです。先ほども少しご紹介させていただきました子ども家庭支援センターですとか、保健センターといった出先のメンバーも入って、検討を進めております。","id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問","question":"そのケースについて何かないですかと聞けるというのがあるから、視察に行ったところはわざと月に２回開催、コーディネートするのがすごく大変だと。プロフェッショナルの１人の人をつくるのではなくて、そのようなやり方はどうかと思うのですけれども、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"委員のおっしゃることはもっともだと思います。本格実施に向けて、各自治体で取り組んでいるようなやり方、今後併せて検討していきたいと思います。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"そういう方を１人置かないとできないぐらいのボリューム感だし、制度の仕組みづくりというところを、特に注力してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"おぎの委員","kind":"質問","question":"全体を見渡せることにはなるので、ある程度固定して、いろいろな部署から出る人をつくったほうがいいのではないかと私も思います。そういったものを広げて、どこまで広げていくという予定とかは、今のところどうなっていますか尋ねました。","respondent":"東野福祉計画課長","answer":"それから、支え愛・ほっとステーションでの訪問活動を行っているという部分で、高齢者については大きくカバーができているかなと思っています。","id":"exchange-010"},{"speaker":"おぎの委員","kind":"質問・要望","question":"表に出てこない方をどうやって支援していくのかは、本当に難しいと思いますが、ぜひやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"あるべき一番効果を発揮するケース会議に、ぜひしていっていただきたいと考えていますので、よろしくお願いします。社会福祉法第１０６条の４によると、現状、重層的支援体制整備事業はどの程度の自治体がやろうとしているのか尋ねました。","respondent":"東野福祉計画課長","answer":"全国的なところということになりますので、今把握している部分というのはございません。今、そういったところがどこまでできているかは別としましても、全国的な取組がされているというところは間違いがないかなと考えています。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"８０５０問題とか、重要になってくるという思いで、こう書かれたのでしょうか。なぜこう書かれたのか、理由を説明するよう求めました。","respondent":"東野福祉計画課長","answer":"今、委員もおっしゃっておりましたとおり、区としては重層事業の中で、孤独・孤立対策も併せた形で取り組んでいくという方針です。今後一緒に推進してまいりたいという考えで、こちらの支援、区が目指すというところにも書かせていただきました。","id":"exchange-013"},{"speaker":"筒井委員","kind":"確認","question":"ということで、孤独・孤立対策を重点的に対策するために重層的支援体制整備事業をやるというわけではないということですか。それを確認でもう一度。","respondent":"東野福祉計画課長","answer":"区が令和３年から始めているもので、地域共生社会のところから派生した重層事業を重点的に取り組んで、そこに孤独・孤立対策を併せて取り組んでいく。そういう順番です。","id":"exchange-014"},{"speaker":"こんの委員","kind":"確認","question":"1)現状と課題というところから、一つ確認させてください。要するに連携なのか、そこに眠っている課題というのは洗い出されたのか、まずそこをお伺いしたいと思います。","respondent":"東野福祉計画課長","answer":"こちらの支援のしづらさにつきましては、それ以外のところへつなぐという部分が、なかなか難しいというアンケート調査の結果がございました。それが一番大きな課題だと考えていますので、その辺を解決するために、こういった事業の取組が必要だと考えております。","id":"exchange-015"},{"speaker":"こんの委員","kind":"確認","question":"今確認をさせていただいた、それ以上のことができないというのは、本当に今まであった。そうしたところの具体的な、最後まで寄り添う人というのはどういうイメージなのか、その辺も説明を求めました。","respondent":"東野福祉計画課長","answer":"ですから、いろいろなところとの連携を強化した上で、重層的支援体制というのをつくっていきたいというのが、今の区の考えです。今窓口で受けた人が対応するのか、例えば訪問したりして対応できるかどうか、そういった対応の仕方を区として考えているところです。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"本格実施は令和７年なので、今日の時点というか、現時点での資料は理解いたしました。この方に支援をしたらどのように進捗状況を連携するというか、情報を共有するものも必要だと思いますが、その辺はどのようになっていますか尋ねました。","respondent":"東野福祉計画課長","answer":"その辺についてはまた検討の余地はあるかと思うのですけれども、今現在はケース会議の検討、それから支援者へつないだ後の体制についてのフィードバックは行っているところです。","id":"exchange-017"},{"speaker":"こんの委員","kind":"確認","question":"こういう方をどう見つけるかというところが大事かなと思うのですけれども、区民にも何か調査をするのでしたでしょうか、その確認です。窓口対応ということも、孤立・孤独の方を察知していくということが大事かなと思うのですが、その辺についてはいかがか尋ねました。","respondent":"東野福祉計画課長","answer":"それから、対応スキルアップツールは、かなりいい制度だと思います。先ほど委員からもお話ありました接遇も含めまして、そういった方が中心になった形での、窓口に来られた人の対応を行っていると認識しております。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"その点について伺いたいのですけれども、５回、６回という形で充実をさせていくという会議がされているという報告だったのです。品川区としては、重層的支援体制をどう構築していくのかというところでの検討が、どこでされているのかということです。","respondent":"東野福祉計画課長","answer":"庁内におきましては、関係している課において庁内検討会というのを年に２回行っております。重層事業はかなり大きな事業となりますので、関係所管と連携しながら進めていくところです。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、推進会議というのは、福祉計画課の中で推進会議というのが持たれているのか、その推進会議のメンバーと、庁内で検討されている課がどこなのかについても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"推進会議につきましては、ケース会議も兼ねた形になりますので、先ほど来お話ししている相談窓口を持っているようなところになってきております。庁内検討会は、今後の方針を決めていくという会議になりますので、そこの部長も入った形で検討しています。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、毎月されている推進会議というのは、多機関協働事業ケース検討を行うところとイコールみたいな形でしょうか。参加されているところを、もう一回だけ教えていただけますか。","respondent":"東野福祉計画課長","answer":"ケース会議も先ほど、２か月に一回とお話させていただいたのですけれども、推進会議につきましては、基本、毎月開催をしております。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"そして、品川区としては、重層的支援体制はこういうことでやっていきますというのがまとまるのは、いつ頃になるのか尋ねました。","respondent":"東野福祉計画課長","answer":"本格実施が令和７年度からということを目指して進めておりますので、取りまとめについては令和６年度、来年度末までにはまとめたいと考えています。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"独り暮らし高齢者の実態というのは把握されているのではないかと思うのですが、高齢者の独り暮らしの実態がどういう形で把握されているのか、その点についてだけ教えてもらえますか。","respondent":"東野福祉計画課長、川原高齢者地域支援課長","answer":"次が来年度行う予定となっておりまして、そこで高齢者のニーズの把握をしています。ただ、年齢的には７５歳以上というところになりますので、後期高齢者以上という形になります。 今月の実施予定につきましては、そして、こちらは９月１０日に実施をしたオレンジフェスタの成果報告会を予定しています。４つだけ主なものを挙げしていますが、実際には１０事業、運動系の予防事業は実施をしています。","id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私から２点お聞きします。助成決定は６１件で、助成数が２２件ということになっているのですけれども、内訳をお聞かせほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"令和４年度からは中学生までに範囲を広げてサポーター養成講座を実施したところ、非常にニーズが高いと感じました。３世代とか２世代でも一緒に、高齢者の状況を知っていただきたいという思いで、新たに開始したところです。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"４,２２３人分を発送して、受診率が５％ということなので、不安だけれども検診に行けないという部分があると思うのです。令和４年から令和３年を引いた数の９２６人が、４３回というのはどんな形で、どういうところでされているのかについても伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"実施していただきました後、今後もどういったところで窓口としてサポーターを増やしていけるかというのを、引き続き考えていきたいと思ってあります。あくまでも１年度で何人ということで、昨年度以上というところでは、今年度も実施していきたいということで考えてあります。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１５０件のうち、助成が決定したのは６１件なのですが、受けられるというのはおおよそ何件ぐらいまでになるのかという件数を教えていただきたい。今後も引き続いて、ぜひやっていただきたいということでお願いしたいと思っているのですが、そのところで区の考えもお聞かせいただけたらと思います。","respondent":"川原高齢者地域支援課長","answer":"７月の助成時にも、やはり普及啓発の一環として効果的だったと考えていますので、今後も実施をしてまいりたいと考えているところではあります。引き続き、こちらは実施をしていきたいと考えているところです。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"累計で２万人近くの方が受講されているということなのですが、知識を深めるために受けられている方がどのくらいいるのか、サポーター養成講座を受けられている方はどのような方が多いのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"自分も支援者の一人として、地域の方としての手を挙げて受講している方、様々なところです。実施をしていますので、そういった高齢者の方と接する方たちにも、啓発という意味で講座を受けていただいているところです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"非常に大切なことだと思いますので、ぜひ引き続き積極的に、こうした講座を広めていっていただきたいと考えています。もしくは介護予防サービスの事業として扱うということは検討されているというか、今後どのようにお考えをされているのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"今のところは情報収集に努めているところではありますが、区としても関心を持って、情報収集と検証を図っているところです。脳トレのようなゲームもありますので、そういったところでも活用できないかというのは、引き続き検証を図ってまいりたいと考えています。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"ｅスポーツを取り入れたら参加者が２倍になったということで、ぜひ積極的にやってほしいと求めましたので、ぜひよろしくお願い申し上げます。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"この２つが一番、高齢者の方のやってみたいことという要望で多かったと思います。運動したいという要望があったときに、介護保険に関わる、歯がゆさを感じる方がケアマネジャーに結構いらっしゃるのです。","respondent":"川原高齢者地域支援課長","answer":"私どもの課でスマホ教室を実施しておりまして、その一環として、スマホを使ったゲーム体験というのを試行的に昨年度実施したところです。社会参加にもつながると思いますので、そういった取組も含めていろいろな方面から、検証は引き続きしてまいりたいと考えています。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"４番のところの、高齢者の約８割が元気で活動的な生活を送っていらっしゃるということで、かなり悪い状態で来る方とかもいらっしゃるのです。なぜもっと早く認定を受けて、もう少しこの文言を検討されたほうがいいのかなというところで、要望になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"こしば副委員長","kind":"質問","question":"登録の医療機関が３０か所ありますが、例えば岡山市では、かかりつけの医者を登録していると。その辺り、品川区で今後の検討もあるかと思いますけれども、お考えを教えていただけたらと思います。","respondent":"川原高齢者地域支援課長","answer":"そこには細かく介護と医療の連携ということで、あと、物忘れの認知症サポート医の登録の医療機関というのをずらっと掲げているところです。","id":"exchange-032"},{"speaker":"こしば副委員長","kind":"質問","question":"実際にはもう少し数が多いということで、安心をしました。認知症と診断されたときというのは、そこのお医者さんのほうで今後の診療、治療につながってくるということでよろしいのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"まさに第一次窓口というところで、認知症相談医であるとかサポート医のところ、かかりつけのところで簡単な検査をしていく。その方の進捗と進行の状況によって、各医師が判断をして、適切な医療機関というところにつなげているところです。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいのですけれども、実施回数８６４回、そんなに利用されていないのかなという数字が見受けられるのですけれども。１か所でという人もいるだろうとなると、今の実績も含めて、どのように今後されようと考えているのかを参考までに伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"ご説明の中で書き切れなかった部分でありますが、高齢者の地域の身近なグループで、自分たちでやっていこうと。自分たちでつなげる、介護予防に自分たちで自主的に取り組むというところを、引き続き実施ができればと考えています。","id":"exchange-034"},{"speaker":"こんの委員","kind":"質問","question":"この取組については、今後どのようにフレイル予防というところに関連してくるのですか。いま一度説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"普及啓発イベントの一つとして実施をしたところ、そこに達していない方、幅広い年代でニーズがあるということもつかめました。なので、今後もこういった普及啓発のイベントの一環として、もう少し広い年齢層に実施をできればいいなという形で、検証を今、図っているところです。","id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"この健康チェックというのはこれから大事な事業にもなるのかなと思いますので、どうぞこちらを積極的に推進してほしいと求めました。何かございましたらば、答えるよう求めました。","respondent":"川原高齢者地域支援課長","answer":"ご意見ありがとうあります。は自分たちで何かに取り組むという形の、通いの場への活動へと、さらに広げていければと考えています。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"提案","question":"既にいろいろと提案されていると思うのですけれども、初期集中支援チームというのは実際どういう形で、どれぐらい稼働されているのかも説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"全てをコーディネートしてくださっている認知症の地域支援推進員という方が、そして、企画会議も令和４年度から開始したところでありますけれども。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問","question":"品川区の高齢者地域支援課の中に、初期集中支援チームというのができていたのではなかったですか。初期集中支援チームというのができていたイメージがあったのですけれども、そういう形で今、動いているというわけではないということか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"初期集中支援チームに関しては、高齢者地域支援課と高齢者福祉課との連携というのも図っているところでございまして、実際の実施状況は。今後の在り方を検討しているところです。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3674#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":38009,"voices":97}},{"id":"r05-20231107-8","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"建設委員会","time":"午後 １時００分～午後 ４時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件整理しています。","topics":[{"id":"topic-01","title":"京浜急行バス株式会社のバス路線における系統廃止","agenda":"京浜急行バス株式会社のバス路線における系統廃止","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そういった状況も伺いたいと思いますし、ここで１便しか出ていないのかどうかという、状況を伺いたいと思います。その意見聴取の返答というのですか、そういう答えというのは何かあるのかどうか、それはどういった内容なのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"冒頭ご説明した、これが１便というような、廃止の３ルートの状況です。例えば関東運輸局から回答が来るですとか、あるいはバス事業者から回答が来るということは、回答というところは特にございません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"求めたところで見ますと、区の考える影響というのは、どういったものがあると考えているのか伺いたいと思います。意見の中でも、減便や既存路線の再編等を検討していただきたいということで求めていますので、そうしたところの区の考えも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区の意見に対しての回答といいますか、冒頭ではご説明したのですが、令和５年の１０月１９日付で運輸局より路線の廃止に関する通知が届いてあります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"代替手段としてはりんかい線ということで、それも確かに一つの手段であるとは思うのですけども、この路線がなくなることの影響があると考えているというところですので、大田区などとも協力して、路線の再検討などを求めるべきではないかなと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"検討いただけないかということで意見は出させていただいたですが、これは運輸局のホームページにも公表されておりますが、関係自治体として。公表されておりますが、特段大田区のほうでは意見なしということで、意見の聴取が出されているです。","id":"exchange-003"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認をしたいと思いますが、いろいろと交通機関を総合して今のコミュニティバスという形の路線を決めたと思うのです。廃止になるということでは、またそのときの分析状況が変わってくるかと思うのですが、その影響はどういうふうに考えられておりますか尋ねました。","respondent":"鈴木都市計画課長","answer":"１１の指標で点数化をして、導入効果が高い地域というのを３地域抽出していますが、影響は多少出てくるのかなです。廃止の路線本数とすると１８便ですので、それほど、当時の検討結果に何か大きく変更が加わるようなものではないのかなという受け止めです。","id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"コミュニティバスの検討の中での影響はないというのが確認できたと思いますが、この路線を見ると、ただもったいないなという感じはします。それを、ではコミュニティバスがどういう補完をしていったらいいかというのが今後出てくるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"いわゆるバス路線の廃止については品川区は、運送事業の関係なので国交省マターですから、直接は関わりはないということなのだろうと思います。１時間に１本しかないとかですから、事業ですから、法律上どういう扱いになるのかというところをお聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"補助第２６号線の新設路線のお話をいただきましたが、しっかり考えていきたいというようなことは、推移を見ているというような状況です。廃止みたいな、そこは常に意見交換をさせていただきながら、東急バスの増便につながるような要望は引き続き行っていきたいです。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"補助第２６号線は東急ということで、区民のサービス向上につながるような視点で取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"２番目の、具体的に教えていただきたいのが一つと、これはどういうことかお聞かせほしいと求めました。これまで、いわゆるこういう路線バスの廃止については、この品川区内、３社かな、廃止はあったのか尋ねました。","respondent":"鈴木都市計画課長","answer":"改正後は１１時間以上空けなければいけないとか、この国の方針の下に行われているところですが、そこは聞こえてくるところです。今回こうした手続が行われる廃止はある意味、私の知る限りでは、６年間の間では初めてかなです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"約２４万人で、最初に設定をした京急の目的というのですか、今日になって約２４万人まで落ち込んできたと。需要が減ってきたということについての原因とか要因というのは、バス会社から聞いておられるかなと、それをお聞きしておきたい。","respondent":"鈴木都市計画課長","answer":"井３０という路線の運行が開始されたのが平成９年の９月１日からというところで、まちづくりの進展に合わせて運行を開始し、系統としてはその後。２０１８年と２０２２年の比較で、その７７％よりもさらに落ちる５９％というような状況ですから、会社としては判断したのかなです。","id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"それで、知らない、そういう報告がないうちに、ないままで当然廃止されていたのも、これまであったと。いわゆるそういう公共交通的なところの要素として何ができるのかというところはまた、見詰めていきたいなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-02","title":"「品川区空き家等対策計画の中間見直し」（素案）について（パブリックコメントの実施）","agenda":"「品川区空き家等対策計画の中間見直し」（素案）について（パブリックコメントの実施）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この不適正管理状態というのがどういう状況なのか、管理不全空家というのが、具体的にどういう状況なのかというのを伺いたいと思います。昨年と比べると７件増えているのですが、実際には７件増えているということで、これはどういう計算なのかというのを伺いたいと思います。","respondent":"竹田住宅課長","answer":"幾つか例を挙げてご説明しますと、建築物が２０分の１以上傾斜した場合、傷むことが認められる状態。この傾向が続けば、徐々に空き家数は減っていくものと考えています。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"それで、先ほどの数のところは、空き家はそうなのです。私も計算してそうなったので、それは分かったのですけども、不適正管理の数がどういう計算で出されているのかというところを伺いたいと思います。","respondent":"竹田住宅課長","answer":"私どものほうで、５４１のうち９７件程度が近隣の方に悪影響を及ぼしている空き家であるというふうに認識しまして、９７という数を記載しています。３０減らしても４０増えたりとか、一直線ではございませんが減る方向で今、推移しているという状況です。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"改善されたのは３６戸あるので、昨年から見ると９０から９７に７戸増えているというのはどういう計算で出されているのかというのを伺いたいです。いかがか尋ねました。","respondent":"竹田住宅課長","answer":"下から２段目の居住確認または除却された数の中に、一番下の不適正管理状態から改善された空き家が含まれている表です。令和４年度ですと５４１のうち、幾つ不適正管理状態なのかということで、私どもが認識している数が９７というふうに認識しています。","id":"exchange-013"},{"speaker":"のだて委員","kind":"提案","question":"今回、初めてこの目標の数値を決定したということで、それに至った経緯ですか、前回決めなくて今回決めたというところを伺いたいと思います。全体としては荏原地区が多いということなのですが、この大井地区がこれだけ多い理由について、区の分析を伺えたらと思いますとの意見を述べました。","respondent":"竹田住宅課長","answer":"ご検討いただいてからご回答いただく場合が多うございまして、おおむねなのですけれども４分の１ぐらいが解決につながっているところです。空き家になっている戸建ての４分の３超が、昭和５５年以前、空き家の割合も多くなっているのではないかというふうに推測しております。","id":"exchange-014"},{"speaker":"のだて委員","kind":"提案","question":"そこの民間の提案が活用された件数でいいのかという確認と、実際どういった活用をされたかというところを伺いたいと思います。この定期的な修繕を行う際に、助成というのを区としてやるべきではないかなと思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"空き家は、それ以外にも倉庫で活用したりとか様々な活用方法を考えて、負の財産にならないように行政としても取り組んでいきたいと考えています。基本的に空き家も私有財産ですので、所有者の方の責任の下、維持管理していただくというのが基本だと考えております。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"耐震性のところがちょっとそれがあったか分かりませんけれども、と思いますので、そこはぜひ活用できるようにしていただきたいというふうに思います。様々、環境への配慮など重要だと思いますので、そうしたこともぜひ今後考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"だから改正になっているのでしょうけれど、これを誰がどのように周知させるのでしょうかということです。これは住宅課がやるのか尋ねました。","respondent":"竹田住宅課長","answer":"で、そういった方々に、相談してみようというようなお気持ちになっていただけるような働きかけを今後も続けていきたいと考えています。もちろん、住宅課でも広報紙やホームページに載せる等々、何ができるか知恵を絞っていきたいと考えております。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"何件ぐらいあるのでしょうかということと、それに対しての手間、これ真剣にやろうと思ったら人が足りないのではないのですかと私は思っているのです。だけど、この辺のやり方、今後の検討というのはいかがな状況になっていますか尋ねました。","respondent":"竹田住宅課長","answer":"先ほど空き家が５４１戸ということをご紹介したのですけれども、近隣の方から情報提供いただいて、年間１,０００件ぐらいになるという現状です。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今の現状でいいのですか、現実としてこのままでいいのですか。区民の皆さんの啓発をしていくのは、非常に大切なことではないかなと思うのですが、この２点だけ最後にお聞きしたいと思います。","respondent":"竹田住宅課長","answer":"さらに、新たな分野に挑戦していこうということも考えながら、今、予算組みのほうを考えておりますので、人員も含めて、まさに今検討しています。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"今までの議論というかご説明を伺うと、この中にしっかり盛り込んでいくべきではないのかなと私は思うのですが、どこに力点を置かれているのかというのをお聞かせほしいと求めました。","respondent":"竹田住宅課長","answer":"所有者や相続人の方のお話を聞いていると、売却したいけども売却できないというお話は、さほどお聞きしないのです。その２点が最も重要と考えておりますので、そこに重きを置きながら、空き家対策を進めていきたいと考えています。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"居住確認または除却された空き家の数として、居住確認が取れたということは、いわゆる不適正管理状態から脱したということなのでしょうか。もう壊して更地にしたということだと思うのですが、その数と居住確認された数を一緒にする意味が、そこをまずお聞かせほしいと求めました。","respondent":"竹田住宅課長","answer":"先ほどの説明がよろしくなかったので改めてご説明するのですが、不適正管理が７件増えているという表の見方をしていただければと思います。説明が悪くてすみません。","id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"ここからつくる数字を生かすという意味では、分けたほうがいいのではないかなと思えるのですが、いかがでしょうか。令和４年は３６件で、不適正管理から改善する数を４０に目標を定めるということで、その辺はいかがですか尋ねました。","respondent":"竹田住宅課長","answer":"スペースの関係で一緒にしてしまったのですが、今後は、どういった記載の仕方が分かりやすいか検討させていただきたいと思います。決して軽んじるということではなくて、それも十分、念頭に置きながら進めていきたいと考えています。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。何というのでしょうか、パブリックコメントを求めることの必要性は当然あるわけですが、そこに対して何を期待されているかというのか尋ねました。","respondent":"竹田住宅課長","answer":"今回、計画をつくるに当たっては、法改正に当たって、国のほうから基本的な指針、それから必要な指針、ガイドライン等も提示されております。私どもの考える方向性や、５年後には目標自体の見直しもまた、そういったところに向けてのご意見をお尋ねしたいと考えています。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"地権者に名のり出てもらうようなというのでしょうか、そんな質問させていただいたのですが、引き続き取組をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際は９０件で１７件減っているということになるわけですが、それで改めて本紙のほうの２１ページを見ると、そこを確認させてほしいと求めました。","respondent":"竹田住宅課長","answer":"不適正管理でなかった空き家が不適正管理になるケースもあります。下の表の３行目、４行目は一部重複している数が含まれておりますので、分かりにくくなっておりまして申し訳ございません。","id":"exchange-025"}]},{"id":"topic-03","title":"品川区公園施設長寿命化計画の改定","agenda":"品川区公園施設長寿命化計画の改定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認をさせていただきたいと思うのですが、これはどういったものがあるのか、どういったものが多いのかということも含めて伺いたいと思います。併せて、この長寿命化計画の対象にならない施設というのはあるのかどうか伺います。","respondent":"高梨公園課長","answer":"補修等をしないで使用見込み期間を全うして、ただ、どちらが有利なのかということを本計画の策定の中で判定をしています。予防保全型の管理をすることでそれだけ費用的にもメリットが出るという結果が出ているというご説明です。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった状況にもなっておりますので、そういったところも配慮しながら、ぜひ安全な遊具等にしていっていただきたいというふうに思います。そこの対処の仕方を伺いたいのと、この間、そうした老朽化などで子どもたちが事故に遭ったとかといったことはあったのかどうか伺います。","respondent":"高梨公園課長","answer":"一定の使用見込み期間を設定してそれの中で計画的に何年後に補修をしたほうがいい、言わば机上の計画というような形にはなってあります。まだまだ寿命はあるのだけども緊急的に対応が必要な、不適切な対応、すぐに替えなければいけないというような状況があります。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういったことがないように、適切に管理、保全をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えてほしいのですが、こういう遊具であったり、いろいろするときに、減価償却という考えもあると思うのです。その兼ね合いの中でこの年数というのはどういうふうに考えながら設定していっているのかなと思うのですが、整理してほしいと求めました。","respondent":"高梨公園課長","answer":"それぞれの公園施設によって、使用見込み期間ということで計画の中では呼んでいますが、その遊具が使われるべき期間はそれぞれ異なってまいります。使用見込み期間が過ぎたからもうどんどん新しいものに替えていくというよりは、それが１２年、１５年というふうに使っていく。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"財政上の計算の仕方であったりとか資産の考え方とかというのは、関係してくるのではないのかなと思うのですが、その辺はいかがですか。もしも担当が違ったら別に構わないです。","respondent":"高梨公園課長","answer":"必要な区の公園施設たる資産だという認識で、区のトータル資産が減ってしまうというようなところはちょっと考え方としてなじまないのかというところは、所管としては感じるところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"長寿命化というのは当然の流れになってくるので理解はできるのですけれども、これは別な機会でお聞かせいただきたいというふうに思っております。補修していくというのは当然必要だし、管理が強化されるということになると理解しておりますので、その辺をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"私が１期目だったか２期目の頃に中央公園ができまして、だからということではなくて、そういう過去の事例もありましたと。一生懸命思い切り遊びたいというものはどうしても頻度が高くなってしまって、天然芝のことも、もしあればですがお聞かせをほしいと求めました。","respondent":"高梨公園課長","answer":"一つ考え方の軸をもって、維持管理を行っていくということは、区としては取り組まなければいけない大切な部分なのかなというふうに思ってあります。１年に１回やってありますので、機動的に安全確保の対策を取っていきたい、このように考えているところです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"総論としての長寿命化、大賛成であり、また、個々においては利用頻度とか、また、一方での安全性もしっかり踏まえた上でぜひお願いしたいと思います。今回の９５０万円余というのは、さらに増えたものなのかどうなのか、ちょっとその辺の比較をお聞かせいただきたい。","respondent":"高梨公園課長","answer":"今回は、先ほど説明しましたとおり令和５年度、９５０万円余です。１０年前との比較でもご説明しましたが、今回その縮減効果については約３分の１ほどに圧縮されている、このように分析しています。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"新たな９５０万円余が出てきたということは、物すごくすばらしいことだと思いますので、ぜひ不断の努力を継続してほしいと求めました。ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"推し進めていただきたいのと、危ないからとなくなってしまって、相当自分の中ではショックだった出来事の一つであったのです。譲り受けたどこかの都市があるでしょうから、例えばそういったものの考え方というのですか、そういうのを説明するよう求めました。","respondent":"高梨公園課長","answer":"公園施設を基にした、例えばほかの自治体との連携だったり、公園施設から発する展開というようなところまでは踏み込んだ計画ではございません。それをスタートとしての様々な幅広い展開等についても、関連部署と連携の上、取り組んでいきたいなと考えているところです。","id":"exchange-035"}]},{"id":"topic-04","title":"公園児童遊園等維持修繕工事における未精算金の発生","agenda":"公園児童遊園等維持修繕工事における未精算金の発生","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の単価契約工事、これはどういうものなのか、仕組みを伺いたいと思います。それと、今回のこの未精算金の発生という事態、これが課長に報告が上がる前に、公園課の職員は何人の方が知っていたのか伺います。","respondent":"高梨公園課長","answer":"単価契約工事ですけども、この工事はまず、年度の最初に、公園の中で行う維持修繕の各工種の単価を業者と取り決めて契約を行います。全部で１０名の係なのですが、係員によってそれぞれ認識の差はありましたが、係の中では共有をされていたというふうに聞いてあります。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"工事契約のところでは、この単価契約工事というのは、公園課以外ではこうした契約をしているところはないのかどうか、伺いたいと思います。そうした視点も含めて、今後の再発防止策については検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"組織的な問題というのは確かにあると思います。問題点、その重要性についてまず、知っていただくというようなところから課内の教育を再度行っていく考えです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"同じことが起きないようにしてほしいと求めましたし、こういったことがないのかということは全庁で調査をしていただきたいというふうに思います。２年分でいくと５,５００万円ほどだという事態になっているということですので、さらに、しっかりとやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"こういう現状になっていたというのはいつからですかという、ということで２年間なのか、それを教えてください。例えば、１か所に管理する、そういう方向には考えていないのかということをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"細かい事象は聞こえてまいりましたが、適切な時期までに書類を整えられなかったといったところが一番大きな部分であるというふうに考えるところです。","id":"exchange-039"},{"speaker":"西本委員","kind":"確認","question":"確認しなければいけない事象というのはとてもたくさんあると思うのです。担当にあれどうなっているの、これどうなっているのというぐらいの確認、やはりそれではミスが起きます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"ご説明を伺いまして、ぜひまた、引き続きお願いをしたいと思います。ぜひ、取り組んでいただきたいと思うのですけども、ちょっとこの部分だけ感想をほしいと求めました。","respondent":"高梨公園課長","answer":"あれ、トリプルチェックという形で、こういった電子媒体等をうまく利用しながらやっていこうという話合いはもう既に進めさせていただいています。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"大体１０名ぐらいの方で共有をされていたというお話があって、それはいつから共有されていたのかは明確にお聞きをしたいなというふうに思います。そうすると令和５年度の会計決算に載ってくるのだろうなと思うのですけど、どういった項目でこれが表記されてくるのか、これもお聞きしておきたい。","respondent":"高梨公園課長","answer":"確かに工事施工については令和４年度に実施がされておりますが、請書等の取り交わしもされていない中での工事のみが行われている状況です。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"令和４年度の中で、これは組織的には、その辺も含めてＰＴでしっかり進めてほしいと求めました。本当に電話１本で、もし言えないとしたら、その辺もＰＴで行っていただければというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"仕事を１個飛ばしてしまったときに、どうしよう、やはり言えない人というのはいらっしゃるのです。ではこのチームでどう守っていこうかなという、起こらないような話合いをいかにどうやっていくのかなというのをちょっと教えていただきたい。","respondent":"高梨公園課長","answer":"今、副委員長からお話がありましたとおり、職員の人間性に頼ったシステムというのはよろしくないのかなというふうに思っています。それでこのようなことが起こらないような再発防止をしっかりと含んで、新しいやり方という形で議論してまいりたいというふうに考えてあります。","id":"exchange-044"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問","question":"要は城南地区と言ったらいいのですか、ベイエリアと言ったらいいのですか、品川区内での取組だと思うのです。この水辺の活用、品川区はどのように捉えていくのでしょうか、ということはいかがか尋ねました。","respondent":"北原河川下水道課長","answer":"可能なものがあれば連携できるものをしていくべきだとは思いますし、他の自治体のいいものというのは取り入れていくべきと思っています。水辺の取組を進めてきているのですが、来ていただくという取組が大事だと考えていますので、進めていければと考えているところです。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、これからも推進していただきたいという思いがありますが、もう少し視野を広めていただいたほうがいいのかなという思いがあるのです。そういう方向では何か動きがあるのか、あったら教えてほしいと求めました。","respondent":"北原河川下水道課長","answer":"今回、舟運の社会実験を東京都と連携して実施したというのは品川区だけというところもありますので、そういったところでつながりもありますので。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"一つ一つのイベントについては、最大限やられているなという思いがあるのです。もう少し広げてもらいたいなというふうに、そういうのもこれから勉強していきたいなというふうに思って、意見として言わせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"私の思いとしては、活用するのはいわゆる民間、地元の方が活用する。こういうことの規制を緩和してほしいとか、どちらに聞いていいのかあれですが、あればお聞かせいただきたい。","respondent":"北原河川下水道課長","answer":"まず、そういった方にとってどうやったら使いやすいのかとか、そういう視点で今後は進めていく必要があると思っているところです。利用状況等も踏まえながら、今後は、追加の整備が必要なのか検討していくのが大事なのかなと思っています。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"地元の声として伺っているのは、まず、お伝えをさせてほしいと求めました。今現在の状況については、まだその途上なのだと思うのですけども、いわゆる工事の進捗状況というのをお聞かせほしいと求めました。","respondent":"北原河川下水道課長","answer":"順次進めてきておりまして、建設局との工事の関係で、予定では令和７年度にそこまでやるという形で考えてあります。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"この清流復活事業で落合水再生センターから来る水が、目黒川で言えば流れている。今現在、そういうお考えがあるのかどうか、検討されているのかどうかも含めてお聞かせほしいと求めました。","respondent":"北原河川下水道課長","answer":"過去に、海水を持ち上げてきて、それを流したらどうだという検討をした経緯があります。ただ、今日おっしゃっていただいた視点に近い形で検討はしているのですけども、参考にさせていただけたらと思っています。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"目黒区に水質浄化施設が整備中、下目黒一丁目付近ということなのですが、これは、東京都の施設なのですか、それとも目黒区が単独というか目黒区が主体となって造っている施設なのかというのはどうなのでしょう。","respondent":"北原河川下水道課長","answer":"こちらの施設は、品川区でいう立会川に設置されているものと同じものを目黒区が設置するという工事になっておりまして、やはりそこの辺りが一番泥がたまりやすくて、水質の悪化も著しいというところで、目黒区のほうで設置をするものになります。","id":"exchange-051"},{"speaker":"田中委員","kind":"意見","question":"ごめんなさい、品川区でというのは、月見橋の施設でしたか。品川区のというのは具体的にどういう施設かが、すみませんとの意見を述べました。","respondent":"北原河川下水道課長","answer":"この説明資料の表面の下に、平成２０年度より高濃度酸素溶解水による水質改善を実施ということであるのですが、こちらと同じような施設を目黒区が目黒川で設置するという内容になります。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"行政の果たすべき役割として、地元の利用者の声をぜひ聞いていただいて、有効に活用していただけるように取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"ほぼ同じ場所で、だから、やる規模が違うのかどうか、当時の記録がどういうふうに区でストックされているのか分からない。もやるという、何か目黒区との連携があるのか、まずお聞きします。","respondent":"北原河川下水道課長","answer":"目黒川水質浄化対策検討会というのを目黒区と東京都も入った中でやっておりまして、目黒区としても認識した上で、今回整備をしているものというふうに認識をしているところです。","id":"exchange-054"},{"speaker":"若林委員","kind":"提案","question":"ちなみに、この計画策定体制には東京都は入らないですか。その辺、そういうものなのかどういうものなのか、河川下水道課長にあえてお聞きしたいと思いますとの意見を述べました。","respondent":"北原河川下水道課長","answer":"現在のところ東京都が入って策定していくという予定はないですけれども、今言っていただいた視点、非常に大事な部分だとは思っております。そういうところも含めて検討していきたいと思いますし、結果が出るような形で、可能な限り進めていきたいと考えています。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"計画を立てた後、仕事がスムーズにいくように、東京都との連携は様々な形で模索をしていただきたいなというふうに申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"のだて委員","kind":"確認","question":"令和４年度は約６００回ということだったのですが、現状は年１５０回と書いてあるので、どういうことなのかというところを伺いたいと思います。それと、今回この計画を策定する方向だということで、計画を策定するメリットを伺いたいと思います。","respondent":"北原河川下水道課長","answer":"様々な施設整備を実施してきておりまして、土台となる整備は一定程度、できてきたと考えています。どういった形で一般、あとソフトの取組とどう連携できるかといった、計画をつくることで効果的な事業を進めることができると考えています。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"その周辺での再開発などにつながっていかないようにしていただきたいというふうに思うのですが、そうならないようにしていただきたいと思うのですけども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"あくまで、今回の計画は開発について定めるものではございませんので、直接この計画でそれが進むということは考えてございません。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"いわゆる実験した側の評価というのでしょうか、対応しなくてはいけないポイントがあったのかどうかという、その辺の評価はどうなのかということ。そういう利活用に進まないという課題が多分あると思うのですが、そこへの取組はどうしようとされているのかというのをお聞かせいただきたい。","respondent":"北原河川下水道課長","answer":"舟運社会実験を実施した側としてのどういった評価かということなのですけども、橋が邪魔になる部分もあるので、その辺に課題があるのかなと。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4392#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":58743,"voices":147}},{"id":"r05-20231107-9","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"文教委員会","time":"午後 １時００分～午後 ４時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"令和５年特別区および東京都人事委員会勧告等","agenda":"令和５年特別区および東京都人事委員会勧告等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"どちらがどちらに関わる勧告なのかというのを教えてもらいたいのと、両勧告の意見とも、メンタルヘルス対策の推進等がうたわれていると思います。現場では、学校と幼稚園では、現状どのような対策が取られているのか、伺えればと思います。","respondent":"中谷指導課長","answer":"２点目のご質問のメンタルヘルスにつきましてですが、大変大事であると捉えておりますので、既に配置されているスクールサポートスタッフがあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"誰でも抱え得る問題であるというメンタルについての知識ですとか、あるいは相談できる窓口とか、そういった点の対策という点ではいかがでしょうか。お伺いします。","respondent":"中谷指導課長","answer":"月の超過勤務時間が、一月当たり８０時間を超えてしまったような場合は、必ず産業医の方の面接を受けるということになっております。それを超えなかったとしても、いつでもご自身が希望する場合は受けることができるという環境を整えてあります。","id":"exchange-002"}]},{"id":"topic-02","title":"令和５年度（６年度採用）品川区立学校教育職員採用候補者選考状況","agenda":"令和５年度（６年度採用）品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２点お伺いしますが、その辞退の中身というのがもし分かれば教えていただきたいというのが１つと、在籍者数が２５名というところだと。今回５名程度採用という報告だったと思うのですけれども、内定者が６名ということなのですが、これはなぜなのかというのをお伺いしたいと思います。","respondent":"中谷指導課長","answer":"今年度４月１日時点では５名程度の募集とさせていただいた経緯については、ご指摘いただいたとおりです。結果としてはプラス１となる６名程度を採用していくということが妥当であるという判断をしたため、今回は１人増えているという状況です。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"当日何も連絡しないで来ないのだと、少しびっくりしたのですけれども、なかなか厳しい状況だと思います。総合的にプラス１ということで、そこら辺、理由をお伺いしたいと思います。","respondent":"中谷指導課長","answer":"辞退者についてなのですけれども、確かにこれまでの経緯の中で、採用の内定をさせていただいた後に辞退者が出るということが発生しております。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"意見","question":"９年の一貫教育、それこそずっと品川の先生でいていただけるように、支援をぜひよろしくお願いしたいと思います。ぜひそれを追いかけてというか、教員が５年１０年のときに有意義な気持ちを持っていただけるように、追いかけていっていただければいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-03","title":"令和５年度品川区学力定着度調査および令和５年度全国学力・学習状況調査の結果","agenda":"令和５年度品川区学力定着度調査および令和５年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の分からないところを伺いたいのですが、６番、何が違うのかというのを伺いたいと思います。","respondent":"中谷指導課長","answer":"そして、全国学力・学習状況調査の同じくグラフの横軸というのは、正答数となっております。正答率と正答数は、換算の仕方が違うものにはなりますが、見方としては同じものであると解釈いただければと存じます。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"品川区のほうの６番のところのグラフについてお伺いしたいのですけれども、それが７年生から９年生に進むと、お椀形になっていると思うのです。こちらはなぜそうなっているのか、理由などを分析していただいておりましたら、お伺いしたいと思います。","respondent":"中谷指導課長","answer":"先ほど申し上げた、ここについては、こちらをどのようにＡ層のほうに持っていくことができるのか。一番大事なことは、Ｄ層Ｃ層をできるだけ少なくするという、そのための授業改善というところが最も大事になると考えております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜそうなるのかというのを、品川区として区教委としてどのように分析しているのか伺ったので、教えてほしいと求めました。これもよく分からなかったので、もう少し教えてほしいと求めました。","respondent":"中谷指導課長","answer":"一貫教育の９年間の中で、毎時間の授業の中で指導者がしっかりと振り返りながら改善を図っていくというところが大事になってくると考えています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"別に聞いているだけで楽なわけですから、学びの主人公になるし、一人も孤立させない学びを実現することにつながっているという指摘があるのです。少し伺いたいのですけれども、これを整えているのかというのを伺いたいのが１つと、いかがか尋ねました。","respondent":"中谷指導課長","answer":"やはりどの授業でも自分の考えを発表する機会をつくらなければならないし、指導者側にもやはり再認識をしていただきたい。こういった研究校の取組を行く行くは品川区の全ての学校に広めて、共有できるというような段取りで進めていきたいと考えています。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私から、２点、質問します。学校に対して、理科に関しての指導方法の改善を指導課としてはどのように行っていくのか、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"教育検討委員会という組織を持っておりまして、共有させていただいて、次年度にどうつなげていくかということを話し合っていきたいと思っています。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問","question":"２点お伺いします。されているのであれば、その傾向はどうなっているか、説明を求めました。","respondent":"中谷指導課長","answer":"直接、現時点では提供ができないというお答えをいただいたところがあったので、そのようにそのまま書かせていただいたという経緯があります。それ以外にも、学校の平均と比べたりというようなことはできておりますので、そこを申し添えさせていただければと考えています。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問","question":"７年生のときにそうだったけれども、８年生のときには、その学校がよくなったりするときもあるわけではないですか。全体的に底上げにもつながっていくのだと思うので、その辺が、だからしっかり各学校との連携が取れているのかというのを最後に説明を求めました。","respondent":"中谷指導課長","answer":"もう一つで、先ほど申し上げた教育検討委員会の中で、その中でいい取組というのを積極的に出していただくようにしています。特に理科も少しずつよくなっている、先ほど申し上げたような傾向も含めて、しっかりお伝えしていきたいと考えています。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今タブレットでいろいろ子どもたちも習っていて、タブレットでの履歴を追っていけば、結構面白い結果というのが出てくるわけです。ぜひそういったいい事例をうまく広げていっていただきたいと思うので、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"２項目調査されていると思われるのですけれども、２つ目の生活習慣といったところで、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"例えば、テストで間違えた問題を後でやり直していますかなど、そういった家に帰った後の行動について聞くようなものもあります。今、こちらに関しては、生活習慣や学習環境に関する調査の質問出しは資料の中にはないというところをご了承いただければと思います。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"統計は取っていらっしゃると思われますけれども、どちらの両面についても、円滑に分析しながら対策を取り続けていってほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは２点お聞きしたいのですけれども、１点目が、そこは具体的にどうやって取り組んでいくのかというところを教えてください。設問のところの出し方というのはどういう状況なのかと思って、そこを教えていただきたいです。","respondent":"中谷指導課長","answer":"やはり８年生のところでぐっと低まると思うのですけれども、そこをしっかり整理していけるかという一つの山が、８年生の学習内容になっています。９年間の英語科の教育をやっておりますので、８年生だけに負荷がかからないような、見直していきたいと考えています。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"そこは要望いたします。そこも要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"発注している側としては認識しないと、この結果自体が比較できないと思うのですが、その点はいかがですかというのが１つ。１つ言うと、ＩＣＴのほうはお聞きしたので、説明を求めました。","respondent":"中谷指導課長","answer":"２つ目のご質問で、やはり家庭の中でどう充実していくかというところで、引き続き研究を進めていきたいと思っている先ほどのお話です。ただ、それだけで何かというよりは、やはり理科としての全体の分析が非常に大事であると考えていますので、全てやっていきたいと考えています。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つ目、業者はほかにもあるわけですから、適切な支出になるのかという話になってくると思うのです。それが１つと、どうしても先生がついて教えるような仕組みでないと、その点についてはいかがか尋ねました。","respondent":"中谷指導課長","answer":"こちらにＩＣＴ、タブレットを使いながら、それぞれの教科について学ぶというような学習を進めしています。未来塾のように、地域の方にご支援いただく中で、子どもたちの学びを進めるというような取組が非常に大事であると考えています。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"個人が見せると言えばいいわけですから、未来塾で教えてくださる人との情報共有をできるような仕組みを考えていただきたいのですが、その点はいかがか尋ねました。","respondent":"中谷指導課長","answer":"先ほど、振り返るというところが話題になっておりましたけれども、とても大事だと考えています。子どもにアドバイスをするというところが大事であると考えていますので、充実できるようにということで、働きかけをしていきたいと思います。","id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"子どもたちへのフィードバックというのはどうなっているのか教えていただきたいのと、こういうことが答えられないという状況のどういうあたり。自分でも難しいことを伺っていると思うのですけれども、本当の子どもたちの理解には進まないような気がして伺うのですが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"２つ目の、江戸時代の問題への無回答率の高さというところからは、それぞれの特色を押さえる必要があるというところがあります。しっかり子どもの学びの過程を共有するということが大事かと考えていますので、そういったところに力を入れていきたいと考えています。","id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういう方向で進めてほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"品川区の学力定着度調査と全国の調査のそれぞれの業者名というのですか。それを教えてもらえればと思います。","respondent":"中谷指導課長","answer":"品川区学力定着度調査の業者は、東京書籍になります。それから、全国学力・学習状況調査については、国立教育政策研究所、文部科学省になります。","id":"exchange-023"}]},{"id":"topic-04","title":"いじめ重大事態の発生状況","agenda":"いじめ重大事態の発生状況","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"２年前の重大事態では、この４件、姿勢というのですか。それが何か変わった点はあるのか、伺いたいと思います。","respondent":"米田教育次長","answer":"１点目ですけれども、これは順番として、品川区のいじめ対策委員会が調査結果をまとめてまいります。特に最近取り組んでおりますのは、そういうことについては工夫して、今対応を行っているところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですけれども、そもそもいじめをしようというまず子どもが生まれにくい、そういう学校をつくるためには、どんな取組を行っていくのか。いじめをしようという子どもが生まれにくいといいますか、そういう学校をつくるための取組について伺います。","respondent":"米田教育次長","answer":"いわゆるいじめというのがどういうものがいじめに当たるのかというのは、改めて子どもたちにとっても再認識をしてもらう必要があると思います。いじめの早期発見、早期解決、これを学級の風土の中でもつくっていければというようなことで考えているところです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"いじめの芽というのですか、そもそも子ども同士とか、先生を含む学級集団の中で解決できるという学校をつくっていただきたいと思っているのです。先ほどと同じような答えになるのかもしれないのですけれども、もう一度、そこについてはどうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"確認","question":"１つだけ確認したいのですけれども、１番から４番の発生時期というのが分かれば、お願いします。２番目には、それぞれ認定してすぐに教育長のほうに報告をおおむねする形になっているのか尋ねました。","respondent":"米田教育次長","answer":"いじめの認知が全て重大事態に結びつくというものでもありませんので、基本的には、一定のずれがあるとご理解いただければと思います。やりたいわけなのですけれども、その辺のところはずれも生じているということでご理解いただければと思います。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、今日はお答えは結構ですから、それでお尋ねしたのが１つ。区長部局が聞いていないという話があったわけですから、そこのまた時差というか、それがどういう状況だったのかということをお尋ねしたかったのです。","respondent":"米田教育次長","answer":"前回、既にご指摘いただいています事案につきましては、２つ、私どもの反省点があります。これからも多分今後様々な連携体制を取っていくようになると思いますので、そういうことは念じながら、今対応に当たっているところです。","id":"exchange-028"},{"speaker":"石田（し）委員","kind":"意見","question":"耳打ちという言葉が適切かどうか分からないけれども、区長とその間、話していないわけではないのでしょうと思ってしまうとの意見を述べました。","respondent":"米田教育次長","answer":"今、一つの事例として、委員から挙げられたようなやり方も含め、コミュニケーションは取らせていただいておりますということは申し上げします。ですので、正式な報告も、あれの件が来たねというようなことで、区長部局とは連携を図っているとご認識いただければと思います。","id":"exchange-029"}]},{"id":"topic-05","title":"八潮児童センターにおける公金紛失の対応","agenda":"八潮児童センターにおける公金紛失の対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２万２,１００円全部、どう考えたらいいのかというのが１つと、紛失の原因というのは何だったのか。それは判明したのでしょうかというのをお伺いします。","respondent":"藤村子ども育成課長","answer":"９,９００円のみなくなったというところですけれども、そちらをとった方の意図というのは、こちらでは計り知れません。ボランティア報酬として受領した前渡金について、館長以外の方が金庫の鍵に触れられる状態であったというところがあったのかと考えております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"この紛失の捜査というのですか、その後は継続して行われているということなのでしょうか。伺います。","respondent":"藤村子ども育成課長","answer":"本件に関しては、まだ紛失か盗難かどうか分からないというところではありますが、こちらに関しては、先ほども申し上げましたが、警察に被害届を提出しておりまして、警察で継続して捜査をしていただいている状態になっております。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"確認","question":"１点確認なのですけれども、１８日を挟んで、１９日の動き出しになっている点についてお聞きできればと思っています。２万２,１００円の中から、その辺についてお考えがあれば、お聞きできればと思います。","respondent":"藤村子ども育成課長","answer":"こちら、１６日に紛失が発覚した後にすぐに館長には報告しておりまして、連絡できる職員については内容を聞き取っているところです。１９日の段階で初めて全ての職員がそろって、再度の館内の捜索というところをしたので、こちらの記載になっているというところです。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３番４番で再発防止をするということなので、ぜひ二度と起こらないようにしてほしいと求めました。あるいは、行われなかったとすると、今後、何らかの注意というか、訓告とか、そういうことを行う予定はないか尋ねました。","respondent":"柏原子ども未来部長","answer":"公金が見つからないという状態でありますので、人事上の服務の関係の部分になるといいますか、いろいろなところに当たる部分があろうかと思います。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"懲戒処分ではなくて、そういうことをやるということが、金額の多い少ないではないと思うのです。ですから、そういう措置が出たかどうかぐらいは報告してほしいと求めましたが、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"どのような形になるかはまだ分かりませんけれども、そうした事態が起こった際には、しかるべき話といったのは、処分という言い方はあれなのですが、部署との相談になりますけれども、何らかの形でと思っています。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問","question":"９,９００円というのはどうなるのですか。どうなのだというのがあるのだけれども、今の責任の話ではないですが、この９,９００円を誰がどのように処理をするのかというのを説明するよう求めました。","respondent":"藤村子ども育成課長","answer":"こちらは、紛失か盗難かといった内容のところはまだはっきりしていないところなのですが、そちらの内容がはっきりした時点で、どうしていくかということを検討していこうと思っています。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"確認","question":"１点確認なのですけれども、４番目の(2)、館長が管理しているのですか。鍵の管理。","respondent":"藤村子ども育成課長","answer":"館長から鍵を借りて、金庫の鍵を開けるというような形です。館長が不在の場合は、鍵の置いてある場所から取って、金庫を開けるという形態を取っていたというところです。","id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これはどうしようもないことだと思うのですけれども、今回そのように銀行振込にしたというのは分かるのですけれども、これは本当に残念です。先ほど部長からもご説明あったとおり、今後、こういうことが一切ないように徹底してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"吉田副委員長","kind":"提案","question":"今回、ボランティア報酬の支払いはそうなったとして、ほかにも児童センターにおいての現金の扱いというのは残るということでよろしいか尋ねました。","respondent":"藤村子ども育成課長","answer":"副館長が鍵を扱えるという形にして、２人いれば２人いる状態で、その他の職員が立ち会えば安全性が高いのではないかです。その他、会計管理室のほうでこういった形の今後の対応というところを取らせていただいているところもあるので、提案を踏まえた内容というのが。","id":"exchange-038"},{"speaker":"吉田副委員長","kind":"提案","question":"会計管理者がご提案のシステムにすれば、細かい現金の扱いとか、そういうことについてもミスもなくなると理解してよろしいですかと言ったら。改革が有効に本当に働いていたら、こんなことにならなかったのではないかと思うものですから、その点について伺いたいと思いますとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"今、会計管理室のほうで全庁調査した際も、なかなか資金前渡から振込に対応できるというものは少ないということの結果は出ております。こちらを振込化することによって、今後こういったことがないよう、対策が一つ取れたのかと考えています。","id":"exchange-039"},{"speaker":"吉田副委員長","kind":"意見","question":"過去の監査意見とかを見ても、なかなかなくならないというのがどうしてかと思うのです。どうしてと追及しても、改めて念押しさせていただいて、私からは以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"つる委員長","kind":"確認","question":"そうならないように、毎回、店長とか副店長が現金を確認するのです。この９,９００円、どういう金種がないのかというのが分かれば、参考までに説明を求めました。","respondent":"藤村子ども育成課長","answer":"これまでどおり、しっかり感謝の気持ち等を伝えていきたいと考えていますし、真摯に受け止めてまいりたいと考えています。金種としては、なくなった金種は１,０００円札が９枚と１００円玉が９枚で、合わせて９,９００円というところです。","id":"exchange-041"}]},{"id":"topic-06","title":"すまいるスクールでの仕出し弁当試行結果","agenda":"すまいるスクールでの仕出し弁当試行結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１回でも利用した児童が約１割ということだったのですが、どんな感じなのかというのを伺うのと、どんなところに委託されたのかというのを伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"補助員の方なのですけれども、そういったお子さんの食事に慣れている方というのを２名ほど派遣していただきました。２名来た方につきましては、お弁当が届いたときの引取りですとか、そういったところもご対応していただいたということになっております。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"夏休みですから、昼食を取った方のうち１割がこの仕出し弁当だったのかというのをお伺いしたので、分かれば教えていただきたい。そこら辺はどうか尋ねました。","respondent":"藤村子ども育成課長","answer":"昼食前に帰られた方もいらっしゃるというところですけれども、このアンケート自体がすまいるスクールに登録している方全体に対してのアンケートですので、そこの利用した方が１割いたという形です。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"私はすまいるに通う子どもたちがいかに豊かな育ちの環境というのですか、同時に保護者の子育て支援も行っていくということなのだと思うのです。学校給食でのすまいるの夏季休業中の昼食提供というのは検討すべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"決まった児童の方が基本的には毎日いらっしゃるというところで給食を出しているので、今のすまいるスクールの在り方としましては、適合しないかと考えております。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"やはり課題が何なのかとか、そういうほかの事例がないかとか、様々工夫すればできると思うのです。私は、検討はやはり少ししてみる必要があるのではないかと思うのですけれども、それについては、最後いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"いろいろな事例はあるかと思うのですけれども、こちらのほうとしましても、子ども育成課としてどういった形がいいかというところを検討して今の形を試行したというところですので、まずはこの形を試行して、本格実施というところに動かせていけたらと考えております。","id":"exchange-045"},{"speaker":"ゆきた委員","kind":"意見","question":"子どもたちも、量的にもちょうどいいということで、おいしく食べられている様子を見せていただきました。すまいるスクールのスタッフのよかった点とか、そういった現場からの声があれば、聞かせてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"やはりお母様方から、助かったという声がいただけたというところは、いいかなと話していたということはあります。昼食対応で仕出し弁当の方と、そういった新たな対応というか、もし実施していくのであれば。","id":"exchange-046"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"様々、今後課題が出てくることかと思いますけれども、子育て世代の方々から根強い要望があることですので、今後またさらに引き続き検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"せお委員","kind":"確認","question":"状況も少し確認させていただいた中で、今、ご答弁の中にもあったと思うのですけれども、食べる場所を変えていたのですよね。その準備とかも、すごく早めの時間に集まって、「集まったよね」という確認もきちんとして、上がっていってという。","respondent":"藤村子ども育成課長","answer":"今回試行実施の中でやっているところなのですが、もし本格実施していって、こういった対応は難しくなることは十分に考えられると思います。","id":"exchange-048"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"利用したという人は３３件という読み方でよろしいのでしょうかというのと、もう少し多くの方からの声を伺う必要があるのではないかというのが。調査も当然しておられると思うのですけれども、その辺で特筆すべきようなご意見というのがあれば、教えてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"本格実施というところに移っていく中で、実施していくのであれば、その過程で多くの声を伺っていきたいと考えております。対応した者の反応というところですけれども、今回こういった仕出し弁当の実施をすることによって、お母さん方から喜びの声が聞かれたりですとか。","id":"exchange-049"},{"speaker":"吉田副委員長","kind":"意見","question":"その辺どうなのだろうかというのと、現実問題、そのような全児童に対応したような夏休み給食という方向に行けたら一番いいねと。会派の中では、この利用人数でこのまま広げていくという結論を出すというのはどうなのだろうかという意見があったということをお伝えしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"確認","question":"どうしてここなのですかと聞いたときに、もう一回それを確認したいので、それをクリアしたのでここにするというお話がありました。２３万円かかっていますから、約９００万円から１,０００万円ぐらいの補助員の方の費用が必要になるから、お願いします。","respondent":"藤村子ども育成課長","answer":"校数というのが幾つになっていくかというのは、その後、検討していきたいと考えております。何校実施するかというところは、今検討中の段階なのですけれども、１校で試行を実施したので。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問","question":"拡大するならば、条件をクリアするかどうか検討と。逆に言うと、クリアできないのだったら、やらない小学校も出てくるという認識でよろしいか尋ねました。","respondent":"藤村子ども育成課長","answer":"例えば、そういった環境を確保できる学校があれば要するに実施するというところですので、来年度絶対やらないというようには考えておりません。","id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問","question":"この学校でという話がどうしても出てきてしまうので、そこではなかなかこういう条件でというような説明ができないといけないと思うのです。ぶれるというか、そういうところもあると思うのですが、最後にそれだけお願いします。","respondent":"藤村子ども育成課長","answer":"すみません。仕出し弁当を実施したシャショクラブというところとお話しして、例えば、この条件のクリアというところは考えていきたいと考えています。","id":"exchange-053"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"特別支援児２２０人というのは、それとあと、医療的ケアを必要とする児童が利用している人数というのは何人なのかというのを伺います。それと、特別支援児と医療的ケア児それぞれについて、受け入れに当たってはどのような体制を取っているのか、伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"医療的ケアが必要な方に関しましては、学校に準じた対応を取っているというところで対応しております。看護師を１名つけたり、特別支援の方についても、加配というような対応を取っておるところです。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々議会での要望、現状どうなっているかということと、課題は何なのかを伺いたいと思います。時には一緒に遊ぶということで、このプレイワーカーの役割について、区はどのように考えているのかというのを改めて伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"課題としては、一定の冒険ひろばという形で今実施してきていない状況で、引き続き今検討事項になっているのですが。穴を掘ったりですとか、どんな考えというところになりますけれども、子どもたちの見守りをしっかりしていただいている方たちかと考えております。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"公園として整備をしていただきたいと、改めて要望をさせてほしいと求めました。ぜひ児童センターのほうにも、プレイワーカーの育成を進めながら配置を進めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"プレイワーカーの方については、これは委託でやっている事業なので、特に児童センターのほうに配置というところの考え方ではないので、児童センターのほうにこういった方を配置するという考え自体は今のところございません。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"プレイワークというと、すごくまた狭くなってしまうので、ユースワーカーみたいなものなのですよね。ぜひ現在、冒険ひろば等で活躍されているプレイワーカーの役割などをしっかり把握していただいて、広げていただくよう要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほど安藤委員からも話があったと思うのですけれども、ユースワーカー的な存在がすごく効果的なのではないのかという思いがあります。今後の考え方といったところで、もしお考えがあれば、お聞きできればと思います。","respondent":"藤村子ども育成課長","answer":"そういったところで機能を果たせているかというのがまず１点ございまして、そちらのほうであれば、一つの居場所というのにもなっております。そういった機能を複合的に使っていくという形で対応していけたらと考えております。","id":"exchange-058"},{"speaker":"ゆきた委員","kind":"質問","question":"最後、１点だけ。児童センターの職員の年齢層というか、概算で大体このぐらいの年齢層がいますというのが分かれば、教えてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"児童センターの職員の年齢なのですけれども、以前も委員会で説明さしあげているところがあるのですけれども、５０代より上の職員と、あと、３０代以下の職員というところで、二極化しているというところが今のところあります。","id":"exchange-059"},{"speaker":"せお委員","kind":"質問","question":"中学生からで、もちろん放課後等デイサービスなどもあるのですけれども、そこに週５行くのかという。このアンケートだと１,８２０人、そういう特別支援児の動きというのを把握しているところがあれば、説明を求めました。","respondent":"藤村子ども育成課長","answer":"子ども育成課のほうでは、すまいるに登録されている方ですとか、そういったところは把握しているのですけれども、中高生の方というところまではデータは持っていない形になるので、お答えしかねるところです。","id":"exchange-060"},{"speaker":"せお委員","kind":"提案","question":"まだそんな私からこうしたほうがいいのではないかという提案はできないのですけれども、様々検討していただけたらというのは要望して、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問","question":"様々な自治体の問題点とか、そういうのを遊びながら考えるみたいな、そういう高校生に対する働きかけというのでしょうか。子どもなので児童のことになると思うのですけれども、その辺、何かお考えがあったら。","respondent":"藤村子ども育成課長","answer":"そういった若者の、先ほど申し上げた子ども若者応援フリースペースというのは、どちらかというと生きづらさを持った若者の対応というところなのです。今、委員おっしゃられたように、そういったものを今後検討していければいいかと思っておるところです。","id":"exchange-062"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。分かる範囲で説明を求めました。","respondent":"藤村子ども育成課長","answer":"友達と触れ合ったりというところで、やはり精神的にもいい影響があるということで、ご視察に来られているのかと考えております。１件視察が来たと聞いているのですけれども、内容自体、どういったところを見に来たかというところまでは確認はできていないです。","id":"exchange-063"},{"speaker":"石田（し）委員","kind":"質問","question":"先ほど私が質問した意味というのはまさにそこで、ほかの自治体ではそうでもなくて、結構すばらしいことをやっているという気づきにもなるのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"吉田副委員長","kind":"質問","question":"先ほど児童センター職員の年齢層のご質問があったのですけれども、どういうことを得意分野としておられるのかということを伺いたいと思います。児童センター全体がうまく回るのだけれどもというようなご意見をいただいたので、その辺どのようになっているか、現状を伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"保育士というのがあったり、教員免許を持っていらっしゃって、従事されているという方もいらっしゃいます。一応、どういった資格があるかというところにかかわらず、コミュニケーションをしっかり取っていければ問題ないのかというところで考えております。","id":"exchange-065"},{"speaker":"吉田副委員長","kind":"質問","question":"児童センターというのは、よく、前、私も質問の中でも使ったのですけれども、斜めの関係というのでしょうか。自分の悩みも、そういう場であってほしいというのは思っていますし、ぜひそういう視点も今後の運営で持っていただけたらいいと思っての質問です。","respondent":"藤村子ども育成課長","answer":"職員の方の特性を活かした事業となっておりますので、そちらのいい点を伸ばしつつ、今後も児童センターをしっかり運営してまいりたいと思います。","id":"exchange-066"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"本当にここは私が伺ったときなんかは、見守っているというか、それがすごくその方にとっては楽しみ。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２点質問させてもらいます。毎年やっているのかどうかということと、もう１点は、この抽出というのはどういう抽出をされておられるのかというのをお尋ねしたいと思います。","respondent":"藤村子ども育成課長","answer":"令和３年度はコロナの影響で、アンケート、児童センターのあり方検討というところに合わせてアンケートを実施したという形になっております。区内の小・中・高生等というところでアンケートの回答者、児童センターの利用者からアンケートを取ったという形です。","id":"exchange-068"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これはコロナの令和３年度だから、登録していたのだけれども、自宅で待機しているという取り方でいいわけですよね。学童、児童センターの伸びというのも当然、伸びるということですよねとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"そうですね。次回、もしアンケートを取るという形になった場合には、数値はまた変わってくるのではないかと思います。","id":"exchange-069"},{"speaker":"高橋（伸）委員","kind":"質問","question":"アンケートというのは、例えば、３年に１回とか、５年に１回とか、少なくとも計画で何かそういうアンケートというのをいつやるというのがあるのか尋ねました。","respondent":"藤村子ども育成課長","answer":"アンケートはあり方検討というのを行うためにアンケートを取ったので、定期的に取っているものではないです。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5112#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":70470,"voices":201}},{"id":"r05-20231107-5","meetingId":"r05-cm11","date":"2023年11月7日","dateIso":"2023-11-07","committee":"総務委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"先ほど申し上げましたとおり取り上げる順番を変更し、初めに、(2)八潮児童センターにおける公金紛失の対応","agenda":"先ほど申し上げましたとおり取り上げる順番を変更し、初めに、(2)八潮児童センターにおける公金紛失の対応","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"人間ですからやはり間違いはあるかと思います。今後注意して対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"令和５年職員の給与等に関する報告及び勧告の概要","agenda":"令和５年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"勧告の概要ということでお聞きしましたが、所得がないというのが、私がいろいろな人から話を聞いている中では実態です。こちらの公表、区民から見てもなかなか理解されないような状況にあると私は思うのですが、その辺についてちょっとご意見を説明するよう求めました。","respondent":"崎村人事課長","answer":"公務員と同様に同じような部長ですとか課長等の役職段階を有していて給与比較が可能といったところでこういった勧告になったと理解をしているところ…こういった給与勧告の制度ということについてもご理解いただければ幸いです。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"このまま減ってきて、というよりこれはどこかで回復できるのですか。そういう方たちに区で働いていただくということが大事でして、非常に先行きが心配されるデータがあるのですけれども、そういうのは大丈夫なのか尋ねました。","respondent":"崎村人事課長","answer":"３０代は大体３０％で２０代は大体２７％ぐらいということで、２０代３０代の若年層がかなり品川区の職層構成比の中では高いといったところです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"可処分所得が減ってしまったら生活できないから会社に、こういう品川区役所でも見切りをつけるということが今の若者の傾向でもあると思うのです。若い人を品川区に職員として残して、それで区民のために働いてもらうように努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"意見","question":"だけれども、２０代の後半ぐらいから３０代の、２５歳から３５歳ぐらいまでの間、ここのやりがいがどうしても私は問題だと思っています。","respondent":"崎村人事課長","answer":"仕事と生活の両立支援というところで言えば、男性育休の促進についてはまさに力を入れて進めていくところです。知識、経験を有する職員を採用する制度というのがありますので、そういったところを活用しながら体制というものは考えていきたいと考えております。","id":"exchange-005"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"変えてください」と言って、だから品川区はデータを出さなくてはいけないわけだけれども、そうすると東京都のほうは囲ってあるわけではないですか。こういうのはどうしたらいいのか尋ねました。","respondent":"辻広報広聴課長","answer":"やはりアクセシビリティ、そういったことで返事をするというような、区の中での調整は広報広聴課のほうでさせていただきました。ところが、都との関係ですとか、よそとの関係ということですと、そこまでは実態としては今はできていないところです。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これから売り出してほしいということで、ケーブルテレビの方は結構食いついていただいて、取材を進めてもらっています。要望です。","respondent":"辻広報広聴課長","answer":"しながわ」で取り上げよう、ケーブルテレビの番組でとか、いろいろ考えるわけですが、まずそのネタですね。今おっしゃってくださったような情報を、ぜひその辺りはご協力を逆にいただきたいなと思いますので、よろしくお願いします。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"意見","question":"だから、「まちの人から学ぶ」でやっている人もたくさんいらっしゃるけれども、ぜひそういうものをもう一段考えてほしいな。これはお願いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"もちろん区もバックアップしなければいけないと思うのですけれども、そういう体制を本気でやるならやっていくべきではないかなと私は思います。いや、品川区というより品川駅が品川区だと思っている方が多いので、その辺広報広聴課長のご見解を説明するよう求めました。","respondent":"辻広報広聴課長","answer":"いろいろなところに行っていろいろなことを幅広く知っているけれども広報の専門家ではない、それだけで生きてきた人間ではないというのは事実です。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"できないからというのではなくて、区の職員もそれに影響を受けてよりよい品川区にしていく、そういう姿勢が大切ではないかなと私は思います。意見だけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"いろいろなことをやった結果、何となく因果関係がよく分からないままこうなりましたというものがどうしても多くなってしまいがちだと思うのですね。この点を、そしてそこからの事業ということで明確化していくということが大事ではないかと思いますけれども、ご見解を伺えればと思います。","respondent":"辻広報広聴課長","answer":"その上で、この右下の図にも示しているような大きな目標があって、それにひもづいたものがある。それはこれからいろいろ調整する中で課題となって考えていくところかなと考えています。","id":"exchange-011"},{"speaker":"大倉委員","kind":"確認","question":"すみません、ちょっと確認も含めて教えてください。どの世代が、例えば若い世代なのか、年配の方たちがさらに愛着を増やしていくのかとか、そういうような考え方はどうあるのか説明を求めました。","respondent":"辻広報広聴課長","answer":"割とこういうふうに考えてシティプロモーションをしている自治体というのは全国でも多いと聞いております。そこを起点として相乗効果で品川を活気づけていくというのがいいのかなと考えています。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"それは世代にもよりますけれども、もう少し若い２０代後半ぐらいだと、そういったところもぜひ積極的に聞きにいっていただきたい。大変かもしれないですが、そういう声を聞けるような何か取組とかというのはどうですかというのは、いかがでしょう。","respondent":"辻広報広聴課長","answer":"本当に思った以上にすごくいい区で」というようなご意見を個別にいただいたりすることもあります。今、何かＱＲコードを読んでとか、そこは今後いろいろな形で区民の意見を拾っていくということはチャレンジしていきたいと思います。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"そういった民間活用とかというところの視点というのはどのようにお考えなのかというのを教えてください。地域課題を解決するところで、当然行政だけでもいいですけれども、民間の活用というのも視点に入れた何か考えがあれば説明を求めました。","respondent":"辻広報広聴課長","answer":"これからのシティプロモーションの進め方というようなご質問かと思います。これから区民と一緒につくり上げていくというのをコンセプトにやっていきたいなと思っています。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"かなり行政と連携して、様々やられているかと思うので、ぜひいろいろ民間も含めて検討していっていただけるといいなと思います。ただそこの判断が難しいなと思っているのですが、その辺はハードルがあるものの、いろいろ前向きにやってもらいたいと思うのですがいかがか尋ねました。","respondent":"辻広報広聴課長","answer":"いろいろな面があり、そこにあまり気を遣い過ぎると総花的になって結局どこにも刺さらないというようなことはあるのかなとは認識しております。将来の品川がどんなふうになってほしいということも区民の皆さんともお話をしながら、そこで設定していくのがいいのかなと考えます。","id":"exchange-015"},{"speaker":"塚本副委員長","kind":"質問","question":"最初に、今の品川区の地域というのですかね、そんなところの認識をお伺いしたいと思います。こういうところでいくとやはりシビックプライドみたいな、その点、今の品川区の今後のシティプロモーションについての考え方を伺いたいと思います。","respondent":"辻広報広聴課長","answer":"そういうことを私たちだけが仕掛けるのでなくて、区民の方と一緒にできていくのが理想かなと思っています。そんな活動を来年度はしていきたいなと思っています。","id":"exchange-016"},{"speaker":"塚本副委員長","kind":"質問","question":"区長が代わったりしたということも影響としてはあるのかなと思います。適宜な見直しというか、そういうのはどう入れるべきなのかなというようなことがひとつあると思うので、その点について最後にお聞きします。","respondent":"辻広報広聴課長","answer":"それも平成３０年度の認知度では、そのとき実は８７％、すごく高かったのです。これだけ社会の状況や人々の考え方がいろいろ変わる状況の中では適宜、やり方、手法を見直すということは必要になってくるかなと思います。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"中途でそういう方が来られてうまくいく場合と、その人が来てしまってどうするのだ、５年間と。だから多分感想でも同じことを言うけれども、こういうことが起きていると私は思っているということだけお伝えしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":26198,"voices":55}},{"id":"r05-20231108-14","meetingId":"r05-cm11","date":"2023年11月8日","dateIso":"2023-11-08","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松本委員","kind":"質問","question":"そういったところは、今回は記載はないのでしょうか、伺います。","respondent":"山下新庁舎整備課長","answer":"ただいまご質問いただきましたエレベーター内のかごにおける鏡の設置ですけれども、かご内に鏡を設置するという形でお示しをしております。第三庁舎でありましたり、鏡は極力設置に努めているところがございまして、新庁舎においても取り入れていく考えです。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"網羅的に反映をされているのかどうかというところと、これはガイドラインで手引きですから、まず大丈夫なのかというところ。２点、お伺いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回、主なご意見とその対応状況を反映しておりますので、基本的には反映に努めているところです。この手引きを指針として定めるというところで取り組んでおりますので、極力でき得る限り、この手引きに沿った設計で臨んでまいりたいと考えています。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２４０件全てをというのは難しいと思うのですけれども、こういうご意見があったのだけれども、ご紹介をいただきたいということが１つです。それをお伺いします。","respondent":"山下新庁舎整備課長","answer":"主なご意見の３点目、「また」以下に記載をしておりますが、天井走行リフトの設置検討といったようなご意見がございました。先ほどご紹介申し上げた素案の検討、安全性の面で大丈夫なのかとか、ただいま「検討」という表現にとどめしていますけれども。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"正に当事者の方からのご要望ということで、できるだけ反映をできるよう、基本設計を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"その中で確認をしたいのが、子育て世代への伺いは、これもどれぐらいの人数の方に聞けたのかということを知りたいところです。これはページの、例えば閲覧数の把握とかということはできるものなのでしょうかと思ったので、教えていただきたいところです。","respondent":"山下新庁舎整備課長","answer":"主なご意見の１つ目、こちらとしても改めて認識をしまして、こちらのほうに反映しております。３点目の周知、区広報しながわには、１０月２１日号にこのオープンハウスの実施について掲載いたしました。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"知っていただくとともに、より質の高いものにつながっていくと思いますので、そのような取組を引き続き続けてほしいと求めました。新庁舎検討に当たって、様々ご意見を聞く機会があると思いますので、同じような形で進めていただきたいと要望いたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"踏面は確認できましたけれども、事細かく障害者団体、あるいは設計の方としっかりと検討してやってほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"トイレのことで少し教えていただきたいのですけれども、その横に個室のトイレがあって、ここは性別を問わずということになっているのですか。どこの自治体などでもご苦労されているところなのではないかと思うのですけれども、少し今、気になったので、そこのところをお伺いしたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"ピクトグラムにつきましては、ＩＳＯなどＪＩＳ以外の基準や既存の施設の検討事例を踏まえて、これから検討する段階になってあります。補足的に配色で識別できることを検討するというところで考えているところではありますけれども、性別に関係なく入れるトイレにつきましては。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"このオールジェンダーということを要望されている方々か、オールジェンダートイレを導入してほしいという要望の答えとしては、理解いただけるというようなところは大丈夫なのかということを最後にお伺いします。","respondent":"山下新庁舎整備課長","answer":"今回、そういう性別の別を気にせず入れるお手洗いがやはりあるといいというようなところは、団体の皆様からもご意見として聴取したところです。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問","question":"１階に、一部屋というか、かなり広いスペースなのです。区民の皆様にとってはいいのではないかなと考えますが、その辺、お聞かせ願えますか尋ねました。","respondent":"山下新庁舎整備課長","answer":"設置するとか、検討するというふうな表現にさせていただいているところですけれども、今後検討を深めてまいりたいと考えています。一応の考え方としましては、今ご紹介あったような音とか、光といった点には配慮した上の検討をしていきたいというふうに考えてあります。","id":"exchange-010"},{"speaker":"筒井委員","kind":"確認","question":"面積のことはほかの委員もありましたけれど、これ、全フロア、このような同程度の面積のトイレを設置するのか。イメージ図と言っていいのですか、これはあくまでもイメージであって確定ではないということでしょうか、その確認をしたいです。","respondent":"山下新庁舎整備課長","answer":"今委員ご案内のとおり、あくまでそれぞれに記載例にという形で極力書いておりますけれども、例示という形です。０８トイレというところも、ご説明をしたい項目を書いていきますと、面積の点についても配慮した上での設計というところが肝要かと捉えてあります。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"性的マイノリティ支援団体のご意見として、トイレについては少し記載がされておるのですけれども、そのほかにも性的マイノリティ支援団体から何かこうしてほしいとか、そういったご意見、ご要望はあったのか尋ねました。","respondent":"山下新庁舎整備課長","answer":"下から３つ目、性的マイノリティ支援団体の方からも、ご意見を頂戴いたしました。したがいまして、今回、それは性別を問わずご利用いただけるようなというところも含めた配慮をしてまいりたいと考えています。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"はい、分かりました。それこそパーティションとかの設置はお考えではないのかということと、お分かりになるところがあれば、ご説明いただきたいと思うのですけれども。","respondent":"山下新庁舎整備課長","answer":"仕切りは一定設置されているかと思いますので、座ってお話しする場面では、やはり仕切りは一定必要かなと考えています。個室のブースを設ける形でプライバシーに配慮していくという形での運用を考えてありますけれども、今、大枠の考え方としてそのような考え方です。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひプライバシーに配慮した設えを積極的に検討していってほしいと求めました。まだまだ知らない方がいらっしゃるかなと考えていますので、もう１回広報をするとか、意見を募る期間の延長はお考えではないか尋ねました。","respondent":"山下新庁舎整備課長","answer":"今回のオープンハウスの取組に対する周知という部分です。ＳＮＳでの配信というところは重ねて行ってまいりたいと考えていますので、重層的に周知、ＰＲはかけていきたいというふうに考えてあります。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"それぞれご説明ありがとうあります。１点目は、ぜひそれも水洗になるのかどうかということをお聞きしたいなという、お願いします。","respondent":"大友新庁舎建設担当課長","answer":"１点目、福祉車両の停車についてですけれども、停車スペースを設ける形で設計を進めたいと考えているところです。２点目、まだ設計上進めていないところですので、これからの整備検討の中で検討してまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"駐車場のことについてですが、入り口の近くとか、エレベーター近くとか、ぜひ設置してほしいと求めました。やはり水の出るトイレのほうがいいかなというふうに思っておりますので、要望ではありますが、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"ご意見をお伺いした２４０件を出していただいた団体とかについては、追加があれば言ってくださいという形にしているのかというのが２つ目です。３つ目が、これは少し個人的に伺いたいのですが、それとも全く同じような意見が出てこういう形になったのか。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"１点目のご質問です。まず１点目として、そういうようなトイレも設置していきたいという考えを示していくところでございまして、基準をより厳しくして。 素案の検討会と同様に、７団体の皆様が２回ぐらいに分かれまして、お聞きしながらというところで考えてあります。３点目ですけれども、全体的な考え方の中で、このような形で取りまとまっているという状況です。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"２番目のところについては、正にそれを望んでおりましたので、よろしくお願いいたします。１点目については分かりましたが、その点も含めて、あまり区別するのも申し訳ないかなというところもあって質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"せお副委員長","kind":"質問","question":"１点だけお伺いします。授乳室は安全でプライバシーに配慮した場所に設置してほしいと、まず、これ以外に授乳室に関して意見があったのかということを説明するよう求めました。","respondent":"山下新庁舎整備課長","answer":"もう少ししっかりしたものにしてほしいというところと、やはり鍵などの防犯設備というところのご意見をいただいております。今回の設置の場所につきましては、子ども連れの皆様が訪れるフロアに１以上設けるという形で手引き（素案）上、表現をしております。","id":"exchange-019"},{"speaker":"せお副委員長","kind":"質問・要望","question":"民間はしようがないですけれども、できれば、そこは分けていただきたいという。場所をとるので、なかなか難しいとは思うのですけれども、そういった配慮もしていただければなということを要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"４０年後、どのような場所であってほしいかというところで言うと、そういったものを求めている。各委員から活発な意見交換とかがあったのでしょうかというところ、よかったかどうかということを、ご見解をお聞かせいただければなと考えています。","respondent":"泉広町事業調整担当課長","answer":"当日行いましたグループ討議形式における進め方に関するご質問ですけれども、３班つくって、様々なご意見を引き出していただいたところです。通常、こういった検討委員会をああいった形で進めてまいったところはなかなかありませんけれども、区としては捉えているところです。","id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"せっかく皆さんに集まっていただいているので、意見を言っていただいて有効なものにしていただきたいなということを思ったところです。もう１点、コメントをいただけるところがあれば、お聞きできればと思います。","respondent":"泉広町事業調整担当課長","answer":"現在取りまとめ中というところで、改めて取りまとまった段階で周知を図ってまいりたいと思ってあります。対話型市場調査と呼んでいるところがありますので、そういったところの内容を踏まえながら出していきたいというふうに考えておるところです。","id":"exchange-022"},{"speaker":"山本委員","kind":"確認","question":"今、無事に進んでいるということだと思うのですけれども、確認をします。社数とか、何か中身以外のところで、ご説明いただけることがあれば、お願いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"複数社の方から非常に様々な検討の内容を、お考え、内容につきましてはご報告します。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問","question":"度々質問して失礼いたしました。ぜひ、まとめていただいた資料を待ちたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"右側のところがどこがどう対応しているのかが少し分からないのですけれども、この反映はどこの部分でこれをご説明しているのかというところが１つ。その辺りをまず説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"４ページに記載しています、令和６年６月頃を予定していると書いています第５回検討委員会の取りまとめの上に、活用の基本的な考え方というところで。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員の皆さんが、どこがゴールなのかというところが、私がまだ少しはっきりしないところがあったので質問させていただきました。４０年後に求めていくイメージとしてあるのですけれども、(8)だけ特出して財政、そういう整理にしなかった理由を説明するよう求めました。","respondent":"泉広町事業調整担当課長","answer":"申し訳ございません、記載をしてございませんけれども、そういった視点が含まれている事例というところでご紹介させていただいているところです。(8)につきましては、財政支出の抑制の１本の柱で行った事例として、少し特出しで表現をしています。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"どういう捉え方もできると思うので、第１回ワークショップの実施結果を踏まえてから抽出したような、あえて質問させていただきました。それについて教えていただきたいということが１つと、今回、いわゆる賃貸マンションをつくりますよということが定住ということを言っているのか。","respondent":"泉広町事業調整担当課長","answer":"第１回検討委員会のときに申しました現庁舎、第二庁舎なども含め、おおむね１万４,０００m2ほどあります。もう１つは、子育て支援施設ですとか、この中では表現させていただいているところです。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。その辺り、皆さんがご理解していればいいのですけれども、その辺りも少し丁寧に説明したほうがいいのかと思って質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"まつざわ委員","kind":"質問","question":"高齢者施設をつくってほしいという方もいたり、ドッグランをつくってほしいという方もいたり、もう一度説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"２０代、３０代の方もいらっしゃっているというところでは、幅広くご意見を頂戴したと考えています。検討委員会の中で行ったグループ討議におけるファシリテーターにつきましては、その学識経験者、バランスよくご意見を頂戴していただいたところです。","id":"exchange-029"},{"speaker":"まつざわ委員","kind":"質問","question":"解体があって、建物を造ると、やはり一番迷惑がかかるのは地元とか近隣ですよね。いろいろ騒音でも何でもそうなのですけれども、一番そこら辺の方のお声をやはり聞いてあげるべきというか、そこら辺を説明するよう求めました。","respondent":"泉広町事業調整担当課長","answer":"考え方ですけれども、情報提供、意見集約が必要だろうというところで捉えているところです。様々な場面で、こういうところには広く周知をするとともに、その中でもご意見をいただいてまいりたいと思ってあります。","id":"exchange-030"},{"speaker":"松本委員","kind":"確認","question":"私のほうからは、先ほど、あくつ委員からもありましたけれども、事業手法です。どういうふうに活用していくのかというところと異なって、それでいいのかという確認と、そういうものを示していくという形なのか伺います。","respondent":"泉広町事業調整担当課長","answer":"今新しいやり方ですとか、そういったところも出てきているところで、様々な事例を今収集しています。これは跡地活用の検討委員会の中では、この庁舎跡地活用検討委員会が終わって、この検討委員会の中でしっかり区民ニーズを捉えた上で。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"その辺りは意識していただきながら、恣意的な評価にならないように、企画にならないように気をつけていただきたいというふうに思う次第です。以上は意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"ワークショップの質問の仕方について伺いたいのですけれども、緑豊かとか、公園とかというふうに答える人が多いかと思うのです。２０ページ、なぜ「庁舎跡地周辺」というふうに質問をしたのか、どういう効果を狙ってこういう質問をされたのか伺います。","respondent":"泉広町事業調整担当課長","answer":"今回の活用検討の範囲ということでお示しさせていただいた現庁舎跡地と、検討の範囲の対象となっているところについて、この検討範囲の中でできることといった視点でご議論いただきたいといったところで。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"一体的なまちづくりということで、その周辺ということを聞くということは必要かと思うのですけれども、ということは、庁舎跡地そのものについては、今後、聞いていく予定はあるのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"第２回のワークショップを控えているわけですけれども、どういう活動のアイデアがあるのかというところをさらに掘り下げていくというところで聞いてまいりたいと考えてございまして、こういった形での進め方をやっていく考えです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"では、庁舎跡地周辺のイメージというか、委員の人に庁舎跡地周辺のイメージを聞いたり、ご要望を聞いて、逆算して、庁舎跡地そのものをどうしていくのかというふうに決めていくという、そういう流れの認識でよろしいか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"例えば、先ほど申し上げた、この検討委員会のその後に検討がなされていくものというところで考えてあります。は庁舎跡地、公園を含む現庁舎跡地等につきまして、区民ニーズがどこにあるのかという視点でのワークショップを行っているところです。","id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"先ほど、まつざわ委員からもご質問がありましたけれども、年齢層の幅は分かったのですけれども、区内のどの辺にお住まいだったりとかという、この近隣地域の方というご意見もありますでしょうし、私も住んでいる地域、その辺はうまくバランスがとれているのかどうか、それだけ確認をお願いします。","respondent":"泉広町事業調整担当課長","answer":"ワークショップにつきましても、地区編成が偏らないように、バランスよく配置した中でのワークショップの班をつくっていったです。","id":"exchange-036"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"文言の「てにをは」のところで１点、(1)で、そのほうがいいのかなと思ったのが１つ。適時適切なタイミングで公表すること」と(2)であるのですけれども、実現をした部分についても、そこについての考え方を説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"これから基本設計を進めていく中で、どういう変更がまたあるかも分からないので、残しておいてもいいのかなというところで。ほかにご意見があればというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前にも発言しているのですけれども、これは部長にも、課長にも確認しました。その点については、また文書は一文入れますけれども、今日は議論をしないのであれば、次回また皆さんのご意見も伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"筒井委員","kind":"確認","question":"本当に基本的な確認なのですけれども、この取りまとめ、今までこの委員会で出た、それぞれ各委員からのご発言を議事録とかで確認して抽出されたと、それは正副のご判断で文章化してこのように記載したという理解でよろしいか尋ねました。","respondent":"こんの委員長","answer":"はい、そのとおりです。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/642035?Template=document&Id=6158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":35585,"voices":113}},{"id":"r05-20231109-19","meetingId":"r05-cm11","date":"2023年11月9日","dateIso":"2023-11-09","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"品川区地域防災計画の素案","agenda":"品川区地域防災計画の素案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、下水道は被害が６％に減ったということで、さらにそれを１００％にしていくという計画があるのかどうかというところも伺いたいと思います。いろいろな公園など、マンホールトイレの区内での必要数というのは出されているのか、今幾つあるのかというところを伺いたいと思います。","respondent":"平原防災課長","answer":"こちらは被害想定上、かなり減少したということで、東京都下水道局による下水道整備が進展しているものと認識しております。マンホールトイレが幾つあるかというのは、後ほど確認した上でお答えさせていただければと思います。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"避難所のトイレを使えるようにしていくお考えなのかどうかというところ、増やしていただきたいとは思うのですけれども、伺いたいと思います。そこは避難所マニュアルもそうだと思うのですけれども、住民の方に配布していっていただきたいと思うのですが、いかがか尋ねました。","respondent":"平原防災課長","answer":"災害対応は災害対策本部なのですが、様々なお声をというようなところは踏まえて進めていくような形になろうかと考えています。地区防災計画ですが、区ももちろんご支援しますし、まずは自らの計画だというところを前面に出しながら進めさせていただければと考えています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"マンホールトイレは、今、そうすると公園と避難所を合わせて４００か所ぐらいあるということですか。必要数がもし出ているのであれば伺いたいのと、品川区としてはマンホールトイレの基本方針というのはあるのかどうかも含めて伺いたいと思います。","respondent":"平原防災課長","answer":"それができるかできないかということなので、全てが対応できるかというのは、また別の課題があると考えています。マンホールトイレの４００基で足りるのかといったところですが、今現状の考え方では、総合的にトイレは充足しているという認識です。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"まちづくりのほうは、しっかり住民の方の意見を聞いてやっていっていただきたいと、これも意見を述べておきたいと思います。どう行動すればいいか、しっかり分かるように、区でも周知していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"品川区地域防災計画の素案を見させていただいて１点、今、どのように作成の支援・促進を進めていくかというところが非常に課題だと感じています。今後の検討ではあると思われますが、今後の動きで具体的なところが決められているものがあれば、お聞きできればと思います。","respondent":"平原防災課長","answer":"そういったところに区が入りまして、一緒に地区の現状等々の分析から進めてまいりたいと考えています。どういう地区から進めるのかとか、今後そういったところが計画上位置づけられましたら、しっかりと細部を詰めてまいりたいと考えています。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"地域団体へ自治体の予算内でコンサルタントを３年間派遣して、その地域の特性に合った防災対策を検討して、地区防災計画を作成しているとのことです。１３地域に限らず、モデルとなる地区防災計画を作成する地域を抽出していただき、この辺についてさらにお考えを改めてお聞きできればと思います。","respondent":"平原防災課長","answer":"地区防災計画を進めるに当たりまして、そういった一定の指針のものはこちらでも考えているところですけれども、実際にどのエリアで実施していくのか。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"皆さんご意見を伺ったということなのですが、「照会」となっていますけれども、どういう形だったのかを伺いたいと思います。それが、防災計画の中で修正されたところがあるのかといったことについても伺いたいと思いますが、いかがか尋ねました。","respondent":"平原防災課長","answer":"回答があったのは、地域防災計画に直接反映すべき答えといったものといたしましては、なかなか高齢化等によりまして担い手が減っている。先日も委員会でご説明させていただきましたが、避難支援、移動の際の支援要領等々といったところを考えていくべきだというようなところで。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど１つは挙げられておりましたけれども、ぜひ反映していただきたいということなのですけれども、その確認でよろしいでしょうかということが１つ。一方で、持って帰るのも結構大変だったとは思うのですけれども、その辺についての配慮はどうなのか尋ねました。","respondent":"平原防災課長","answer":"頂いた意見にしっかり前向きに取り組ませていただければと考えています。全部で１,１００ページぐらいに及ぶ計画ですので、どういう形ができるのかというのは、すみませんが検討させていただければと思います。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"せっかく出たご意見ですので、私はぜひそちらの方向で検討していただきたいと思っての質問なのですが、それが１点。じっくり見ていただくとか、そういう配慮もしてほしいと求めましたので、その点についていかがか尋ねました。","respondent":"平原防災課長","answer":"どういう方針で進めるのかといったところを、頂いたものの反映方針というものは、しっかりと示してまいりたいと考えています。そうでもないかもしれませんけれども、なるべくそういったところに行っていただくように、改めてご案内させていただければと考えています。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望にとどめます。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"防災計画をまとめるのは大変だと思いますが、最後は公助によって住民をやはりバックアップしていただけるようにやってほしいと求めました。そして、その地域の人が、その地域の住民をよく知っているわけですから、その地域の人と併せて、やはり自助・共助でその地域を守る。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"まずちょっと確認させていただきたいのが、来年の２月、決定して区民に周知されるのがいつになるのかということ。大きく在宅避難ということが、この素案の中に、在宅避難を推奨するということがどこに書かれているのかというのを教えていただけますか尋ねました。","respondent":"平原防災課長","answer":"２月の防災会議でご決定いただけましたら、即日というのはなかなか難しいかもしれませんけれども、速やかに公表してまいりたいと考えています。今ご説明させていただきました本日の概要資料の中では、「在宅避難」と、地域防災計画の中ではかなり多数の場所に散らばっております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこをどうしていくのかというところを、ぜひ強調してほしいと求めましたが、その辺のお考えをお聞きします。そこのチェック機能を今後どうしていくのかというところを、お考えが、検討されていることがあれば教えてほしいと求めました。","respondent":"平原防災課長","answer":"大変なことになってまいりますので、今後の周知啓発の進め方の考え方なのですけれども、重要性を今後伝えてまいりたいと考えています。区としてマンション防災で触れてまいりたいと考えています。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"集合住宅に関して、管理組合のあるところはしっかり区と連携が取れる、その仕組みづくりもしっかりとつくり上げていってほしいと求めました。それをしっかり区が把握して、足りていないところを補っていただくという取組が大事かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"震度６以上で防災区民組織を中心に区民避難所を開設というときに、「ではもうそろそろ行きますよ」みたいな、「震度６になりました。開設するのでどうぞ」というのをお知らせするのかというのを教えていただきたいと思いまして、お願いいたします。","respondent":"平原防災課長","answer":"まずは震度６弱以上は被害が出るのだということを前提に、避難所は基本的に開いていただくということを前提で考えて行動していただければと思います。","id":"exchange-015"},{"speaker":"澤田委員","kind":"確認","question":"では、例えばニュースやラジオ、携帯などで確認して、それぞれ区民の方が、震度６弱以上であれば、もう即、向かうという形で考えていらっしゃるということでいいのか尋ねました。","respondent":"平原防災課長","answer":"震度６弱といいましょうか、震度５弱以上になりましたら、「震度６弱以上だった。では」というような形で動いていただければと思ってあります。","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問","question":"１つ目の、もしくは地域のコミュニティーの核になっています町会や自治会がそれぞれで行っている訓練を指すものなのかどうか、その辺が曖昧に捉えられますので説明を求めました。","respondent":"平原防災課長","answer":"そういう方々にまず触れていただいて、特にどのタイプの訓練がそういうふうになっていくというような形では限定的に考えてございません。区が実施する訓練というと、あまりそぐわないかもしれませんけれども、様々な訓練で何かご支援することがあるかどうかと考えています。","id":"exchange-017"},{"speaker":"こしば委員","kind":"質問","question":"地域の中の町会・自治会によって、訓練のレベルという表現が正しいのかどうか分かりませんけれども、かなり温度差があると思うのです。課題になっていくと思いますし、その辺の底上げに向けた訓練を促すことについてのお考えなどを教えてほしいと求めました。","respondent":"伊藤災害対策担当課長","answer":"なかなか、やはり底上げというのは非常に必要だと感じました。来年度以降はまだ検討段階でありますけれども、皆さんの顔が見える関係をつくっていく訓練を考えていきたいと考えております。","id":"exchange-018"},{"speaker":"こしば委員","kind":"意見","question":"ぜひ、そういった親子の顔の見えるような訓練、全体の訓練もそうですし、また地域・町会の訓練のほうも、ぜひお示ししていただきたく。その発想がなかなか生まれてこないというのが実情でもありますので、その辺りを柔軟にまたお示しほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"ほかの町会の皆様がたくさん見学に来られていまして、あとはもう、地域に関わる全ての団体関係者の方も来られていました。特に木密地域ですから、今のご説明を伺って、所感も含めて伺いたいのと。","respondent":"平原防災課長","answer":"そういったところを考えますと、他地域の模範になるような、広めるべき訓練かと考えています。区といたしましては、手順の支援というような形でしっかりと入れて、先進事例という形でご紹介できればと考えています。","id":"exchange-020"},{"speaker":"西村委員","kind":"確認","question":"その風景には感動しているところもあります。安否確認不明者保護の訓練をしたときに、区民の方々が参加するために仕掛けていくということが本当に必要なのだろうと私も実感しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"だから足りますというふうなところが見える形になっているものがあるのであれば、それを教えていただきたいのが１点です。熊本市や、それと照らし合わせたときに、品川区はそれでも足りているのかというところも教えてほしいと求めました。","respondent":"平原防災課長","answer":"何らかそういったところに着目したガイドラインというよりは、いろいろな形でのトイレに着目して、必要量を充足していくという形を考えてあります。その辺を両方取り入れた形で災害時のトイレの充足数というのを考えて、今、備蓄しています。","id":"exchange-022"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"やはりトイレがすごく、示していただけるようにしていただけたらと思うのですけれども、その点も伺いたいと思います。何というのですか、この防災計画の中でも位置づけてやることが必要ではないかと思うのですけれども、その点も伺いたいと思います。","respondent":"平原防災課長","answer":"なので皆様、家庭内備蓄で、やはり携帯トイレを持っていただくことが重要だということをしっかりと進めてまいりたいと考えています。しっかりとまた支援していますが、防災課でしっかりとご相談しておりますので、そういう取組を進めてまいりたいと考えています。","id":"exchange-023"},{"speaker":"鈴木副委員長","kind":"質問","question":"東京都の方針としては、いつまでに断水率０％に持っていくなどという方針が出ているのか、それが出ていたらいつまでなのかも伺えたらと思います。断水率がゼロになると、水道は止まらないということで考えていいのか、その点についても説明を求めました。","respondent":"平原防災課長","answer":"そういった中で、今ありましたような耐震化といったところも進めているところなのですけれども、０％という数字ではなかったかと思ってあります。もし仮に０％になったといっても、そうなったときにどうするのかといったところの備えというような意味で、重要かと思ってあります。","id":"exchange-024"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"水道局に伺ったときに、技術的にはできているのだということも伺いましたので、ぜひ進めてほしいと求めました。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"令和５年度区内一斉防災訓練の実施","agenda":"令和５年度区内一斉防災訓練の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけなのですけど、やはりいろいろな、地域に対する騒音とか何かで駄目になってしまうのですかね。その辺、なぜこうなっているのか説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"今回の地域の総合防災訓練でも、訓練を実施する際に総合防災無線等を流して、地域の方々に訓練の実施、また中止などを呼びかけさせていただきました。一方で、いろいろ確認できる手段がありますので、そういったものをご活用いただければと考えています。","id":"exchange-026"},{"speaker":"せりざわ委員","kind":"質問","question":"聞き逃したのかもしれないのですが、４６か所でやるということで、５２か所、もともと避難所というのが一覧であると思うのですけれども、やらないところの理由というのはどうなのか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"例えば八潮地域ですと、開催する小学校等が３つございまして、これは年度で交互に実施しているというようなことを伺っております。同じ時間、同じ時期に訓練を実施するということが非常に重要だと考えていますので、今後も働きかけてまいりたいと考えています。","id":"exchange-027"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"５２か所全部、一緒にできる、そんな年を待っております。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/924121?Template=document&Id=6644#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":26929,"voices":70}},{"id":"r05-20231110-10","meetingId":"r05-cm11","date":"2023年11月10日","dateIso":"2023-11-10","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"第１０条、今のご説明ですと、具体的にはどういうことでしょうか。それはもう少しお伺いしたいです。","respondent":"渡辺議長","answer":"今、私が考えているのは、せんだってのことは、今までではなかなか想定外の行動だったので、対応し切れなかったと。傍聴席の方にしても、傍聴券の裏に規則の記載があるとおり、ご確認願いますということで、当面、対応したいという思いです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"傍聴規則を読み上げるだけでは、今のような行動を自粛しようというふうになるのかなというのは、私は疑問に思ったのです。そんな感じなのですけれども、どうか尋ねました。","respondent":"渡辺議長","answer":"その際は、退席を含めた対応をしますという断りを、直近であったものでという断りで、様子を見る形で、次回は入れようと思います。説明を冒頭に持ってくるという考え方は以上です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"提案","question":"今日はその提案はしませんけれども、今、今後どういうふうに運用されていくかというのを見守っていきたいと思います。その上で、何か提案が出てくるようでしたら、改めて提案させてほしいと求めました。","respondent":"渡辺議長","answer":"特にこの間の振り返りの中では、やはり人格否定や、特定の個人を恫喝するようなことに値するときが退席というのを、私の中ではイメージしております。これはもう誰もが、万人が許されないこととして思われる範疇だと思いますので、そういった考えです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"ただ、その都度、議長が冒頭に話すということですけれども、やはり時間帯によって出入りしているではないですか。それがいいかどうかは分からないのですが、何か紙ベースで、来られた方にこれは守ってくださいというものを手渡ししたらどうか尋ねました。","respondent":"渡辺議長","answer":"直近の、第３回定例会の最終日にあったことを踏まえて、第４回定例会でまず取り組ませていただきたいと考えています。説明があろうがなかろうが許されてはいけないということで進めたいと考えていますので、お気づきの点を含めて、ご協力をお願いします。","id":"exchange-004"},{"speaker":"西村委員","kind":"意見","question":"ただ純粋に怖かったですし、私自身のことなので、そういった思いをせずに私たちが発言できる環境をつくっていくということも必要だと感じました。それは区民の皆様に理解していただく、紙の配布なのか、何か方法というのは新たに必要かと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"そういう意味では今回、議長からいろいろ根本の発言をしていただくということは、大変大切なことだと思います。そういった事態にならないようにということでの一巡の考え方などというのは、今後も様子を見ながら、常に考えていきたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"区政資料コーナーに紙ベースで置いているだけなので、残念ながら、ほとんど見られていないという状況があると思います。ぜひしていただきたいですし、ぜひ検討をお願いしたいと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。どこの会議体でこれが検討材料になるのかということだけ確認させていただきたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"せりざわ委員","kind":"意見","question":"第４回定例会にはルール改正は多分間に合わないだろうからというお話も頂いていたと思うのですが、議会全体で取り組めるように進めていただければ。意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":9993,"voices":40}},{"id":"r05-20231121-10","meetingId":"r05-cm11","date":"2023年11月21日","dateIso":"2023-11-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"の議事日程(1)(2)および追加議事日程","agenda":"の議事日程(1)(2)および追加議事日程","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"一般質問２日目の２人目、ご本人からの要望で、着座でお願いできないでしょうかです。どうぞご了承願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"非核平和都市品川宣言にもあります恒久平和を求める立場と、ガザ攻撃の中止と即時停戦を求める、そういった決議を上げることを提案したいのです。皆さんいかがでしょうかですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"意見","question":"共産党にお声がけできていないのが恐縮なのですが、しっかりまとめて、議会全体で同じような方向性で結論を出したいと思います。そのように進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":5958,"voices":34}},{"id":"r05-20231127-6","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"区民委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山本委員","kind":"質問","question":"この契約や条件などは、そこの賃料を含めた条件面のところでの状況について、進捗等があれば併せて教えてほしいと求めました。そういった見通しについても、現状、分かるところでお教えほしいと求めました。","respondent":"西村委員長、宮澤地域活動課長","answer":"跡地活用が企画部の所管になりますので、お答えいただける範囲でお願いできればと思います。 現在は内装工事を１月末まで進めているというところでございまして、特に問題なく準備を進めてあります。企画部のほうで検討して、本日補正予算の審議を含めて、文教委員会のほうで説明されているというふうに伺っております。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"状況として問題なく進んでいるということで、確認できましてよかったと思います。文教委員会等、ほかの機会を通じて、会派としても確認させていただきたいと思ってあります。","respondent":"宮澤地域活動課長","answer":"契約の部分です。３０年の契約でございまして、駐車場や駐輪場を含めた月額の賃料につきましては、３３９万８,３４０円という形になってあります。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"その金額が、区として妥当だというふうに判断されたその根拠とか理由を、簡単でも結構ですのでご説明いただけませんか尋ねました。","respondent":"宮澤地域活動課長","answer":"そういったところと比較して、また近隣にもやはり同じような大きさの貸物件というのはなかなか見当たらないところではありますが、区内の駅前等を含めてというところを確認しています。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"何とも申し上げられないところがあるのですが、やはりそういった近隣事例等を含めて、合理的な金額が算出されているということで理解をいたしました。一つ考えるべきところでもあると思いますので、無駄のない賃料の契約締結等、今後あるときには心がけていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ伺います。ある程度のそういう物件であるということは確認できたのですが、課長にも確認したのですが、今分かる範囲で教えてほしいと求めました。","respondent":"宮澤地域活動課長","answer":"そこも、オーナーチェンジというのも含めて、お話はそれぞれからお伺いしています。ＪＲ西日本になるのですけれども、そういったところからも、地元の町会等との関係性というのもつなげていけたらというように考えているところです。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"しつこいようですけれど最後に確認したいのは、今後はオーナーチェンジはない、ほぼないと考えていいのか。当然地域センターが入るわけですから、当然それは町会自治会加入促進のための条例を持っている品川区ですから、この２点お伺いします。","respondent":"宮澤地域活動課長","answer":"先ほど来になりますが、長い目線を持ってオーナーとしてやっていきますというふうには伺っているところなので、そこは区としても安心をしています。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"大体この４０年ぐらいで老朽化というのであるならば、ほかの地域センターではどこがあるのですかという質問をたしかしましたよね。だからこうなのですよときちんと言わないと、議員としての仕事が全うできないと思うので、改めてお伺いします。","respondent":"宮澤地域活動課長","answer":"これから先も地域の人たちの町会・自治会の支援も含めてですが、３０年、移転をすることに決まったというところです。１０年、１５年と建物としては存続できるのかなというところの中で、現在の建物の中で活用してやっていくというふうに聞いているところです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"なぜなら民間のマンションなのだから、いろいろ事情があって「すみません、何のためにこうやったか分からないではないですか。だからその辺について、しっかり説明というか、今、答弁いただけますか。","respondent":"宮澤地域活動課長","answer":"その３０年後につきましては、３０年経ってからというところになりますが、引き続きというところで契約は可能だというところです。それは状況に応じていくというところにはなるかと思いますが、３０年は保障されていくものです。","id":"exchange-008"},{"speaker":"藤原委員","kind":"確認","question":"そういう意味で３０年後がどうなるかという思いがあるのですけれども、もう１回だけ確認しますが、区民の方々のためになるということですよね。大きくなって、使い勝手がよくなって、という意味で、これだけのお金をかけても投資対効果はあるということで、課長、よろしいのですよね。","respondent":"宮澤地域活動課長","answer":"地域センターは、地域の区民の皆様のために日々、サービスを提供しています。今後も区民の皆様へのサービス提供というところをしっかりと、大井第三地区へのサービス提供というのを担っていきたいと思っているところです。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"地域で質問を受けたときに、こうなるのですよ、こうなるのですよ」と。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"えのした委員","kind":"質問","question":"築４３年ですからプラスするとその後７３年、３０年後を考えるとその賃料そのままでいくというのはいいのか悪いのか、私も判断しかねるところです。３０年なので、長い期間ですとそういったことも考えられるので、その辺についても区としてはどのようなお考えか尋ねました。","respondent":"宮澤地域活動課長","answer":"月額の賃料につきましては、３０年間変わることのない金額で契約をしているというところです。賃貸借物件ですので、修繕積立てといったもの等々はその賃料の中に含まれていると解釈しております。","id":"exchange-011"},{"speaker":"えのした委員","kind":"確認","question":"それは確認できたので、区としてもやはりそれに応じて、契約内容をＪＲ西日本と協議してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"防災備蓄倉庫のことで、その確認だけさせていただきたいのですけれども、こちらの建物自体は地上５階建てということでよろしかったですか。例えば、そういった辺り、どういった部分を工夫されて準備していらっしゃるのかというところを確認したいと求めました。","respondent":"宮澤地域活動課長","answer":"防災備蓄倉庫につきましては２階部分に設けるです。浸水被害を想定してというところは確認していないところですが、２階部分にできるということと、一体となってできることがあるかと考えております。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"これから３０年間ですか、３０年後を想定するというのはすごく難しいことなのですけれども、可能性を考えていただいて。状況をよく確認していただきながらというところだと思うのですけれども、一言お願いできればと思います。","respondent":"宮澤地域活動課長","answer":"防災備蓄倉庫につきまして、所管となる防災課とも連携しながら、また、地域センターが入っておりますので、そこでも、日頃からの防災への備えというのも検討しながら、併せて進めていきたいと思います。","id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"３０年間契約で、それ以降買い取るということに、取得できるということになっていったりしないのか伺いたいです。新しいものが出ていますけれど、ちょっと広くなるということなので、区民の方が利用する際の利用料も上がってくることになっているのか尋ねました。","respondent":"宮澤地域活動課長","answer":"３０年間賃貸借をしていくというところでありまして、その先買い取るとかどうこうというところに関しましては、ちょっと今現在では検討はないです。大きさが少し小さくなりますので、その分１００円から４００円近くの金額は現状よりダウンするということになります。","id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"その３０年後というのも聞いてしまったのですが、その先はまだ分からないということです。今、どうなっていくのかちょっと分からないというところはありますので、ここは注視していかなくてはいけないなというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"せらく委員","kind":"質問・要望","question":"こちら、３０年後もそれ以降も地域の皆様に親しまれるような施設になるように、若い世代からもしっかり注視してまいりたいと思いました。広さ以外に附属の設備などで、移転後にグレードアップする部分がありましたら教えてほしいと求めました。","respondent":"宮澤地域活動課長","answer":"区民集会所の中身の部分の設備につきましては、今回移転するということで、机と椅子等に関しましては新調する予定です。併せて、プロジェクター等の設備というのは引き続き設けて、音響設備も新たな物を設置する予定です。","id":"exchange-017"}]},{"id":"topic-02","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"執行率が２２％ということで、どうしてなのですかという質問に対して、たしかそんなご答弁があったような記憶があります。それよりも１００件以上多い金額が今回想定されていますけれども、この辺り大丈夫なのかというところの算定の根拠を教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"何かしら交付金なり、そこを実際にどういう手当をするかというところは企画部財政課のほうとも協議しながらの対応になるかと考えています。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"なかなか難しいかもしれないのですが、それはお願いしたいなというのが一つです。今回は、前回もしたのかどうかというのは確認してないのですけれども、業界からどれぐらいの事業者がいるのかという聞き取りなどはしたのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"１,１００件というのが、昨年も実施するに当たりましては、いろいろご連絡もさせていただいたところです。各団体、一番身近な事業者団体にもご連絡しつつ、できるだけ広く制度を知っていただいて使っていただくようにしたいと考えております。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"随分前ですけれどこういうご要望もいただいていて、金額が１億５,０００万円以上売り上げている団体でも４０万円ということで、周知をしっかりお願いしたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"こちらの申請につきまして、現在、２２２件の中で割合はどうなっているのかというのを教えていただけたらと思います。運送事業者等燃料費高騰対策支援金のほうは昨年度３０８件ということで、こちらももしその割合が分かりましたらまた説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"ですので、事業者の中にはやはりそこがまだできていないということもありますので、今回もこの両面でということでやってまいりたいと思います。数字については、また後で調べてお伝えしたいと思います。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"昨年１,１００件程度ということだったのですが、その辺り、どのような形で確認していただいているのかというところ。個別の事業者への周知もそうなのですけれども、どういった形で、詳細に教えていただけたらなというふうに思っております。","respondent":"小林商業・ものづくり課長","answer":"もう１点、周知のところです。できるだけこの制度が始まったよということと、手続きが比較的簡単にできますので、ということをお伝えしていきたいと考えております。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"なぜこのように決まったところにしか助成しないのでしょうか、不思議です。どんな方でも火葬するわけですから、火葬場等への助成というのはどうなっているのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"国のデータも参考にしつつ、我々が実施しました助成金の実績などを参考にしまして、実施させていただいているです。そういう意味では、特定の何か業種を排除してというような意味ではございませんで、そういう中で対応可能かなというふうに考えてあります。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"今回また、枠がいっぱいになっているということで機動的にこうやって増やされるというのは、いい取組であると思っています。傾向等があれば教えていただきたいというところと、そして個人事業主ですが、企業と個人事業主の内訳があれば教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"これを合わせるともうほぼ８割、９割というようなところが、恐らくこの後の申請もそういうところが多くなるのかなというふうに考えてあります。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"ほかの委員からも質問がありましたが、また、来年度以降も引き続き支援ができることをご検討願いたいです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"えのした委員","kind":"質問・要望","question":"所管が違うのかもしれませんけれども、丁寧な対応ですとか、そういった相談サービスみたいなものをされているのかというのをお伺いしたいところです。出向いていって企業の方に丁寧にご説明いただく、これは要望ですけれど、この辺もお聞かせいただければ。","respondent":"小林商業・ものづくり課長","answer":"ちょっと家に持ち帰ってということもありますけれども、そういったことを引き続き、しっかり対応してまいりたいと思います。それが、我々の景気判断なり次の施策の展開というのに生きてくるものですので、こういうところもしっかりやっていきたいと考えています。","id":"exchange-026"},{"speaker":"えのした委員","kind":"質問・要望","question":"安心したところですが、やはり一度、事業者の方が役所に出向いてくるという、そこも例えば電話ですとか、オンラインですとか、お互いにその辺ももう少しオンラインで申請が簡単にできるような取組も、要望としてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"せらく委員","kind":"質問","question":"先ほど、電子申請と紙での申請の割合をほかの委員がお伺いしたところなのですけれども、やはり、行政ＤＸ化というところでオンライン申請を進めていきたいというご答弁がありましたが、オンライン申請にたどり着くまでの経路といったところはどのように想定されているか、伺えますか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"一番多いのがやはり、直接窓口に来られる方も多く、加えて電話では問合せというのもあります。改めてご説明の機会つくらせていただくか、あるいは、その比率というのは少しずつ上げていきたいなというふうには考えているところです。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"文字が大きくて見づらくて、なかなか進めない、たどり着けない部分があるのかなというふうに感じました。オンライン申請化、増えるのではないかと思ったのですけれども、ご見解を伺えればと思います。","respondent":"小林商業・ものづくり課長","answer":"ここをたどっていただけると、というのをご紹介しつつ、誘導をしっかりやっていきたいというふうに考えております。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今回１００件また新たにということですけれども、それを超えてくるようなら、また、来年度もというのが必要になってくるのではないかなと。来年度も引き続きというところの意欲というのをお聞かせほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"先ほど申し上げましたように４か月で２００件ペースで来ておりまして、恐らく当初、もともと予定していた１月末ぐらいまでに。申請を考えている方には早めの申請を呼びかけるような形で、早めに申請すれば当然納期も、そういったところの対応をしっかりしていきたいと思います。","id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ継続していただきたいなというのと、私たちも、もっと業種を広げるべきだというのはずっと求めてきているのです。特に、少しずつでもいいですから業種を広げていくという検討をしていくべきではないかなというふうに思うのですけれども、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"こういった燃料費の助成金というのが実態に適しているのかなという形で、今回、こういうような制度設計にいたしました。いろいろ経済の状況あるいはその物価の動向などを見ながら、経済の下支えに何が必要かということを引き続き考えていきたいと考えております。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今回は全て一般財源でやっていただいたということで、やはり健全財政ですし、急がなくていいものを今、一旦止めて、生活や仕事を支えるということが必要だと思いますので、ぜひ引き続き業種を広げて、こうした支援も継続を、状況を見てしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-03","title":"令和５年陳情第４８号、持続が困難な小規模事業者を支援するための陳情","agenda":"令和５年陳情第４８号、持続が困難な小規模事業者を支援するための陳情","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"何点か確認をさせてほしいと求めました。陳情の理由の2)「新たなる事業資金の貸付」のところでご説明をいただきまして、一つ、確認のために教えていただきたいです。","respondent":"小林商業・ものづくり課長","answer":"このほかに、物価高騰等総合支援資金というのは、事業規模に応じて使っていただいているのではないかなというふうに考えているものです。２点目、平均して９割は超えているようなところでございまして、そういうものを含めて経営相談のほうで対応しています。","id":"exchange-033"},{"speaker":"山本委員","kind":"質問","question":"上限１,０００万円の枠でやっているということなのですけれども、大体どれぐらい使っているのかというところも追加でお聞きしてもいいでしょうか。というのは、この陳情者がおっしゃっている２００万円以下の事業資金貸付について、お聞きする次第です。","respondent":"小林商業・ものづくり課長","answer":"１,０００万円の物価高騰等総合支援資金というものがありますけれど、現時点での平均実施としましては８００万円から８５０万円ぐらいの間、この辺ぐらいの割合で推移しています。","id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"免除そのものは困難ですというような説明もあったのですけれど、この返済に対しての支援というのは、区としてできることはあるのでしょうか。伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"その意味では支援制度ということでいきますと、立て直しをするような猶予期間を与えるような制度というのは既に実施しています。支援制度を使いますと３年間の無利子期間ですとか、今なかなか見通しが立ちづらい、返済計画も立て直しが必要であるというようなところを支援しつつ。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"案が出されたのですけれど、これまで品川区にはどれくらい来ているのか、これからどれくらい来るのかというものがあれば教えていただきたいのです。要は、こういうものも使ってどんどん支援できるのですよねというのをお聞きしたいのですけれど、伺います。","respondent":"小林商業・ものづくり課長","answer":"今ご質問の物価高騰対応重点支援地方創生臨時交付金の関係ですけれども、実際こういうものが、具体的に幾らかというところの部分までは。区、いろいろ支援制度がありますけれども、そういう中でどういう制度を使っていただくのがいいかというところを総合的に支援しているです。","id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"陳情理由3)のところに、そしてあとは東京都ということで、私たち共産党もずっと求め続けているのですけれども。この家賃の部分等にかかってくる支援を、品川区として進めていくべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"今の買換えを通じて将来的には電気代の削減、減少、そういったところの取組の支援というのをやっているところです。与えられるところなのかというところを引き続き注視しながら、経済の下支えの中で何が必要かということを引き続き検討してまいりたいと考えています。","id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど言った物価高騰対応重点支援地方創生臨時交付金、これはある、そして話は聞いている、けれども使っていないということなのでしょうか。そこを伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"現時点で、これは恐らく東京都、例えば区政課とかを含めてですけれども、国なりというところで、品川区のほうに幾らの金額でという形での正式な連絡なり調整がまだ済んでいないといいますか、現在協議中ということで認識しています。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ積極的に使っていっていただきたいなと思いますし、本当にこのままでは、商店街も厳しい状況になってくると思います。支えていくことにさらに力を注いでいただきたいなという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"えのした委員","kind":"意見","question":"そして、先ほどの理事者のご答弁どおり、品川区では様々な支援制度に取り組まれております。理解をしましたので、不採択にしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"様々この物価高騰において、安定的な事業活動に影響が生じているということは、我々も事業者の皆様からお話を伺っているところです。先ほどご質問があったように、そういったものを活用していただきたいということと、これから品川区としてもやっていくというところ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"山本委員","kind":"質問・要望","question":"これは要望です。ぜひ工夫をご検討いただきたいということと、ご相談にいらした方々への丁寧な対応に努めていただきたいというところで、こちらも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当にこれを進めていただきたいなというふうに、もうずっと私たちも求めてきたことですので、もうこれは大賛成なのです。してほしいというところは、ぜひ応えていただきたいなと思いますし、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、品川区は、できることは今、目いっぱいしてくれているのだと私は思うのです。ご相談、その辺は対面でやっていくわけですから、思いやりを持って接していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"せらく委員","kind":"質問・要望","question":"区で提供している支援が今あるという、ご説明の中でもありましたが、そういう現状でそういったところをしっかり使っていただきたい。そういったところを私も、窓口の皆様にはしっかり対応していただけるようにお願いをいたしまして、こちらの陳情に対しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":40113,"voices":136}},{"id":"r05-20231127-7","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"厚生委員会","time":"午前１０時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件整理しています。","topics":[{"id":"topic-01","title":"では、(1)第８３号議案、品川区国民健康保険条例の一部を改正する条例の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(5)の第９０号議案…","agenda":"では、(1)第８３号議案、品川区国民健康保険条例の一部を改正する条例の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(5)の第９０号議案…","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今回公募によらないということで、この公募によらない特別な理由というものは、この場合はどのような理由なのかを１点伺いたいと思います。多世代の利用者を巻き込んだというのはなかなか難しいと思うのですけれども、その辺がどのように具体的にされているのかも伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"先ほどの説明でも少し申し上げてはいるのですけれども、様々な自主事業としての交流事業を盛んに実施してくださっています。まず高齢者事業のほうでは、実際区の事業でも行っていますが、指定管理者による自主事業という形でのスマホ教室を実施してくださっています。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"それから、この平塚ゆうゆうプラザの人員体制はどうなっているのかを伺いたいと思います。その中で施設運営費が１,５４６万円余なのですが、どのようなところにどのような形でお金が使われているのかということも伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"１点目が、配点の選考基準の評価項目ごとに点数が出せないのかというご質問に対しての回答です。各種修繕対応のもの、細かいものでエレベーター、自動ドアなどの保守点検などの維持管理が含まれているような形です。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"その辺のところが、大体人件費という形でなるのか、その辺のところを伺いたいと思います。地域ミニデイ卒業グループの元気ゆうゆう体操クラブについて書かれているのですけれども、多分地域ミニデイをされているということですよね、ここで。","respondent":"川原高齢者地域支援課長","answer":"そうです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、ボランティア料というのですか、ここの平塚ゆうゆうプラザではどのような状況になっているのか。多分運動支援員が１人いて、このゆうゆうプラザでもやっているのか、その点も伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"ふだん地域ミニデイはやれる期間が大体１年で、講師として、ボランティア謝礼という形でお支払いをしているような形で実施をしていると思います。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"募集したら必要な数だけ応募があるという、そのようなことになっているのか、ちょっとその点も伺いたいと思います。もうこれは、やはりそれは責任を持って決定するということが議会の責任として求められるので、ご検討いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"鈴木委員のお話にあったように、人件費のことはぜひ進めてほしいと求めました。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"第８３号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第８３号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"私のほうは１点だけ、質問というよりは希望なのですけれども、広く広報に努めてほしいと求めました。リーフレットもこちらが参考例で、このようなものが区から出るということですが、母子手帳が、これ品川区だと親子健康手帳になるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、その辺のところの、もしも漏れてしまった場合はどのようにされるのかについて伺いたいと思います。国民健康保険料には反映しないということで、一般財源から出してということで考えていいのか、その点も伺います。","respondent":"池田国保医療年金課長","answer":"財源については４分の１、区の４分の１持ち出しという形になりますが、特に関係はないです。ただ、財源としましては、区のほうでの４分の１の部分が負担という形になります。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"免除されても、社会保険のほうはなっているのではないかなと思うのですけれども、その確認をちょっとさせてほしいと求めました。社会保険に合わせてというようなことであれば、国民年金も免除にならないのかなと思ったのですけれども、その点はいかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"先に実施されている国民年金の保険料のやり方をまねしたというか、３年以上前から、免除というような形をさせていただいているところです。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"では、もう国民年金で実証済みだと思うのですけれども、申請漏れはないのかということが分かったら教えてほしいと求めました。区のほうとしてもそのようなことを声も上げてほしいと求めましたし、その点ぜひお願いしたいと思うのですが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"その通知に応えまして、独自での免除というところは、現在のところは考えていないです。ただ、国のほうには、全体の形として要望は引き続き出させていただいているところです。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"常に共産党としては、国にそれは求めているということなのですけれども、区独自に改めてやっていただきたいと求めておきたいと思います。何回かこれまでも伺って、１８歳まで国民健康保険料を無料にするとしたら幾らぐらいかかるかということが、計算されていて分かったら説明を求めました。","respondent":"池田国保医療年金課長","answer":"１８歳以下の方の国民健康保険料の免除については、以前にお答えした１億５,０００万円というところで、さらに減ることはあるかもしれません。ちょっとはっきりとしないところで、来年の３月ぐらいにはまた新しく積算したいと考えているところです。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これからも求め続けていきたいと思っていますので、ぜひ計算はしておいてほしいと求めました。これはぜひ強力に求めて実現をさせていただきたいし、区独自にも無料化ということを検討していただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"提案","question":"これまでの事業者ということでの提案ですけれども、その理由もしっかりと明記していただきたいなと思うのですけれども、その点を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"先ほど説明しました手話通訳者の養成に当たりまして、通訳者のさらなるスキルアップを支援していきたいというようなご提案がございました。３施設とも、区と同じ課題認識の下、区全体のことを考えていらっしゃるご提案をいただいたものです。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"心身障害者福祉会館から伺いたいのですけれども、実際使える時間まで使えないということをいつも伺っていますので、本当に期待したいと思います。先日のモニタリングのところで医療的ケアの方は何人くらいかと伺ったときに、それぞれどれくらいの方を受け入れられているのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"高度障害の方は７名ぐらいだと認識をしております。ただし、心身障害者福祉会館につきましては、２対１を下回らないように、これまで努力を、区としても、指定管理者候補者としても、努めてきたです。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"トータルで何人ぐらいの方が、その心身障害者福祉会館の職員体制になっているのか、全体で何人ぐらいということを教えてほしいと求めました。相談というものがあるのか、調査に入ったことというのはあるのかも、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"虐待についての相談件数ですけれども、それはございません。全体のはちょっと計算をしないとならないので。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"提案","question":"では次に発達障害者支援施設について伺いたいのですけれども、これ赤字続きという、モニタリングで赤字になっていますよね。様々、それを本当に進めていただきたいと思うのですけれども、具体的にどのような形で連携をしていくという提案なのかも伺いたいと思いますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"ただ４０点中２４点ということは６割、６割ということなので、低いということではないかと考えています。区内の連絡会というものを、発達障害者を支援する施設の中心的な役割として、ここが事務局になって連絡会を提案されているです。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"提案","question":"何というのですか、それとも区のほうから働きかけて今回の提案になったのか、その辺のところはちょっと教えてほしいと求めました。その５名の方、その辺の状況を教えていただきたいということと、その点も伺いたいと思いますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"発達障害者支援施設を、連携は必要だという認識は区としても持っておりましたので、発達障害者支援施設の現指定管理者である社会福祉法人げんきとは。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"確認","question":"もっと本当にきちんと資格が問われるべきなのではないかなといつも思っているのですけれども、そのような状況なのか、最後その確認だけお願いします。","respondent":"松山障害者支援課長","answer":"世話人は、職員体制の中で夜間支援を含めまして８人の方がいらっしゃいます。ただ、国の基準上、世話人としては有資格者でなくてもできるという基準になってあります。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１人１００点として４名で計算して４００点、この後ろに別紙である指定管理候補者選定基準の評価項目と配点のところという理解でよろしいでしょうか。この１人持ち点の１０点分というものは、その別紙についてのどの項目に当てはまるかということも、併せて説明を求めました。","respondent":"松山障害者支援課長","answer":"財務状況につきましては、その１００点以外のところで、ここの別添えですね。別添えのところには記載がないのですけれども、評価項目としては、財務状況等評価というものを加えているものです。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"提案","question":"提案内容評価のところの３６０点のようなところは点数が合わないと思うのですけれども、この別添えのところの表記されているところの１００点で評価されて、それでここに合計されているのかなとの意見を述べました。","respondent":"松山障害者支援課長","answer":"この別添えの中の３「管理を安定して行う物的能力および人的能力を有していること」の中の、「福祉サービスを安定的に提供できる経営基盤を有しているか」、この中に、含まれていました。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"幾つか質問項目の中にあるので、この１０点というところがどこに当てはまるかなということをまずは確認したかったので、質問させていただきました。指定管理料が適正ですかというところの点数も本当に見えてこないというところだと、要望といたしましては、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"独自に福祉部だけ、あるいは課だけということではならないのではないかと考えております。そのところ、企画のほうには伝えていこうと考えています。","id":"exchange-021"},{"speaker":"ひがし委員","kind":"質問・要望","question":"もう１点聞かせていただきたいことは、配点のところなど、この項目というものはどのように決められているのかということもお伺いします。お願いします。","respondent":"松山障害者支援課長","answer":"区全体で品川区の指定管理者制度活用に係る基本方針、あとはその実施要領というものがあります。それからあとそれぞれ、福祉施設に関するものということで、福祉部としてこの評価項目を決めているものです。","id":"exchange-022"},{"speaker":"ひがし委員","kind":"質問・要望","question":"家族の要望・意見などのところの５点は、ここはなぜこの点数なのだろうというところや、今後も検討してほしいと求めました。こちらは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"筒井委員","kind":"確認","question":"まず確認として、令和６年３月まで、５年間今までやっていたということでよろしいのか尋ねました。","respondent":"松山障害者支援課長","answer":"上大崎つばさの家、発達障害者支援施設の場合は、２期、１０年間です。品川区指定管理者制度活用に係る基本方針が令和３年度に改定されまして、理由がある場合は継続、その規定に基づきまして行っているものです。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"令和４年度末に指定管理期間の施設に対して適用するということで、では、次回はこの適用にかかるということなのですか。それとも、令和４年度末に指定管理期間の終期を迎える施設以外はずっともう、ずっと延長できるということなのか尋ねました。","respondent":"松山障害者支援課長","answer":"基本方針によると、１５年までということで指定期間としてはされております。上大崎つばさの家と発達障害者支援施設については第２期まで終了しているので、第３期分、あと５年過ぎれば１５年たつので、そのときは公募するです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。１５年までできるのかなという期待を抱かれてしまうのかなという、もうその点の歯止めというか、それについてのご見解はいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"５年後にはまた予備委員会、今回のように５年ごとに行っていき、またよりよいサービスができるようにしていくという仕組みになってあります。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"その辺り、ぜひよろしくお願いします。５年後のことなのでどうなるか分からないのですけれども、集まってこなかった場合というものは想定などされているのか尋ねました。","respondent":"松山障害者支援課長","answer":"区としては、公募ということでは、本当に全国的に公募をし、よりよいサービスができる事業者にやっていただきたいです。今、実際にこの事業をやってみたいというような事業者が今後でてくるように、やはり私たちもサービスの向上を図っていくという必要があります。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"提案","question":"もう少しこの提案内容の３６０点のところを切り分けて、あと何というのですか、確認して。要望で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問・要望","question":"１点ちょっと確認をさせていただきたいのですけれども、評価項目としては実は２項目あってということではなく、単純にこれ重要だから２倍しているということの認識でよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"それぞれ項目について、重要だと思われるものについて２倍ということになっております。","id":"exchange-029"}]},{"id":"topic-03","title":"第９１号議案、診療報酬等の返還請求に関する民事訴訟の提起","agenda":"第９１号議案、診療報酬等の返還請求に関する民事訴訟の提起","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これが令和２年１月までの間、運営されているということなのか、そのところも伺いたいと思います。それが返還しないということは、病院側の理由としては何かあるのか、その点についても伺います。","respondent":"豊嶋生活福祉課長、池田国保医療年金課長","answer":"現時点においては４名分の請求が上がってきておりますので、そこについては２月以降に解決しているものです。生活福祉課からは以上です。 国保の被保険者につきましても、２名の方が入院していたというような形での返還請求という形になります。","id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問","question":"なぜ返還命令に応じなくて、９月に返還命令に応じなくて、伺いたいと思います。民事訴訟を起こした場合というのは弁護士費用がかかってくると思うのですけれども、区の負担というものは生じるのか、その点も伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"この間ちょうどコロナの時期と重なっておりまして、病院の経営が非常に極めて厳しかったというような報告を、東京都を通じて聞いているものです。もう１点、その辺りは手を挙げる他区、それから東京都と十分に協議していきたいと考えております。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ちょっと確認なのですけれども、時効はいつまでということはお分かりか尋ねました。","respondent":"池田国保医療年金課長","answer":"こちらのほうですけれども、請求してからの時効については、これは民法第７０３条ということで、１０年間になります。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"実際その報酬の返還分プラス、例えば損害遅延金のような形の請求もされるご予定か尋ねました。","respondent":"池田国保医療年金課長","answer":"遅延金についても、請求について考えているところではありますけれども、こちらのほうも各区統一でというようなことも、課長会のほうでは申合せをしています。","id":"exchange-033"}]},{"id":"topic-04","title":"第９４号議案、指定管理者の指定","agenda":"第９４号議案、指定管理者の指定","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"事業費としての提案というものはあったのか、現事業者より高い事業費となるということが提案としてあったのか、その点についても伺いたいと思います。それから、区民の健康増進につながる具体的かつ実現可能な提案ということもあるのですけれども、そのことも説明を求めました。","respondent":"若生健康課長","answer":"毎年報告書を提出いただくことになっていまして、それと併せて、毎年利用者アンケートというものを実施しております。荏原健康センター４００円、運動習慣の継続を促す取組といたしまして、あるいは体組成計などの測定器のリニューアル等を予定している。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"提案","question":"事業費なのですけれども、この事業費が、安い提案というようなところは、選ぶ基準として加味されることがあるのか、その点を伺いたいと思います。それから、指定管理者の利益というものはどのような状況になるのかも伺いたいと思いますとの意見を述べました。","respondent":"若生健康課長","answer":"今年度以降は、見込みとしては利用料のほうが戻ってきておりますので、還元も一定程度出てくるということで見込んでいるところです。ただ、教室の責任者というところは常勤でやっているところです。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問・要望","question":"基準額としてこれだけはここの株式会社の利益として保証されます、さらに上回った額の２割という、そのようなことなのでしょうか。これは２社でやらないとできないというものなのか、なぜこの２社が一緒に管理するということになっているのか、その点も伺いたいと思います。","respondent":"若生健康課長","answer":"それから事業体の、これは共同事業体で、２社でやらないとできないのかというような部分です。そこまで１社でやるということは、指定管理の基本方針のところで、事業の内容によっては共同事業体とすることは妨げないということになってあります。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"本件の指定管理の選定に当たって、その利用料金５００円にするということは区側の求める要件だったのか、それともそういった条件をつけずに公募をかけたのか、その辺り、利用料金についてどういった条件や評価でこれが行われたのか、説明するよう求めました。","respondent":"若生健康課長","answer":"その条例に基づいて事業を実施していますので、利用料金というものはそのまま５００円、もしくは４００円というところで設定しています。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。資本金１２４億円、従業員数５,１００人ということで、ＮＴＴファシリティーズと匹敵し得るぐらいの大手企業というものは応募されたのか尋ねました。","respondent":"若生健康課長","answer":"各社ともに、比べてどうかというところはあれなのですけれども、それ相応の規模を持った事業者のほうがご応募いただいているというものです。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。ＣＯ２排出量とか、荏原健康センター、こうした環境配慮にポイントを置いたというようなことなのか尋ねました。","respondent":"若生健康課長","answer":"これは区有施設ですので、当然今後環境に配慮した形での施設の取組というところは、健康センターも例外ではないところです。これは施設整備所管と今検討しているところでございまして、まず今回の審査では、そこを視点に置いて審査したというようなところです。","id":"exchange-039"}]},{"id":"topic-05","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"そこの確認をお願いしたいと思います。取りあえずお伺いします。","respondent":"若生健康課長","answer":"それから東京等のほうの支援金との関係ですが、東京都も今年度の補正予算のほうで、上限１浴場当たり１６万２,０００円ということで支給しています。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前回のところでは１３区ということで、都全体の状況が分かったら、それも教えてほしいと求めました。この１０万円というものはどれぐらいの割合になるのか、平均でいいのですが、その辺の実態が分かったら教えていただけたらと思います。","respondent":"若生健康課長","answer":"都全体の浴場の支援ですが、２３区では２３区中１６区、一部条件あるのが１市のみが補助となっているというような状況を確認しています。それから１０万円という、大体月当たり１０万円程度が上がっているのではないかというところは、区として把握したところです。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それがこのような形で出されるということは大事なことだと思いますので、このような状況が続く限りは、ぜひこの制度は、来年３月だけで終わりというのではなく、続けていただきたいということで要望もさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"なぜ公衆浴場というところだけに支援を行うのか、もう少し合理的な理由をお聞かせほしいと求めましたので、その辺りご説明ほしいと求めました。","respondent":"若生健康課長","answer":"今回補正予算で出させていただいている、公衆浴場以外には、産業経済費のほうで運送事業者等の高騰対策支援金というところもやってあります。そういったところをまず区としては重点を置いて支援するという考えで、今回の補正予算含めまして、対策を講じたところです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"やはり、特にそのお仕事において燃料などの料金が大きいところ、その事業をするに当たって、燃料費というものが非常に重要なところを占めるという業種だからこそ支援するという理解でよろしいのか尋ねました。","respondent":"若生健康課長","answer":"やはりその中でも大きい割合を占めるというところでは、やはり燃料費の支援というところが区としては考えなければいけないということで、今回助成のほうを行っているところになります。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、この支援金はどのようなスキームで支払うのでしょうか。申請があったら支払うのか、一括で組合などに支払われるのか、お願いします。","respondent":"若生健康課長","answer":"事業スキームです。浴場のほうに、それで一括して、年間休業がなければ１２か月分を一括で口座にお振込するというような流れになっております。","id":"exchange-045"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら区民の保健衛生の向上のみならず、地域のコミュニケーションの場ともなっていますので、現在も引き続き支援してほしいと求めました。大きく賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"令和５年請願第１７号、パンデミック条約締結及び国際保健規則改正に係る情報開示を求める請願","agenda":"令和５年請願第１７号、パンデミック条約締結及び国際保健規則改正に係る情報開示を求める請願","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"そして、ＷＨＯに最も献金しているのが、利する側の製薬企業の団体であることが、ＷＨＯのホームページで確認できます。食生活や生活習慣等により、体の性格、体質も異なりますので、地域に合わせた対応策を取ることが求められます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国家主権の尊重を含む国際的な合意を求めるとともに、国際的な軌範や規制を強化することが重要であるとの立場であり、交渉の結果は予断しないものの。何というのですか、そのような体制をつくっていくということは、私は大事なことではないかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"こしば副委員長","kind":"質問","question":"当然民主的な選挙で選ばれた議員より審議がされるわけですから、やはり説明を受けましても、その印象を覆すことはできなかったということが感想です。はそういったところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"不安をあおるというなら、なおさら広く告知し、国民を安心させるべきではないでしょうか。中身がよい悪いといったことよりも、こういったことを広く知ってみんなで議論していただきたいということを求めている請願であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"筒井委員","kind":"質問","question":"ですから本当に、なぜ今の今までにこのような議論が日本で進んでいなかったということは、周知が必要かと考えております。は議員や有識者の方から意見を聴取する手続を早めに開始してほしいということですので、この請願は賛成に値するものだと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"確認","question":"おぎの委員に１つ確認なのですけれども、この理由のところにある、先ほどから理由のところにも先進国、途上国というようなお話があるのですが、日本はどちらに該当するのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これはもう、このＷＨＯの話合いの中で、その枠組みで話し合われているということでよろしいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"意見","question":"先進国から、先ほど鈴木委員がおっしゃっていたように、発展途上国に分配するというプランも入っているようです。先ほど言いました国連加盟国１１か国、広く受ける側の意見も聞いて進めるべきものなのではないのかなということは、これ草案を見ていて思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ここの理由のところは、何というのですか、まだ本当にこれからどうなるか分からないというようなところは正直感じます。ただ、要旨は賛同できると、個人的には考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"意見","question":"今、完成のものはまだ出てきていないので、どこの国でも待っているものは草案です。ただ、草案の段階ですが、決まってからではもう遅いので、広くほかの国のように議論していくことが、日本国内でも重要だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"ひがし委員","kind":"意見","question":"でもそれが変わっていったときに、ではどのタイミングで知るのだろうというところが、やはり懸念点としてあるのかなとは思います。そこについてはしっかりと議連のほうで議論した中で徹底をしていってほしいなというところと、改正案の段階でしていただいて、私としては思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"鈴木委員","kind":"質問","question":"ＷＨＯの憲章の中でも、統治権が奪われたりすることというものはないということなので、この懸念というものも私は当たらないかなと思います。何というのですか、そのような上に今回の請願が出てきているということですので、ちょっとこの請願に対しては賛成ができないというのが意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"おぎの委員に確認させていただきたいのですが、最も危険なのはワクチンなどを強制的に日本国民が接種させられるという、そこが一番問題だというお考えか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"意見","question":"いつ頃どういったことでアナウンスするのかということも含め、国としても議論して、国民も大きく議論をしていく問題ではないかなと思います。今日委員会の、こちら委員会内の討議になりましたが、非常にいい討論ができたと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"もう一定の皆さんのご意見も出ましたし、態度表明もほぼほぼ出ている状態だと思います。これで意見陳述のほうは必要がないのではないかと判断しますが、皆さんいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"私も今、こんの委員と同じように、おぎの委員の説明でこの趣旨も理解はできましたし、また意見については先ほど私がお話ししたとおりであります。ですから、これ以上の意見陳述は求めなくていいのではないのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"意見","question":"私はこの請願は反対ですけれども、意見陳述は常に聞くべきだと思いますので、意見陳述をしていただいてよいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"筒井委員","kind":"意見","question":"こうした状況でしたら、最初に意見陳述を聞きたかったと思うのですけれども、私としてはせっかく請願を出されて、お越しいただいているということなので、意見陳述の申出を受けたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"おぎの委員","kind":"質問・要望","question":"議会運営の慣例にのっとり、来ていただいているので意見陳述を私は求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そうですね。わざわざお越しいただいて、私は区民の声はしっかりと委員会で聴くべきだと思いますので、ぜひお話を聞ければと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。ただ、その点については先ほどお話あったように国会を中心として国でしっかりと議論をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"鈴木委員","kind":"提案","question":"結論を出すということで、この請願に対しては不採択でお願いしたいと思います。そのテキストというのは、加盟国から出されている提案全てを暫定的に書き込んだものであって、主権の侵害ということには当たらないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"おぎの委員","kind":"意見","question":"こちら、今まだ素案の段階ですので、内容等含め、決まったものはございませんが、広く国民に周知して議論していくことが非常に大事だと私も考えます。こちらのほう、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そして参政党、こういったところを含めて、我々も広く一般に周知するようなことを心がけていかなくてはいけないというふうには考えております。まだはっきりとしたことが言えないというところで、不採択といたしますが、議会としても今後注視していく必要は十分にあると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"}]},{"id":"topic-07","title":"令和５年請願第１８号、補聴器購入費助成制度を求める請願","agenda":"令和５年請願第１８号、補聴器購入費助成制度を求める請願","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"今おっしゃっていた、アンケートの内容というのはいつ頃に決まって、この委員会でもぜひ内容というのは共有していただきたいなというふうに思うのですけど、その予定とかあれば説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"そちらの完成をもって次に、荏原医師会の耳鼻咽喉科の先生に、品川医師会と荏原医師会の双方にこちらの中身の確認をしていただくところです。具体の中身を確認いたしまして、またこちらで、実施するかに関しては検討してまいりたいと思います。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問・要望","question":"せっかくアンケートを取るのだったら有意義なアンケートになっていただきたいなというふうに思うので、今質問させていただいたのですが、こういう内容ですというので共有をされるご予定などあるのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"こちらの委員の皆様への公開については、今いただきましたご意見を踏まえまして検討させていただきたいと思います。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問","question":"補聴器の助成について、今後、今年度だけでも既に予定をしていた８０名を超えるのではないかというふうに認識をしております。この今決まっている予算というのは３５５万円余でしたか、予算が当てられていて、何か見えているものがあれば教えてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"予算の状況に対する今後の見込みです。これから支出を予定している方、そこで大体予算の見込みが全て売り切るというか、しっかりと対応していきたいというふうに考えてあります。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問・要望","question":"３分の１となると１万２,０００人、今の８０人の規模の予算だと、私としても要望していきたいなと思います。今後の方針を決めていくべきかなと思いますので、ぜひ共有してほしいと求めましたが、もし何かあればお願いいたします。","respondent":"川原高齢者地域支援課長","answer":"現段階ではまだ検討中ですので詳細は申し上げられないのですけれども、所得要件を非課税者として実施している、あと。という内容よりかは現行の制度できちんと実施が、効果が図られていたかというのが中心の内容のアンケートとして今は考えているところです。","id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問・要望","question":"たしか平成２７年度ぐらいから要望されていて、医師会の先生や認定補聴器技能者の方々からの感想というのですか、そこら辺はどんな声が寄せられているか少し伺えたらと思います。","respondent":"川原高齢者地域支援課長","answer":"それで、ようやくその実施に結びついたというところで、非常に喜んでくださっていたというところが、私も実感をしています。専門の資格が、そういった専門職の方に、資格取得に対しての問合せも受けているというようなご意見もいただいているところです。","id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"さらにこれを進めていただきたいというふうに思っているのですけども、受けるということになったのか、その点伺いたいと思います。８０人というのはその倍の人数を受入れ、補正を組んででも申請者は全員助成しますよという姿勢なのか、その点についても伺います。","respondent":"川原高齢者地域支援課長","answer":"委員のご指摘のとおり、補助率は２分の１ですので、歳入が約半数、半分、見込みがあるところではありますけど、現在申請をしています。どのような結果が出るかというところまではまだ見込みにはなるのですけれども、申請が通った場合には、計算としては想定しています。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１５万６,０００円から住民税課税者と書かれているのですけど、税務課長に改めて確認したのですけど、１５６万円以上は課税になってしまうのです。その点は、高齢者の生活実態というふうなところからしたら、区としてはどう考えられているのかを伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"委員のおっしゃるとおり、年金で単独の高齢者の方が本当に１５５万円の前後のはざまで、区としても認識しています。今後実施するアンケートでも、購入者で、そういった現状も踏まえた取組や政策を検討してまいりたいというふうに考えてあります。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"予定はないけれども検討しているというご答弁でしたが、予定はないということは、来年の４月からされるということがないということなのでしょうか。住民税課税まで対象にしてほしいという要望というのは出されていると思うのですけど、何をクリアするとそれができるのか、その点についても伺います。","respondent":"川原高齢者地域支援課長","answer":"高齢者の社会参加やフレイルのほうの促進からも、現在は現行のスキームで実施をしていますので、現在のところは実施の予定はございません。今後の見込みに対しても、現在も引き続き検討をしています。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これだけ強い要望が各会派からも出されていますし、その点も伺いたいのですけど、来年は無理なのでしたか。様々な予防という観点からも、ぜひとも強力に進めていただきたいということで、改めて要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要望のような形になってしまうかもしれないですけれども、２行目のところに、まず思っております。何か、今のことでご意見があればお願いいたします。","respondent":"川原高齢者地域支援課長","answer":"様々な意見ありがとうございました。引き続き検討しているところでございまして、検討してまいりたいと思いますので、検討をしっかりとしてまいりたいというふうに考えてあります。","id":"exchange-080"},{"speaker":"こしば副委員長","kind":"意見","question":"結論を出すで、今回の請願については、先ほど課長からの答弁にもありましたとおり、アンケートの内容についてまたこれから出てくると、そういった情報をしっかり吟味した上でまた判断をしていくのがいいのではないかと考え、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうした体制を求めたところ、区としては、それを検討していきますという前向きなご答弁をいただいておりました。早い段階で対象拡大が来る時期を待ちたい、このように思っておりますので、本請願については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"ひがし委員","kind":"質問・要望","question":"予算拡大そして対象者、課税者も含めてというところは、ぜひ前向きに検討していただきたいというふうに要望します。ただ、アンケートの結果を踏まえた後でというところも、実態把握という部分では大切かなというふうに思いますので、今回の陳情は不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"こういう要望が上がっているにもかかわらず、区は来年度というか今のところは、そこまで拡大する予定はないということでしているわけです。議会としてそれを求めていくということ、議会がここで採択をすれば区はやらざるを得なくなるわけですから、ぜひ採択をして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問・要望","question":"そもそも私としては、一方で税金を使うわけですから、しっかりとそのアンケート等々で効果の検証をしっかりとしていただくと。それで、効果検証が済むまでは、その効果検証をしっかり見守っていきたいということで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今回アンケート結果を見て、ぜひぜひ拡充していっていただきたいなと、前向きに検討をお願いします。それで、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、採択です。集計をして、この委員会含め議会の役割だと思いますので、一丸になって進めていきたいというふうに思いますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"}]},{"id":"topic-08","title":"令和５年陳情第４４号、品川区立重症心身障害者通所事業所「ピッコロ」移転・拡張に伴い、現在通所できない呼吸器利用者が通所可能になるための整備を求める陳情","agenda":"令和５年陳情第４４号、品川区立重症心身障害者通所事業所「ピッコロ」移転・拡張に伴い、現在通所できない呼吸器利用者が通所可能になるための整備を求める陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"ただ、八潮南の増改築含めて、これ、今後、人工呼吸器を対応したような施設を増やしていく。つまり、八潮南以外でもいずれ増やしていく可能性があるというような認識でよろしいか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"先ほどもご説明させていただいたとおり、どの事業所についても、やはりその人材確保というのは大変難しい状況ではあります。電源用の天井レールなども設置して、重度の方も安心して通所できるような、そのような態勢を構えるよう進めております。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"決まっていればでいいのですけど、どれぐらいの人員の対応を見込んでいらっしゃいますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"こちら、開設が令和９年度になりますので、まだ詳細のところは、現段階では決まってはおりません。ただ、やはり重度の障害者ではありますので、手厚い人員配置というところで考えていく体制ではおります。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問","question":"令和９年となると、まだまだ先かなと思うので、その間の期間に、八潮南の増改築、ピッコロの移転というものの前に、どこかで、人工呼吸器の対応というのを生活介護で考えていらっしゃるという計画は今のところはいかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"現時点では人工呼吸器対応というところで検討はございません。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういった団体の方からのお話も伺っているので、ちょっと令和９年というところは一つの計画としてはあるとはいえ、やはり検討を進めていく必要があるのかなというふうには思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"そのうち、人工呼吸器使用者の人数も同様に教えてくださいと言ったときに、何で１９歳以上の医療的ケア児者の直近の人数というのが４人だったのか。これは、４人という人数はあり得ないのではないかと思うのですけど、その点、どうしてこうなったのか伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"重症心身障害児者等在宅レスパイト事業および障害児支援等の利用者のうち、医療的ケアを要する人数が１８歳以下は３０人、１９歳以上は４人です。連動しているものではございません。","id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私が一般質問で伺ったのは、医療的ケア児者の直近の人数ということで伺ったので、当然人工呼吸器使用者が入ってカウントされるものだと思ったのです。保健センターとかも突き合わせをしながら、全体の医療的ケア児者の人数というのは把握していただきたいなと思うのですけど、いかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"病院に入院されている方もいらっしゃいますので、非常に、把握するのは困難ではあります。ただ、保健センターとは、この令和５年２月末現在の数字は突き合わせている、突合しているものです。","id":"exchange-093"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１９歳以上となると、たん吸引の高齢者みたいなところまで入ってしまうという、そういう感覚なのですかね。課題も明確にして、ぜひ明らかにしていただきたいなと思うのですけど、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"医療的ケアのお子さんが将来大人になるということを考えますと、課題や情報を共有したいということで連絡会を実施したところです。１２月の上旬に開催を予定しておりますので、かなり、一つずつ課題を洗い出して課題解決につなげていきたいと考えております。","id":"exchange-094"},{"speaker":"鈴木委員","kind":"質問・要望","question":"やはりその医療的ケア児が１８歳に達し、支援に対して、そういう取組というのはすごく法律としても求めているというところになると思うのです。実際にそれが変わっていないので、そこのところは、その点についてもどう考えられるのかもお聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"今、障害者の相談員が訪問する際に、障害者やご家族のニーズを把握して支援を行っているところです。令和９年度に移転拡張予定のピッコロにつきましては、医療的ケアの程度が重篤な方についても受入れができるよう整備を進めているところです。","id":"exchange-095"},{"speaker":"鈴木委員","kind":"質問・要望","question":"家にいたきり、もう１８歳の若さで家にずっと閉じ籠もらざるを得ないというのを余儀なくされてしまうわけではないですか、そういう施設がないために。今年こそ何とかしてほしいという願いを伺っているのですけど、令和９年度というのは、その点についても確認させてほしいと求めました。","respondent":"松山障害者支援課長","answer":"様々、その方のご事情によって、過ごし方は変わってくるものと考えています。令和９年度に移転拡張のピッコロについては、人工呼吸器のご利用者が受け入れられるように今、具体的に整備を進めているところです。","id":"exchange-096"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それでピッコロでは、呼吸器をつけた方も受け入れられる方向で整備をしていくということで確認させていただいていいですね、その点が一つ。そこのところは、そこの方針を明確にした上で整備をしていただきたいと思うのですけど、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"ですので、高度な医療支援の対応というのは難しいところです。定員数の拡充を図って、安全安心に通所できる場というものを整備していく、その方向性でおります。","id":"exchange-097"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どうか分からないみたいな、そんな感じだと、ちょっと安心できないではないですか。そういうことでピッコロというのは整備しますというところで、確認させていただきたいのですけど、その点は確認できないか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"現ピッコロよりも約２.５倍広くなりますので、現在、今以上に広くなるということもあります。そこの部分も含めて、今後十分検討していくことになります。","id":"exchange-098"},{"speaker":"鈴木委員","kind":"質問","question":"は人員体制が、ここを委託される事業所がそういうことで配置をしますよということで、区との協議が整えば人工呼吸器の方も受け入れる。区としては人工呼吸器の方も受け入れるという方向で事業者と話合いを進めていくと、そういうことでよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"そういった中で、事業者としても努力しながら通所を継続しているということはあります。やはりノウハウがありますので、高度な医療的ケアに対応できるスキルのある看護師を確保ということで、お話は進めているところです。","id":"exchange-099"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最後に要望だけ。ほかの自治体でも話を伺って、本当にかなりの重度の方まで受け入れているというのは実態としても伺っておりますので、ぜひ今回のピッコロでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"ひがし委員","kind":"確認","question":"令和９年度になりますけど、そのときには、きちんとした場所の確保と人員の確保に向けて区としても取り組んでいるという認識でよろしいでしょうか。その１点を確認したいと求めました。","respondent":"松山障害者支援課長","answer":"確かにおっしゃられるとおりで、健康状態が落ち着いていればというところで、区としては、人工呼吸器の方を受け入れるような具体的な整備を進め、あとは人員配置というのも確保に向けて協議をしているところです。","id":"exchange-101"},{"speaker":"ひがし委員","kind":"確認","question":"この設備面ですか、電源の確保というところはもう重要だから、ここについても整備をしているということでお話は聞いております。今、看護師でしっかりと人工呼吸器を使える方がいないと、その守る会と協力をしながら人材確保に向けても取り組んでいるということでよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"委員おっしゃられるとおり、やはり医療的ケアの実施というのは看護師が行うのが基本になっています。医療的ケアの高いスキルのある人材の確保が必要になってきておりますので、現在、運営事業者に相談しながら人材の確保に努めているところです。","id":"exchange-102"},{"speaker":"ひがし委員","kind":"質問","question":"ということはまだ具体的なところというのはこれからで、看護師の人数とかというところもこれからということか尋ねました。","respondent":"松山障害者支援課長","answer":"理学療法士がＰＴで非常勤が週に２回の方が１人、医師が非常勤で月に３回ということで１人配置しておりまして、かなり手厚く支援をしております。","id":"exchange-103"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点については要望をします。進めていくべきかなというふうに思いますので、ニーズを把握できるように、ケア方法についてはぜひ前向きに検討してほしいと求めました。","respondent":"松山障害者支援課長","answer":"医療的ケア者の人数把握についてのご質問です。なかなか、それを個人の突合がどの程度できるかということになってまいりますので、可能な限り把握することに努めたいと考えています。","id":"exchange-104"},{"speaker":"ひがし委員","kind":"質問・要望","question":"聞いて分かるか、必要性とニーズと必要な政策というところも導けるかなというふうに思いますので、ぜひ皆さんで協力してやっていけたらなと思います。こちらは要望で終了とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"こしば副委員長","kind":"質問","question":"看護師の方の負担、またストレス等も考えると、やはりこういったことは医療機関で行うべきところが大きいのかなという認識をいたしました。これからまたさらにこの八潮のほうの環境整備も進めていくですので、こちらのほうに期待をしたいと考えまして、今回の陳情については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"こんの委員","kind":"確認","question":"品川区としては受入れの課題と思っている点が確認され、また、運営事業者とも協議をされている。よって、これは不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"ひがし委員","kind":"質問・要望","question":"それで、不採択でお願いいたします。大変重要だと考えていますので、その点に向けても、前向きに協力しながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私も、１か所も通所できる場所がないということで、通所の場所をつくっていただきたいということはずっと求め続けてきたものです。これは本当に切実な要望のご相談をいただいているので、何としてもこれを実現させていただきたいと強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"筒井委員","kind":"質問","question":"理由といたしましては、区としても課題を認識されている、そして、今後その整備をされて、方向性としては受入れの方向性ということであります。ただ、人材確保の課題や、その直ちにというのが現実的に困難という事情もありますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"おぎの委員","kind":"質問・要望","question":"でも１８歳以上は、本人が希望しているのであればいいのですけれども、仕方なくそうなっているなら整備を進めるべきだとは思っていました。もう既にやるということですので、これに関しては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出します。区としても前向きに動いていただけているとは思うのですけれども、さらに後押ししたいという意味で、採択というふうにしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3676#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":83190,"voices":357}},{"id":"r05-20231127-8","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"建設委員会","time":"午前１０時００分～午後 ４時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を128件整理しています。","topics":[{"id":"topic-01","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出等 建設委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出等 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"利用が増えているということで、利用が増えた要因をどのように分析されているのか、伺いたいと思います。それと、第二戸越幹線のほうでは、今回、この工事が遅れた理由ですね、そこのところを伺いたいと思います。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"事業開始が令和３年１１月２９日からということで、それで今回、昨年度を上回る実績になっていると考えております。今回のシールド工におきまして発生する残土については、掘削した場所からポンプ圧送で地上まで持ってくるような方式を採用しております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今年度からですか、生活保護の方は４万円に下げられたと聞いておりますけれども、昨年と今年とで教えてほしいと求めました。こうしたことは事前に想定することができなかったのかどうかというところを伺いたいと思うのですが、５億円、伺いたいと思います。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"令和５年度は、４３件ということで、決して減っている状態ではないと考えています。なぜ金額を変更したのかですが、他の属性の方々に比べると、他の属性の方と金額差をつけることとしたものです。土質の状況は把握していたところでしたが、想定以上に細かい砂が分布していたということで、こういった状況になってあります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅改善工事助成も区民が利用できるように補正予算を今回組むべきだったのではないかと思いますが、いかがでしょうか。なぜ補正を組まなかったのか、伺います。","respondent":"竹田住宅課長","answer":"住宅改善工事助成ですが、こちらは毎年当初予算のほうで増額しておりますので、今回、１０月に打切りとなったですが、昨年も１０月でございました。当初予算で対応しておりますので、補正のほうは今回しなかったという結論です。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"昨年も１０月で受付終了になってしまっているということでは、当初予算として増額しているということですけれども、やはりそれでも足りていないということだと思いますので、そこは補正を組んで利用できるようにしていくということが必要だと思いますが、改めて伺いたいと思います。","respondent":"竹田住宅課長","answer":"年度によっては２月末まで執行されている年もありますし、たまたま今年度と昨年度は人気のため早めの終了になったと考えておりますので、今回は補正を行わなかったです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"その分、補正すればそれで対応できると思いますので、そこはぜひやっていただきたいと。これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"１件に対して１００万円ですか、１件に対して補助額１００万円と言っていたと、間違っていたら言ってください。その方々のご理解というのはどのような傾向になっているのか、説明を求めました。","respondent":"竹田住宅課長","answer":"連携ですが、区内に大きな不動産団体が２つありますので、そして登録事業者になっていただいているです。こういった方々にもご理解をいただきたい、あるいは不動産事業者の方にはご協力いただきたいと考えて、行っている事業です。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"協力しながら変えていただきたいと考えていますが、ひとり親世帯、低所得者に対する住宅問題というのはますます増えてくると思うのです。やりますよ、安心してねというようなメッセージが必要だと思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"委員ご指摘のとおり、対象の方、こういった事業の重要性というのはますます増してくるものだと考えています。平均１３年ぐらい、高齢者等の方々にも賃貸住宅にスムーズに入居できるようなスキームといいますか、行動を今後も考えていきたいと考えています。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"それなりの金額ですか、予算を立てていただきたいと要望したいと思いますが、後でそのお考えをお聞きします。もうちょっと計画的に様子を見ながら設定できなかったのだろうかという、そこだけ説明を求めました。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"来年度予算ですが、今年度は実績が増えておりますので、来年度予算は増額する形で、財政部門とも、今、折衝しています。福祉部門とはしっかり連携して、お住まい探しに困る方がないように… 当初どのように考えていたかというところだと思いますけれども、通常どおり進めば、こういった補正をさせていただいたというところになります。","id":"exchange-008"},{"speaker":"田中委員","kind":"提案","question":"第二戸越幹線の関係で何点かお伺いしたいと思います。８月１６日に専決処分をした時点で、今回やむを得ずの延長というご提案になったのか、お聞かせほしいと求めました。","respondent":"北原河川下水道課長","answer":"最初が８月１７日という形になっておりまして、今回どうしても年度内が難しいということで延伸をさせていただいているものでございまして、前回の時点では想定ができなかったというものになってあります。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"前回は９１日という形での具体的な延長日程が専決処分されましたけれども、今回は令和６年度中ということであります。第１四半期だから、６月末までぐらいには完了する見込みだというご判断なのかなと思えるのですけれども、お聞かせほしいと求めました。","respondent":"北原河川下水道課長","answer":"今回、補正予算を議決いただけたその後に、工期の延伸、契約の変更等の手続を進めていくという形になります。委員おっしゃいます延長に伴う全体の影響というのはもちろんあると認識していますので、今後、検討していかなければいけないと考えているところです。","id":"exchange-010"},{"speaker":"田中委員","kind":"提案","question":"先ほどのご説明のように、ここを両方一緒にしてしまうこと、これはぜひ分けてご提案をいただくべきだったのではないかなと思います。我々としてはご提案いただいたものに対して捉えるべきなのか、あるいは補正予算ということなので議決を求められているのかというとの意見を述べました。","respondent":"北原河川下水道課長","answer":"そしてその後に契約変更、増額の変更を行いますので、専決処分になった場合も別途ご報告するという形になります。なお、前回、限りなく次回は議決が必要になる可能性が高いのかなと思っているところです。","id":"exchange-011"},{"speaker":"田中委員","kind":"提案","question":"令和６年度でのまた、そういうご報告、ご提案をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"令和４年度と令和５年度、１０月までになりますが、それぞれ対象者の件数を確認させてほしいと求めました。見通しが立ちつつあるというようなお話もあったので、大体何ｍぐらいなのかというところが分かれば、教えてほしいと求めました。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"今年度が２、昨年度が８０で、今年度が現在４３となっています。 シールドが大体９６０ｍぐらいあるのですけれども、そのうち６００ｍを超えたぐらいのところでこういった現象になってあります。今、少しずつ改善されてきてはおりますが、どこまで続くかというのは、分からない状況にあります。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"住宅確保のほうは、数字を確認させていただきました。なぜ今からご答弁いただくような店舗数にとどまっているのか、そこをもう一重、確認の意味でご答弁をほしいと求めました。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"各店舗の入り口等に貼っていただくステッカーを制作しておりまして、図案のほう、どれでいくかというところで最終的な検討をしています。配慮が必要な方々が、そういうきっかけにしていただいて… 西品川一丁目の大崎ガーデンタワーの前の付近になります。","id":"exchange-014"},{"speaker":"まつざわ副委員長","kind":"質問","question":"何といえばいいのですかね、もっと広報に努めるというか、そういった予算分というのはこれには入っていないのか。入っていないのなら、そういった周知の部分もしっかりしていくべきではないかと思いますけれども、そこら辺を説明するよう求めました。","respondent":"竹田住宅課長","answer":"許可する・しないということの決定権はオーナーのご決断というところで、オーナーの意向というのは大きなポイントだと考えております。ただ一方で、当面は不動産事業者のほうに積極的に働きかけ等を行いまして、当面はそういう方策で進めていきたいと考えております。","id":"exchange-015"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"は不動産業者で、例えばチラシなんかをつくって、そこが大家に理解できるようなことが区で後押しできればいいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"令和５年請願第１６号、リニア新幹線の建設中止を求める請願","agenda":"令和５年請願第１６号、リニア新幹線の建設中止を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"先ほど少し説明されましたけれども、ＪＲ東海から説明を受けているのかどうか、先ほどの説明からもう少し詳しくご説明ほしいと求めました。この間、それは把握されたのかどうか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目の今回の停止の理由ですが、その大きな圧力がスキンプレートを押し、変形させたものと認識しております。７月の段階で１２４ｍの地点になった、もともとの予定がこの時点でございまして、このような事象が発覚したです。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"どういった事態になってしまったのかと思うのですけれども、想定しているところがあれば、伺いたいと思います。このカーブのところで掘り進めていったときに、また止まってしまうということが起きてしまうのではないかと危惧されますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"その中で、今回７ｃｍ程度のへこみが発見されたですので、点検は予定どおり行ったのかなと考えています。先ほども申しましたが、こちら、地盤改良体を連続配置することで元の地盤強度に戻すことを目的にやっているものと認識しています。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"区はほかのところで起こっていることも把握されているかどうか、伺いたいと思います。生活がままならないということが起こっておりますので、品川でもそうしたことが起きてしまうのではないかと危惧されますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"ご質問の１点目ですが、そのような事象にならないように、ＪＲ東海に対して引き続き安全対策を求めているものです。そうならないように、極力抑えられるように、事業者に求めていくものです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"実際、品川で掘り進めていって、陥没ですとか空洞が起こったら、区はどうするのか、伺いたいと思います。やはりこれは中止すべきだと思いますけれども、実際起こったときにどうするのかということと、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海の責任の下に実施されている事業であることから、区は引き続き必要な安全対策を確実に行い、丁寧な取組を事業者に求めてまいります。２点目に、区の対応といたしましては、まずは情報共有をしっかり関係各所で連携するということがまず最初に始まるものと認識しています。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"そうしたところで７時半から８時半までは運行を停止するということですが、夕方の下校時など、伺いたいと思います。そして、工事車両が６００台通行することで、道路の状況に悪影響はあるのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の中で２４時間の施工を行っていくということは近隣住民の皆様にも周知しておりまして、その中で、運搬はしないというところになってあります。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"当初の工事説明会では１時間当たりというのは出ておりませんので、区としてはどのように考えているのか、認識を伺いたいと思います。夕方の運行停止については特に聞いていないということで、区としてはそれで安全確保されていると考えているのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"交通に影響が出ることに対しての区の認識ですが、緊急車両や公共交通の運行に影響が出ないように極力配慮しているものと認識しています。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"２回もストップしているという中で、ぜひ区としてもそれについて説明会を求めてほしいと求めましたが、いかがでしょうか。区としてもそうした対応でよいと考えているのか、これが丁寧な説明と言えるのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の件ですが、今回の事象への対応も含めて、周辺にお住まいの皆様へ説明すると伺ってあります。そういった説明をして区民の不安払拭を果たすことが本来の目的ですので、説明会の開催ということにとらわれずに、丁寧に取組を求めてまいります。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"それはそのとおりで、心配な人がかけてくるだけで各計画地の方の不安が払拭されると、そう考えているのか、伺います。資料の中にも、必要の都度、お知らせをしているということで言われておりますけれども、その必要の都度とはどういうときなのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"先ほども申したとおり、質疑を受けることに対して、会を開くまたは個別で対応するというところが本来の目的ではないと私たちは思ってあります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"工事をストップした場合も当たるのかどうか、実際に今回お知らせをしているのか、伺いたいと思います。やはり説明会も含めて、やっていくということが必要だと思いますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"１０月６日に公表いたしました今回の事象に関しましては、こちらは行っておりません。もう１点、そのようなことが実際に起きているかどうかというのは認識していないのですが、繰り返し求めているものです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"意見","question":"今回の工事が止まったことは配布していないということで、必要の都度、チラシを配ったり、住民の方にお知らせされていないなと思いますので、やはり説明会を実施すべきだと意見を述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"なので、この表だと、いや、説明していますよと。これはＪＲ東海の話ですから、やはり疑問を呈してほしいなと思うのですが、その辺の周知徹底についての認識を説明するよう求めました。","respondent":"大石まちづくり立体化担当課長","answer":"区としてどこまで考えているかというご質問でございましたが、シールドの両端から４０ｍずつ、全長で言いますと約１００ｍの範囲になるかと思います。もう１点、すぐアクセスできるようなやり方というのは、新たにＪＲ東海に求めてまいりたいと思います。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"１００ｍというのは、もうちょっと広げなければならないのではないかという、その判断はいかがでしょうか。結果はどうであれ、しっかり分かるようにしてくれという要望はやってほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"重大な事故だとか、そういった事象が発生した場合は、当然その規模に応じて周知する範囲や方法等は変わってくるものと認識しています。具体的にどこまでやるのかというのはＪＲ東海からは聞いておりませんが、区としてはそういった認識を持っているところです。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"説明する場所のエリアというのが本当に今の状況でいいのかどうかという判断は、やはり品川区のほうで持っていただきたいなと思います。なので、それは今回の請願が出たということをきっかけに、ぜひＪＲ東海には申し入れをしていただきたいと、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"配られた資料の中でも、説明会の案内チラシ、周知チラシ、いろいろやられています。引き続きＪＲ東海へは、さらなるそういった周知の徹底というか、もっと見やすさを求めるということは続けていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、区民の生活を脅かすような、そういう工事はしてはならない。あくまでも安全第一で、そして地元の方々、区民の方々に丁寧な説明をしていただくように、区のほうでも取り計らっていただきたいと求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"のだて委員","kind":"意見","question":"建設を中止すべきです。住民に説明すべきですし、そして丁寧な説明もされていないと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"請願項目の２番は、住民説明はこれでも足りないぐらいだと私は思っておりますので、お気持ちは私も非常に共感するところがあります。ただ、１番目のところは、建設中止というふうには今の状況としては言い難いなということで、本日は不採択ということにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそこに森澤区長も参加していただけるように進めていってほしいと求めましたが、いかがでしょうか。新たな意見が出ているという書きぶりかなと思ったのですけれども、こうした意見が出ていることを区はどのように捉えているのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"区長の参加ですが、まずは事務分掌にのっとって、都市開発課のほうで対応していきたいと考えています。区といたしましては、今後のこういったまちづくり、または商売の継続、そうしたことを含めて、総合的に注視していきたいと考えております。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、今のままでいいのではないかという意見が出ているということなのか、そこのところを伺いたいと思います。テレビなどでも紹介されますけれども、こうした東小路の歴史的・文化的価値を区はどのように考えているのか、伺います。","respondent":"中道都市開発課長","answer":"これは、今後どうしていこうかということは話合いが行われているということとか、そういった意識を持っているということは認識しています。一方で、安全というところの今後の権利者の方々の認識というものを、区としては注視していきたいと考えております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"そうした中で再開発が進められようとしてきたわけですけれども、再開発でないと安全なまちづくりはできないということなのか、伺います。この間、繰り返し出されていますけれども、そうした必要な暮らしを奪うものだという自覚があるのかどうか、伺います。","respondent":"中道都市開発課長","answer":"はそういったことは重要と考えておりますけれども、やはり安全・安心といったところのまちづくりというところも非常に重要と考えています。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"まちの方々に話してほしいということなのですが、こうした再開発を永久に中止してほしいという声が出てきているということだと思います。この再開発によって暮らしが奪われてしまうということを品川区は認識しているのか、伺います。","respondent":"中道都市開発課長","answer":"その権利を今後の再開発が終わった後も維持することができますので、その中で、新しい建物の中で住み続けていただければと考えています。そこにまたお部屋を借りて住み続けられるといったところなどを、指導とか、またはそういった調整をしています。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"るる説明がありましたけれども、再開発というのが権利は残せるというお話でしたが、再開発が進んでいけば、住み続けたいと願っても強制的に所有権を奪われてしまうものだということを区は認識していると思いますが、そこを伺いたいと思います。","respondent":"中道都市開発課長","answer":"所有権を奪われてしまうというところなのですけれども、従前に権利を持っている方々というのは、権利変換の中で、従後も権利を持つことは可能という認識です。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"従後も権利を持つことはできるというお話ですが、それまでには１回権利を奪われると。こうした再開発はやるべきではない、私も中止すべきだと思いますけれども、改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"繰り返しになりますけれども、従前に権利を持っている方々は、権利変換の従後ですね、権利変換を行った後に、従後も権利は持ち続けるです。オーナーの方々とのお話合いの中で従後というのは決まってくるという認識ですが、一丁目一番地、区としては組合に対して調整をしています。","id":"exchange-039"},{"speaker":"のだて委員","kind":"意見","question":"やはりその場に住み続けることはできないということですので、Ｃ地区での再開発はやめるべきだと述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"このＣ地区に関しては、一応エリアというのは決まっているのですけれども、この中で分割的に考えることというのは可能なのでしょうか。安全というひとくくりでもくくれないし、いろいろな思いがあるので、ここは分割していろいろと開発を進めるという制度はないのか尋ねました。","respondent":"中道都市開発課長","answer":"再開発といいますか、まちづくりを進めていきたいという方々が集まった地域が、この地域だというところになります。地域の方々がこれを拡大するのか縮小するのか、そういったところは今後の話合いを継続した中で、またさらに練られていくのかなと考えています。","id":"exchange-041"},{"speaker":"西本委員","kind":"提案","question":"提案できないものなのか、そういう仕組みがつくれないものなのかと思っているのですが、何かございませんか。現状を説明するよう求めました。","respondent":"中道都市開発課長","answer":"では、それで必ずしも市街地再開発事業ができるかというところは、またそこは検討が必要なのかなと考えています。事業者に対しても総合的な、いわゆるウィン・ウィンの関係性といったものをどのように構築していくのかというところが重要かなと考えております。","id":"exchange-042"},{"speaker":"西本委員","kind":"提案","question":"このままではいけないという思いは皆さん一様に考えているわけですから、そこを、もっと広い意味での開発の進め方。そこをアドバイスしながら、そういう仕組みをぜひ推進してほしいと求めましたが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"Ｃ地区におきましては、現在、まちづくりというようなご相談は区のほうには来ていないところです。一方で、地域の方々が都市開発課に来られましたら、そこの部分につきましては丁寧に対応していきたいと考えております。","id":"exchange-043"},{"speaker":"西本委員","kind":"意見","question":"既にそういうところを実践した、実績を上げている自治体もある。そういう地域にしようよなんていうふうに持っていけたらいいなと強く思いますので、ぜひお願いをして、意見として申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の再開発は永久に中止を求めるという陳情者のご要望なのですけれども、行政として、法治国家の下では行えないのだろうと思います。再開発は永久に中止を求めるということも、できないと思いますが、確認でご答弁をお願いしたいと思います。","respondent":"中道都市開発課長","answer":"先ほど再開発の意義といったところをご説明しましたけれども、そうした様々議論を経て、区のほうで永久的に中止という決定はできないと。地域の方々と様々議論を重ねて、再開発をするように持っていくという流れで今まで来ているです。","id":"exchange-045"},{"speaker":"田中委員","kind":"意見","question":"一方で、西本委員も少し触れられましたけれども、９月下旬に火災がありました。たまたま９月下旬の火災はそれほどの被害はなかったわけですけれども、住民の合意の下で、再開発を進めていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"まつざわ副委員長","kind":"意見","question":"お話のとおり、住民同士の話合いというのが本来の在り方であって、行政はサポートする側と私は認識しております。その中で、品川区としては十分な話合いのサポートをしているという私の認識ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。こういうことも１つのきっかけにしながら、別の方向に行くのか、そのために区はしっかりとサポートしていただきたいという趣旨です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。住み続けたい住民を追い出すこのＣ地区の再開発は中止すべきですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。で、話合いもまた必要であると考えていますので、そういった視点からも不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"クロス集計では、ルート直下での声ですとか、回答内容を公表するのかというところを伺いたいと思います。１２月をめどに結果を公表予定だということですけれども、どういった中身になるのか、伺います。","respondent":"辻広報広聴課長","answer":"設問ごとに、どの地域で、どういった意見が多いということを集計する予定です。そちらも公表する予定です。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"ある意味、目的といいますか、そのようなところを伺いたいと思います。そうすると、１２月にはクロス集計のところまでということでしたので、その後の公表は、どういったスケジュールになるのか、伺います。","respondent":"辻広報広聴課長","answer":"ほしいの前に来る単語を合わせて、こういったことを要望している方が多いとか、そういったことを何回かやり直しながら考えていくです。１１月以降のスケジュールですが、年明けに全体のものを公表していくという、そのような予定になっております。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"年明けに公表していくということで、年度内か、それとも来年度になってしまうのかということも分かれば、伺いたいと思います。こうしたアンケートの経費の内訳を教えてほしいということで求められていますけれども、実際、ぜひご説明いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"アンケートに寄せられた声は、区長が国に直接届けるということになるのか、ぜひ届けてほしいと求めましたけれども、いかがか尋ねました。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"総価契約ですので出してはいないのですが、内訳の中で、郵便物の印刷や封入・封緘が発送作業で４,２８１万９,０００円。回答の受領、全体での流れですので、この中で郵便料金が幾らになるかというのは計算はできないところです。 なかなか断言はできませんが、全区民アンケートを受けてという趣旨から考えれば、やはり区長に直接行っていただくということになろうかというふうに考えてあります。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"それが分かるようにしていただきたいということと、区民の被害をなくすようにしてほしいと求めましたけれども、いかがでしょうか。区民の安全安心な生活が壊されているということですので、やはりそれも国に伝えてほしいと求めましたけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"羽田新飛行ルート運用開始以降、区民の方からは、区のほうに直接様々な声を寄せていただいているところです。区民の負担軽減につながる取組を、区としてもしっかり国に届けていきたい、働きかけを行っていきたいです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ中止をしていただきたい、そういう立場で求めてほしいと求めましたけれども、いかがでしょうか。そして、自由記述欄については、これは公開をするということでいいのか、そこを確認させてほしいと求めました。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"自由記述欄、基本的には、報告データとして出すように、今、検討しています。ただいま検討しています。国策として国の責任で行われているものですが、区としては、これまでも落下物あるいは騒音環境軽減に向けた取組を国に求めてきたところです。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"しっかり意見聴取できるようなことを工夫してくださいという要望書を出したのですけれども、それがどこまで反映されましたかということです。区の考え方をまとめなければいけないと思いますが、いかがか尋ねました。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"１件ずつ確認しないと、目検で見なければいけないかなというふうに考えておりまして、一定程度の時間をいただくかなというふうに認識しております。障害者の支援センターですとか… 分析したものを、より伝わるような形で国に届けるということは、一定程度必要なのかなというふうに考えてあります。検討していますが、実施状況については、実施後にしっかり区民の方に公表してまいりたいというふうに考えてあります。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"区民の方からの意見をこういうふうに捉え、これからの品川区としての考えはこういたしますというぐらい、はっきり区長が言うべきだと思うのです。それを踏まえて、国のほうに申し上げるという形にしてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"しっかり区として検討して、結果については、しっかり区民の方に公表していきたいです。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"だったら、その結果に基づいて、こういうふうに捉え、だから品川区の見解はこうだというものをまとめていくべきではないのですか。どういうふうに表現していくのかとか、きちんと議論する場が必要なのではないでしょうか、それはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"正に区民アンケートの結果、区民の声に基づいて働きかけを行っていくですので、そこはしっかり区として検討して、しっかりつくり上げて働きかけを行っていきたいです。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"押し問答になりますので、強く強く要望したいと思います。４番目、当たり前ですよね、これ、詳細を出さないと、みんなの税金を使っているわけですから、詳細に出さなければいけないと思います。","respondent":"鈴木都市計画課長","answer":"２番の集計、このアンケート結果を踏まえての国への働きかけは、しっかり行っていきたいです。経費についても、先ほど、広報広聴課長からご答弁申し上げたとおりです。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、この団体の方々が１軒１軒回っているのです。本当にこれはありがたいなと私は思っていますが、ぜひこれからのアンケートの集計、分析はしっかり考えていただきたいと意見を申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"非常に議員として恥ずるべきものとして私は受け止めるべきだと思いますし、今現在、私はそのようなことで受け止めております。それをどういう形で求めてこようとされているのか、求めようとされているのか、そこを１点だけお聞かせほしいと求めました。","respondent":"辻広報広聴課長","answer":"区民アンケートということで、羽田新飛行ルートのことも含め、区民の方の生の声を全員の方に細かくお伺いしようという趣旨で実施したところです。次の施策に反映する上で、また皆様にご相談をするという、そのような内容になるかと考えています。","id":"exchange-062"},{"speaker":"田中委員","kind":"提案","question":"いろいろなご提案が区長からあるかと思いますので、様々な議論、意見を述べすることになるかと思います。それをどうするかということに関しては、議会に対してどういうご提案があるのか、４０分の１の議員としては対応していこうと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば、賛成、反対、特に反対される方は、どこの部分で反対されるのかということを明確にお願いしたいと思います。どういうところが不備があったのか、どういうところは賛成するのかということをしてあげないと、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"まつざわ副委員長","kind":"質問","question":"全体の郵便の金額の中で、郵便料金は細かくは計算できないという話もお聞きいたしました。それを踏まえて、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"その責任の中で、しっかりと国に対して区民の声を届けるということを最後までしっかりと行っていただきたい。それは申し述べる機会もあるのだろうというふうに思っておりますので、そういった意味で、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"木村委員","kind":"意見","question":"国がやろうとしていること、あらゆることに対して品川区は何ができるのか、それに対してはしっかりとこれから議論をしていくべきだと思っています。現在は不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"のだて委員","kind":"意見","question":"そうではなくて、住民の運動の１つの成果だと私は思っておりますので、アンケートを実施することはいいと思います。区民にぜひ公開すべきだと思いますし、区長が自ら行動すべきだと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"聞いていますと、この１番から４番のこの４つの項目に関しては、皆さん賛同していると私は見受けられました。本当は採択という形で認めていただきたいところではありますが、意見として最後に申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すべきということで、理由は先ほど申し上げましたけれども、区民アンケート調査結果を踏まえた意見は議員として述べるべきではない、取り扱うべきではないという視点から、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問","question":"こうした声を受けて、区はどのように受け止めているのか、伺いたいと思います。この２つの再開発、１年以上たっているということになりますけれども、そうした理由を伺いたいと思います。","respondent":"中道都市開発課長","answer":"今まで準備組合が地域の方々に説明なりしておりますけれども、こうした中で権利を持っている方を追い出すといったことは発言はしておりません。その資料も区は確認しておりますので、そうした事実は特にないというふうな区の認識です。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"実際に進めるかどうかというところも検討されているというご答弁でしたけれども、そういった検討はされているのかというところを伺いたいと思います。そうしたことがやはり追い出すことになると私は思いますけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"まちづくりに対してより多くの方の同意をもって進めていきたいというところで、今現在、お話合いまたは検討がされているところです。床面積の価格は、やはり従前に比べれば、一定程度高くなるということはありますけれども……。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"私は言えないと思いますけれども、そこを伺いたいと思います。先行して行われた２つの地区がありますけれども、個人情報を理由に公開しないということで、なぜこれが個人情報に当たるのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"都市再開発法の中で手続が行われているものですので、区としましては、そこの部分は法令に遵守して進めていきたいというふうに考えてあります。法律の在り方につきましては、国のほうで議論されるべきものという認識です。","id":"exchange-073"},{"speaker":"若林委員","kind":"意見","question":"委員長、もう１回。ぜひ、この委員会の質疑が円滑に進みますように、適正な委員長としての職権を発揮してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところは努力をしてほしいと求めましたし、選べる自由がありますよということで書いてあるということなのか、伺いたいと思います。やはり一番住民に身近な自治体としても、こうした姿勢でいるのはよくないというふうに思うのですけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"実際に戻ってこられた方が、土地所有者が２名と、また、借地権者は７５名の方が戻ってきたというところで、８８％です。区といたしましても、繰り返しになりますけれども、より多くの方に同意していただきたいというところで進めていきたいというふうに考えております。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"その中で商店街が、パルムビジョン２０２２を作成されたということで、この中身、どういった内容が書かれているのか、伺いたいと思います。今後どうなっていくのかということがやはり心配されていると思うのですけれども、区の認識を伺いたいと思います。","respondent":"中道都市開発課長","answer":"まちづくりにつきましては、地域の方々で進められてきているものという認識ですので、区のほうで中止する考えはございません。ですので、商店街が壊されるですが、そうではなくて、一緒に進んでいるという認識です。","id":"exchange-076"},{"speaker":"のだて委員","kind":"確認","question":"やはり正式には確認をされていないということで、やはり再開発の悪い部分、区の考えを伺いたいと思います。入っているとしたら、住民の発意ということが疑わしくなってくると思うのですけれども、いかがでしょう。","respondent":"中道都市開発課長","answer":"発案者５名ですが、または、その中での理事を務める方は地区内の権利者の方です。ＥＬＣジャパンにつきましては、協議会または準備組合といったときに、事務局を委託されていたというふうに区のほうは聞いております。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、発案者には入っていないということなのか、そこのところを確認させてほしいと求めました。再開発が知らないうちに進められていたというところで、そうした中で進めていくことが再開発だというふうに思うのですが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"どこまで、全員と言われると、なかなか全員には周知は行き届いていないのかもしれません。区は、過去数年からずっと周知は行っておりますので、よりそういったところで地区の様々な方に周知されるように努力していきたいと考えています。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"水面下で再開発が進められて、手続が進められていく。これは武蔵小山だけではないですけれども、こうしたまちづくりというのは、そうしたまちづくりに変えていくということを求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"アーケードはなくなるのですかということと、それから、地権者の中の３分の２が同意すれば再開発は進みますよね。現時点で、この該当する地権者の方々の合意はどれだけとれているかという把握はされていますか。","respondent":"中道都市開発課長","answer":"そこの今後の取り組み方も、今、まちづくりを進めているところです。３分の２以上ありますということ、何かアンケートをとったとか、そういうことではない」との発言あり〕。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"そこは地元の方々が意見交換しながら決めていくということだと思いますので、なるべく存続していただきたいなという、これは私の要望です。今後の進め方について、相関を説明するよう求めました。","respondent":"中道都市開発課長","answer":"３分の２以上ありますということ、やはりそういったお話合いの中で、まちづくりの熟度は上がっていくのかなというふうに区としては認識しています。市街地再開発事業を進めるという段階になった際には、準備組合がつくった計画を見ながら、そういった部分は指導していきたいです。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"３分の２、まだはっきりした意思表示は確認されていないというところでありますが、ただ、これはしなければいけないでしょう、もうそろそろ。ぜひ組合の方々、丁寧に対応していただきたいと考えていますので、指導をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"昨年度４月から都市計画の決定から１年あいている中で、サポートできる範囲で、より多くの区民の声を聞くために動いているというお話も聞けました。引き続きできる範囲は丁寧にやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。商店街の合意形成も曖昧ですし、住民を追い出す小山三丁目第１地区、第２地区再開発は中止すべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問","question":"この陳情書の中から暴言と言われるようなところは読み取れませんし、議事録にも残っていないというお話でもありました。課長のこれまでの発言や委員会でのご様子を伺うと、こういうことを言うような方ではないと確信しておりますので、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"その確認と、不燃領域率が６０％または６５％を超えているところもあるというところで、区の認識を伺いたいと思います。不燃領域率、これ、資料の中では、恐らく２０２１年３月時点のものだと思いますけれども、現在、最新の状況が分かれば伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"今、まだまだ道半ばというふうには認識しておりますので、引き続き建物の不燃化促進等について取り組んでいきたいというふうに考えてあります。そして最後の西大井六丁目に関しましては６５.９％という数値になってあります。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"住民の安全を考えても、それが一番ではないかというふうに思いますけれども、改めて伺いたいと思います。やはり交通の円滑化のために住民の暮らしが壊されるということは、あってはならないことではないかというふうに思いますけれども、いかがか尋ねました。","respondent":"小川木密整備推進課長、鈴木都市計画課長","answer":"個々の財産、皆様の財産がしっかり守られるというような観点もあると思いますので、やはりそういったものを含めて総合的な防災まちづくりはしっかりと行っていきたいというふうな考えです。１.３６の地点もあったりしますが、一端の減少のみをもって交通の円滑化が必要ではないのだというところではないのかなというのが区の認識です。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"私の質問が悪かったのかもしれませんが、不燃化を進めていくことこそ必要ではないかということで伺いましたので、ご答弁ほしいと求めました。特に商店街などを通ったりしますので、そうしたところが危惧されるわけですけれども、そうしたことがないのか、伺いたいと思います。","respondent":"小川木密整備推進課長、鈴木都市計画課長","answer":"面的なまちづくりの観点からですが、委員おっしゃられるとおり、面的なまちづくりの観点からも、この耐震化、また不燃化の促進は、非常に重要なまちづくりというふうな観点で捉えております。 そうした道路が有効に機能していくというところで、防災の観点あるいは通常の交通の円滑化、そうした観点から都市計画道路の整備は必要だという区としての認識です。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"公園や福祉施設を設置できるようにしてほしいということですが、現在のままだと設置ができないということなのか、伺いたいと思います。それまでは暫定活用が可能だということなのか、伺います。","respondent":"鈴木都市計画課長、小川木密整備推進課長","answer":"福祉施設等の諸施設の設置ですが、東京都と連携をして、地域の防災性の向上に取り組んでいきたいです。特定整備路線の実施、不燃化を進めながら、しっかりと進めていきたいです。委員からの最後のご質問で、暫定広場の活用の期間のことをご質問されたかと思いますが、今、暫定活用をしておりますのが、戸越四丁目の用地です。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"令和７年度中ということだと思いますが、そこまでにあと約２年ということですから、１区間のみ５０％を超えているという状況です。改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"品川区で３分の１を占めます木造密集地域の防災性の取組、東京都が進める延焼遮断帯の形成、そうした中で連携をしながら行っているものです。今後も、東京都と、あるいは地域と連携をして、防災性の取組を進めてまいりたいです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"２０ｍの道路で、そうした火の粉などは加味されていないという下で、この道路が重層的になるのかと私は思うのです。ならないと思うのですけれども、やはり区として住民の暮らしを守る責任があると思いますので、中止を求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"そもそも論から教えてほしいのですが、この補助２９号線、これ、もともとは都市開発道路だったのですよね。品川区全域に近いぐらいにもうなっていると思うのですけれども、今後の広がりについて、拡大についてお聞きします。","respondent":"鈴木都市計画課長、小川木密整備推進課長","answer":"１点目の、今、進められているというものです。その部分ごとで開通していくという考え方はあろうかと思いますが、いずれにせよ、最終的には１００％で整備をしていくです。今現在の整備地域内で各種やらせていただいております防災まちづくり事業を、集中的、重点的に行っていこうというふうな考えです。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"補助２９号線が選ばれた理由が、都市計画道路ですか、どうなのでしょうか。私は、住まわれている沿道の方は、ある程度ご理解していただいているのかなと思っているのですが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"鉄骨造であるとか、３階建てまで、１０ｍ以下という範囲の中で建物は計画をして建てることができるというような緩和措置はあります。不燃化に関わる各種事業が行われておりますので、それが優遇措置というような形になろうかと思います。","id":"exchange-093"},{"speaker":"西本委員","kind":"確認","question":"補助２９号線で都市計画道路に面していますというご説明があって建築をされているのではないのでしょうかと思うのです。それを確認したいのと、いずれは返してねということではなかったのかなというふうに思うのですが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"都市計画道路の範囲内にかかっている土地で建物を計画される場合は、都市計画法の第５３条の許可手続が必ず必要になってきます。その中で、先ほどお伝えしたような建築計画の条件がクリアできているかというところが確認されています。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"区がやるのか、多分、東京都がやるのでしょうね。品川区がやるべきものではないと思うのですが、そこはやはり東京都のほうにも、そこからの説明が必要なのではないかと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうした説明はされてきたのかなですが、そうしたところは丁寧に説明いただいていると思うのですが、より丁寧な説明を行っていただくように伝えてまいりたいと思います。","id":"exchange-095"},{"speaker":"まつざわ副委員長","kind":"質問","question":"いろいろな説明の中で、区としても必要と考える特定整備路線、この中において、陳情項目には当てはまらないと考えています。それで、３つ目の暫定活用につきましては、やはりなかなか道路の工事が進まない中、暫定活用は引き続き続けていただけたらと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。住民を追い出し、生活を壊す補助２９号線などの特定整備路線は中止すべきですし、買収用地の活用も進めるべきだと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。先ほども意見を申し上げましたけれども、原点に返って、しっかりそこを説明していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"田中委員","kind":"質問・要望","question":"特定整備路線の必要性は厚く感じておりますし、これは基本的には都の事業でありますので、都が主体的に事業を進めるべきだと思います。一人でも多くの、一刻も早い地権者の理解を得て事業が完成するように、側面からご尽力ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、昨年の９月が最終ということで、この羽田空港のこれからの「ニュースレター」の最終発行はいつなのかというところを伺いたいと思います。まだ６回目が１年以上も開催されていないというところで、説明会を実施すべきだというふうに思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"オープンハウス型説明会、説明を行っていただきたい旨、国は丁寧に説明。教室型説明会については、固定化回避検討会が検討状況でございまして、その検討状況について。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"率直なところで、質問もできたりというところで説明会を実施をしていくということが、いかがでしょうか。ぜひ国としても説明してほしいと求めましたし、それを求めていただきたいというふうに思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"いろいろなご質問にお答えする窓口も用意していますので、区としても、国のほうで直接答えていただくことが一番丁寧なやり方なのかなです。今後の検討会の検討状況、区民の方への説明は、区としては求めていきたいです。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"やめるということが一番だというふうに思いますけれども、区が考える一番の解決策はどういうことか、伺いたいと思います。今回の一般質問で、問題意識があるということは、どういうことなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国が今、実施している固定化回避検討会につきましては、違う方法がないかというところを技術的に検証していただいているところです。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりやめることが一番の解決策だと私は思いますので、ぜひ区としても、中止をするという立場に立っていただきたいというふうに思います。教室型説明会、求めておりますので、ぜひ実施をしていくべきだと意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"いつまで待つのですか、１年間以上。品川区は何もアクションしないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"他区の状況について、行われているかどうかということは、情報として把握してございません。第５回の検討会の資料の中でも、国の回答が、区としては継続して求めていきたいです。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"うがった見方をしてしまうような状況をやっているなというふうに私は個人的に思っているところがあるので、ほかの区はどうなのでしょうか。どうなっているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"固定化回避検討会の実施時期については、区としてもしっかり認識しているところでございまして、第５回目が昨年８月に実施されて以降。しっかりと強く、早急に結果を出していただけるように、区としても求めていきたいです。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"そこはある程度もう決着をつけてもいいのではないですか。もう１年以上もたっているわけですから、やはり区議会として、議会から発言してもいいのではないかと私は意見として申し上げたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"まつざわ副委員長","kind":"質問","question":"国としてのオープン型説明会、そしてまた、１３地区の地域センターでの説明があるとお聞きしました。５回やっていて、説明会という必要性ということもあるのかなということも考えられるという部分で、継続とさせていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"若林委員","kind":"意見","question":"これまで検討会を５回やりまして、今日は区のほうから資料もまとめていただきました。６回目の検討会がそろそろ開かれる時期、しっかりと私どもも注視をしていきたい、こういう趣旨で継続で結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"木村委員","kind":"意見","question":"継続でお願いいたします。これをうまくかみ合わせた新しいルートをつくるべきではないかなと、今回のこの陳情に対しては、継続でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。前回検討会が行われてから１年以上経過していますし、区民に説明がないということで、説明会を開くべきだということで採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"陳情内容については、もう１年以上もたって何の進捗もないということに対して、やはり黙っているというのはいかがなものかと思います。私は、今後、品川区としても強く態度を示していかなければならないということを強調させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"田中委員","kind":"意見","question":"一自治体が言うべきではないという思いは、では、ほかの地域であればいいのだという思いも私はそれは言えないと思います。特に、国会あるいは国土交通省においての判断だと思いますので、そちらにぜひ直接思いをお伝えいただけたらというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"区内で２８９基、どういうところに設置をしているというところがあれば、どこに設置をするかというところを伺いたいと思います。それで、この間、ベンチ、お休み石の設置は、増えてきているのか、減ってきているのかという推移、そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほどご説明したとおり、移動する過程において、街中でひと休みできるようなスペースが必要だというところで設置を進めてきているところです。","id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民から要望があって設置ができなかった場所、そういう要件はあったのかどうか、そこを伺いたいと思います。住民から要望があったところは、どういう場所の傾向があるのか、伺えたらと思います。","respondent":"鈴木都市計画課長","answer":"私、なかなかやはり歩道上のスペースがないと設置できないということでお断りした例はあるのではないのかなというところで、ご自宅から駅に行って。商店街のほうから、商店街の歩道上にお休み石を置いていただけないかという声をいただいた記憶もあります。","id":"exchange-114"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり様々な区民要望があって、バス停のところにはどうかということで伺ったので、そこだけ伺えればと思いますが。最後、１点だけ答弁をお願いします。","respondent":"鈴木都市計画課長","answer":"築造物も設置をして、併せてちょっと座れるスペースも設置されてきているというような状況で、どこそこのバス停に改めて設置していただきたいという。２８９基の区民の方が休んでいただける整備というのは、非常に、そうしたスポットの整備が行われてきたのかなという認識です。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問","question":"設置する条件として改めてお伺いしたいのですが、道路に２２８基ありますが、歩道のない道路上には設置できるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"それぞれの道路管理者の占用許可をとってですけれども、少なくとも今設置しているところで、歩道がないところに設置したという実例はないところです。","id":"exchange-116"},{"speaker":"田中委員","kind":"質問・要望","question":"これは設置はしたくても、していただきたいという要望があったとしても、それはできないのはそもそもの条件だと思います。ですから、要望があれば、そういうことと受け止めております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"木村委員","kind":"質問","question":"どうしても椅子を探しているのですが、１基でも多く椅子が設置ができれば、障害持った方を大変多く見受けます。１基でも多くつけられるようなお考えを、２８９基と言っていましたけれども、そういう点についても説明を求めました。","respondent":"鈴木都市計画課長","answer":"１０基という予定は今のところないのですが、できるだけ設置可能な場所について、しっかり検討して。","id":"exchange-118"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"平成８年度から、区民の皆様の要望から始めたこのお休み石の設置という部分に関しては、ベンチ不足ということはないと感じます。これからやはり維持管理という部分は十分必要になると思いますので、そこら辺のメンテナンスはしっかりとしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"若林委員","kind":"質問・要望","question":"今後もこういう方向性で進んでいっていただきたいなと思いますけれども、ここには区のほうで精査をしというような表現もあります。実態には即しているのかなというふうに思いますので、そういった意味で、この陳情に関しては不採択で結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり２８９基ありますので、できれば区民の皆様方と一緒に設置をするというのは、これからも続けていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。高齢者の方等々の対応ということで設置を求められておりますので、その方向性に合っていると思いますので、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"田中委員","kind":"意見","question":"では、苦渋の決断として、条件はどうしても、設置条件の中では最大限やっていただいているという判断をしますので、不採択でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回の転倒事故や和解に至る経緯を伺いたいと思います。損害賠償額については、慰謝料や休業損害等ということで書かれておりますが、その内訳を伺いたいと思います。","respondent":"森道路課長","answer":"令和５年に入りまして、書類も整い、示談の内容も整ったということで専決処分をさせていただいたところです。内容についてですけれども、治療費とスマートフォンの修理費、それから慰謝料と休業損害ということで、当事者の方から申告をいただいているです。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"今のご答弁で聞き逃したと思うのですけれども、事故が起きた、その相手方から申告があったという理解でいいか尋ねました。","respondent":"森道路課長","answer":"そういったものが全部終わって書類がそろわれて、その金額に対して区のほうの過失の割合を掛けた形で損失の補償額が決まってくるというような形です。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"言い難いところがありますが、その辺の対応はどうされる、やはり言われたらやるという形なのでしょうか。区道の点検は常にやっていただきたいという思いはありますけれども、でもやはり、対応の方法はいかがか尋ねました。","respondent":"森道路課長","answer":"いただいた上で、区のほうでしっかりと対応を誠実にするところですけれども、必ずしも補償が出るということでもございません。段差というのは、そういった部分にある程度気をつけていただいて歩いていただくということも必要なのかというふうに思っておるところです。","id":"exchange-126"},{"speaker":"田中委員","kind":"質問・要望","question":"レンガ舗装に対する見直しまでいくのかどうかあれですが、私はぜひ積極的にご検討ほしいと求めましたが、ご対応をお願いしたいと思います。","respondent":"森道路課長","answer":"２０cm角ぐらいのブロックであったり、歩道部分が水が染み込みやすいとか、そういった部分もあります。レンガの模様をつけたりということもありますので、今後はそういった技術もしっかり使いながら、安全な歩道を整備していきたいと考えています。","id":"exchange-127"},{"speaker":"若林委員","kind":"質問","question":"参考までにお聞きしますが、例えば１m2辺り、維持管理費は大分違うのでしょう。参考までにお聞きして、道路の表面はふさわしいよねという議論の参考にもなるかもしれませんので、お聞きします。","respondent":"森道路課長","answer":"インターロッキングブロックのほうが高かろうというふうに考えておりますし、アスファルト舗装が一番管理しやすいというところはあります。地域の要望でつくっている部分もありますので、周囲の方々のご意見をいただきながら、安全な歩道にしていきたいというふうに思います。","id":"exchange-128"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":89654,"voices":346}}]);
